window.QUIZ={"m08":[{"id":"m08-001","topic":"การเลือกฐานข้อมูล","level":"know","story":"","q":"คำถามสองข้อในสไลด์ที่ว่า \"ต้องการ throughput เท่าใด\" และ \"ขยายภายหลังได้หรือไม่\" เป็นส่วนหนึ่งของเกณฑ์เลือกฐานข้อมูลข้อใด","opts":[{"t":"Durability","why":"Durability ถามเรื่อง data durability, availability, recoverability และข้อบังคับทางกฎหมาย ไม่ใช่ throughput"},{"t":"Scalability","why":"สไลด์ 7 ใช้สองคำถามนี้ประเมิน scalability คือปริมาณอ่าน/เขียนต่อวินาทีและความสามารถในการขยายต่อ"},{"t":"Storage requirements","why":"Storage requirements ถามขนาดข้อมูลรวม (GB, TB, PB) ไม่ใช่อัตราอ่าน/เขียน"},{"t":"Object size and type","why":"เกณฑ์นี้ถามว่าเก็บโครงสร้างง่าย ออบเจกต์ใหญ่ หรือทั้งสองแบบ ไม่เกี่ยวกับ throughput"}],"ans":1,"ref":"M8 · สไลด์ 7–10, 15"},{"id":"m08-002","topic":"การเลือกฐานข้อมูล","level":"know","story":"","q":"ข้อใดเป็นชุดตัวอย่างฐานข้อมูล non-relational ทั้งหมดตามสไลด์ Database types","opts":[{"t":"MySQL, Cassandra, Redis","why":"MySQL เป็น relational (ตัวอย่างในสไลด์คู่กับ SQL Server และ Oracle)"},{"t":"MongoDB, Oracle Database, Redis","why":"Oracle Database เป็น relational"},{"t":"Microsoft SQL Server, MongoDB, Cassandra","why":"Microsoft SQL Server เป็น relational"},{"t":"MongoDB, Cassandra, Redis","why":"สไลด์ 11 จัดทั้งสามตัวเป็น Non-Relational"}],"ans":3,"ref":"M8 · สไลด์ 11"},{"id":"m08-003","topic":"การเลือกฐานข้อมูล","level":"know","story":"","q":"ในสไลด์ Amazon database options ข้อใดจัดบริการทั้งสามตัวเป็นหมวด Relational ได้ถูกต้อง","opts":[{"t":"Amazon RDS, Amazon Redshift, Amazon Aurora","why":"สไลด์ 14 จัดสามบริการนี้เป็น relational (Redshift ใช้ SQL และเป็น data warehouse)"},{"t":"Amazon RDS, Amazon DynamoDB, Amazon Aurora","why":"DynamoDB เป็น NoSQL key-value/document จึงอยู่หมวด non-relational"},{"t":"Amazon Redshift, Amazon ElastiCache, Amazon Neptune","why":"ElastiCache (in-memory) และ Neptune (graph) เป็น non-relational"},{"t":"Amazon RDS, Amazon Aurora, Amazon Neptune","why":"Neptune เป็น graph database จึงเป็น non-relational"}],"ans":0,"ref":"M8 · สไลด์ 14"},{"id":"m08-004","topic":"การเลือกฐานข้อมูล","level":"apply","story":"","q":"ข้อความใดเกี่ยวกับ relational เทียบกับ non-relational ที่ \"ผิด\"","opts":[{"t":"Relational เก็บข้อมูลเป็นแถวและคอลัมน์ และใช้ SQL เป็นภาษาคิวรีหลัก","why":"ถูก ตรงกับตารางเปรียบเทียบ ไม่ใช่ข้อที่ผิด"},{"t":"Non-relational เก็บข้อมูลแบบ key-value, document หรือ graph ได้หลายโมเดล","why":"ถูก เป็นโมเดลข้อมูลที่สไลด์ระบุ ไม่ใช่ข้อที่ผิด"},{"t":"Horizontal scaling คือเพิ่มจำนวนเครื่องแล้วกระจายข้อมูลไปยังเครื่องเหล่านั้น","why":"ถูก เป็นพื้นฐานที่ทำให้ NoSQL รองรับข้อมูลปริมาณมาก ไม่ใช่ข้อที่ผิด"},{"t":"Non-relational ใช้ schema แบบ fixed และ scale แนวตั้งเป็นหลัก","why":"ผิด: ตามตารางสไลด์ 52 non-relational ใช้ schema แบบ dynamic และ scale แนวนอน ส่วน fixed schema/vertical เป็นของ relational"}],"ans":3,"ref":"M8 · สไลด์ 12–13, 52"},{"id":"m08-005","topic":"การเลือกฐานข้อมูล","level":"scen","story":"ระบบ media ของบริษัทหนึ่งต้องเก็บไฟล์วิดีโอขนาดหลายร้อย MB ต่อไฟล์ พร้อม metadata เช่น title, uploader, tag และเวลาอัปโหลด ทีมเดิมคิดจะบรรจุไฟล์วิดีโอทั้งไฟล์เป็นค่าหนึ่งใน record ของฐานข้อมูล แต่พบว่า record ใหญ่ทำให้ query ช้าและชนขีดจำกัดขนาดต่อ record","q":"แนวทางใดเหมาะสมที่สุด","opts":[{"t":"ย้ายไป Redshift เพราะรองรับข้อมูลระดับ PB และ query ได้เร็ว","why":"Redshift คือ data warehouse เชิงวิเคราะห์ ไม่ได้แก้ปัญหา record ใหญ่เกินขีดจำกัดของ transactional store"},{"t":"เปิด Multi-AZ เพื่อให้ standby ช่วยรับ record ที่มีขนาดใหญ่","why":"Multi-AZ เพิ่ม availability ผ่าน synchronous standby ไม่ได้เพิ่มขีดจำกัดขนาด record และ standby ไม่รับ read"},{"t":"เพิ่ม read replica เพื่อกระจายการอ่านไฟล์วิดีโอไปหลายตัว","why":"Read replica ช่วยแบ่งโหลดอ่านแต่ไม่แก้ขนาด record ที่เกินขีดจำกัดและยังต้อง replicate ข้อมูลก้อนใหญ่"},{"t":"เก็บไฟล์ใน S3 แล้วเก็บ metadata กับ object key ในฐานข้อมูล","why":"(เพิ่มเติม) ออบเจกต์ใหญ่ควรอยู่ใน S3 ส่วนฐานข้อมูลเก็บ metadata ที่เล็กและ query ได้เร็ว ตามประเด็น object size and type ในสไลด์ 9"}],"ans":3,"ref":"M8 · สไลด์ 9"},{"id":"m08-006","topic":"การเลือกฐานข้อมูล","level":"scen","story":"ระบบบัญชีลูกหนี้มีตาราง customers, invoices, payments เชื่อมกันด้วย foreign key ต้อง JOIN หลายตารางและต้องการธุรกรรมแบบ ACID ข้อมูลรวมประมาณ 2 TB โหลดเขียนสูงสุดราว 8,000 IOPS ไม่มีแผน sharding และทีมไม่ต้องการดูแล OS หรือ backup เอง","q":"บริการใดเหมาะที่สุด","opts":[{"t":"Amazon DynamoDB เพราะ scale แนวนอนได้โดยไม่มีเพดานตาราง","why":"DynamoDB ไม่เด่นเรื่อง JOIN และ foreign key constraint ซึ่งงานนี้ต้องใช้ และโหลด 8,000 IOPS ไม่ได้ต้องการ scale ระดับนั้น"},{"t":"Amazon Redshift เพราะรองรับข้อมูลหลาย TB ด้วย columnar storage","why":"Redshift ออกแบบเพื่อ analytics (OLAP) แบบ columnar ไม่ใช่ฐานข้อมูล transactional ที่เขียนทีละแถว"},{"t":"Amazon RDS เพราะเป็น relational แบบ managed ที่รองรับ ACID และ JOIN ในช่วง low-TB และไม่เกิน 30,000 IOPS","why":"ถูก: ตรงเกณฑ์ when-to-use ในสไลด์ 35 (complex transactions, ไม่เกิน 30,000 IOPS, node เดียว) และ AWS รับงาน patch/backup"},{"t":"ติดตั้งฐานข้อมูลบน EC2 เองเพื่อควบคุมทุกส่วนของระบบ","why":"ต้องรับภาระ OS patch, backup, HA เอง ขัดกับข้อกำหนด และสไลด์ 76 ใช้ EC2 เมื่อต้องการ OS access เท่านั้น"}],"ans":2,"ref":"M8 · สไลด์ 12, 23, 35, 76"},{"id":"m08-007","topic":"การเลือกฐานข้อมูล","level":"scen","story":"ตะกร้าสินค้าของแอปมือถือเข้าถึงด้วย cartId เท่านั้น (GET/PUT เป็นหลัก) แต่ละ item มี attribute ต่างกัน ช่วงโปรโมชันคาดว่ามี write ถึง 60,000 ครั้งต่อวินาที ทีมกำลังพิจารณา RDS ขนาดใหญ่ที่สุดพร้อม read replica 5 ตัว","q":"ข้อสรุปใดถูกต้องที่สุด","opts":[{"t":"ใช้ RDS ได้ เพราะ read replica 5 ตัวช่วยเพิ่ม write throughput","why":"Read replica รับเฉพาะ read และ replicate แบบ asynchronous จาก primary จึงไม่เพิ่ม write throughput"},{"t":"ใช้ RDS Multi-AZ เพราะ standby จะช่วยแบ่งรับ write จาก primary","why":"Standby ไม่รับ traffic ของแอป ใช้เพื่อ failover เท่านั้น และ synchronous replication เพิ่ม write latency"},{"t":"ใช้ DynamoDB เพราะ write 60,000/วินาทีเกินเพดานของ RDS node เดียว","why":"RDS รองรับสูงสุดราว 30,000 IOPS (อ่าน 15,000 + เขียน 15,000) และ write ไปที่ primary เดียว ส่วน DynamoDB กระจาย write ข้าม partition (สไลด์ 35, 53–54)"},{"t":"ใช้ Redshift เพราะรองรับข้อมูลปริมาณมากและ query ได้เร็ว","why":"Redshift เหมาะกับ query วิเคราะห์ ไม่ใช่ write จำนวนมากแบบ low-latency"}],"ans":2,"ref":"M8 · สไลด์ 35, 53–54"},{"id":"m08-008","topic":"Amazon RDS","level":"know","story":"","q":"ข้อใดไม่ใช่เอนจินที่ Amazon RDS รองรับตามสไลด์","opts":[{"t":"MariaDB","why":"MariaDB เป็นหนึ่งใน 6 เอนจินที่ RDS รองรับ"},{"t":"MongoDB","why":"MongoDB เป็น non-relational ไม่อยู่ใน 6 เอนจินของ RDS"},{"t":"Amazon Aurora","why":"Aurora เป็นหนึ่งในเอนจินที่ RDS รองรับ"},{"t":"Oracle","why":"Oracle เป็นเอนจินที่ RDS รองรับ"}],"ans":1,"ref":"M8 · สไลด์ 24, 50"},{"id":"m08-009","topic":"Amazon RDS","level":"know","story":"","q":"เมื่อใช้ Amazon RDS งานใดที่ยังเป็นความรับผิดชอบของผู้ใช้ตามสไลด์ Managed services responsibilities","opts":[{"t":"Application optimization","why":"สไลด์ 21–22 ระบุว่าผู้ใช้ดูแลเฉพาะ application optimization เช่น schema, index, query"},{"t":"การติดตั้งและ patch ระบบปฏิบัติการ","why":"เป็นงานของ AWS เมื่อใช้ RDS"},{"t":"การทำ backup ของฐานข้อมูล","why":"AWS ดูแล backup ให้ใน managed service"},{"t":"การติดตั้งและ patch ซอฟต์แวร์ฐานข้อมูล","why":"AWS ดูแลเช่นกัน ผู้ใช้ไม่ต้องทำ"}],"ans":0,"ref":"M8 · สไลด์ 21–22"},{"id":"m08-010","topic":"Amazon RDS","level":"know","story":"","q":"RDS instance class ตระกูลใดจัดเป็น memory-optimized และเหมาะกับงาน query-intensive หรือมี connection จำนวนมาก","opts":[{"t":"T family","why":"T เป็น burstable สำหรับงานขนาดเล็กหรือผันแปร"},{"t":"M family","why":"M เป็น general-purpose สำหรับงาน CPU-intensive"},{"t":"X family","why":"ไม่ใช่ตระกูลที่สไลด์ระบุสำหรับงานนี้ สไลด์ระบุเฉพาะ T, M, R"},{"t":"R family","why":"สไลด์ 25 ระบุ R เป็น memory-optimized (สูงสุด 96 vCPU/768 GB)"}],"ans":3,"ref":"M8 · สไลด์ 25"},{"id":"m08-011","topic":"Amazon RDS","level":"apply","story":"","q":"ทีมย้ายฐานข้อมูลจาก MySQL ที่ติดตั้งบน EC2 ไปยัง RDS for MySQL งานใดที่เปลี่ยนจากภาระของทีมเป็นภาระของ AWS","opts":[{"t":"การ rack and stack เซิร์ฟเวอร์ฐานข้อมูลในศูนย์ข้อมูล","why":"บน EC2 AWS รับงานนี้อยู่แล้ว จึงไม่ใช่สิ่งที่เปลี่ยนเมื่อย้ายมา RDS"},{"t":"การออกแบบ index และ query ให้เหมาะกับแอปพลิเคชัน","why":"เป็น application optimization ซึ่งผู้ใช้ยังรับผิดชอบต่อใน RDS"},{"t":"การให้สิทธิ์ SSH เข้า host ของฐานข้อมูลโดยตรง","why":"(เพิ่มเติม) RDS ไม่ให้ OS-level access ไม่ใช่งานที่ AWS รับแทน"},{"t":"patch OS และ DB software พร้อม backup และ failover","why":"ตามตารางสไลด์ 21 บน EC2 งานเหล่านี้ยังเป็นของผู้ใช้ แต่ใน RDS เป็นของ AWS"}],"ans":3,"ref":"M8 · สไลด์ 21–22"},{"id":"m08-012","topic":"Amazon RDS","level":"apply","story":"","q":"ฐานข้อมูลรันบน db.t3 และ CPU อยู่ที่ประมาณ 85% ตลอดทั้งวัน เหตุใดตระกูล T จึงไม่เหมาะกับโหลดนี้ และทางเลือกใดสมเหตุสมผลกว่า","opts":[{"t":"T มี baseline ต่ำและ burst เกินคิดเงินเพิ่ม ควรย้ายไป M family","why":"(เพิ่มเติม) ตระกูล T ใช้ระบบ CPU credit เหมาะกับโหลดผันแปร ส่วน M เป็น general-purpose สำหรับ CPU-intensive (สไลด์ 25)"},{"t":"T มี vCPU สูงสุดเพียง 2 ตัว จึงต้องย้ายไป R family เสมอ","why":"ไม่จริง สไลด์ระบุ T ไปถึง 8 vCPU/32 GB และปัญหาคือ baseline ไม่ใช่จำนวน vCPU"},{"t":"T ไม่รองรับ networking จึงเชื่อมต่อ client เข้ามาไม่ได้เลย","why":"สไลด์ระบุ networking ระดับ Moderate จึงรองรับ ปัญหาอยู่ที่การใช้ CPU ต่อเนื่อง"},{"t":"T เพียงแค่เปิด Multi-AZ ก็จะรองรับโหลดต่อเนื่องได้เพียงพอ","why":"Multi-AZ เพิ่ม availability ไม่ได้เพิ่ม CPU baseline ของ instance"}],"ans":0,"ref":"M8 · สไลด์ 25"},{"id":"m08-013","topic":"Amazon RDS","level":"scen","story":"วิศวกรสร้าง RDS ใน Lab โดยใช้ default security group เปิดพอร์ต 3306 จาก 0.0.0.0/0 และเลือก DB subnet group ที่รวม public subnet ฝ่ายความปลอดภัยต้องการให้เฉพาะ web server tier เชื่อมต่อฐานข้อมูลได้ และ DB อยู่ในเครือข่ายส่วนตัว","q":"การแก้ไขใดตรงตามสถาปัตยกรรมของ Lab 5","opts":[{"t":"สร้าง SG ของ DB รับ 3306 เฉพาะจาก SG ของ web และใช้ private subnet 2 AZ","why":"ตรงขั้นตอน Lab 5 (สไลด์ 44, 48): security group จำกัด source และ subnet group วาง DB ใน private subnet"},{"t":"คง 0.0.0.0/0 ไว้ แต่เปลี่ยนพอร์ตของฐานข้อมูลเป็นค่าอื่น","why":"การเปลี่ยนพอร์ตไม่จำกัด source ใครก็เชื่อมได้ยังเป็นการเปิดกว้างเกินจำเป็น"},{"t":"ย้าย web server ไป private subnet เพื่อให้เชื่อมต่อ DB ได้","why":"ทำให้ผู้ใช้เข้าถึงเว็บไม่ได้ และไม่ได้จำกัดว่าใครเชื่อมต่อ DB"},{"t":"เปิด Multi-AZ แล้วถือว่าการเข้าถึงถูกจำกัดเรียบร้อยแล้ว","why":"Multi-AZ เกี่ยวกับ availability ไม่ได้ควบคุมการเข้าถึงเครือข่าย"}],"ans":0,"ref":"M8 · สไลด์ 27, 44, 48"},{"id":"m08-014","topic":"Amazon RDS","level":"scen","story":"ทีมต้องการฐานข้อมูลเชิงสัมพันธ์สำหรับซอฟต์แวร์เก่าที่ต้องติดตั้ง agent ของผู้ผลิตลงบน host ของ DB และปรับ kernel parameter ระดับ OS ทีมกำลังเลือกระหว่าง RDS กับทางเลือกอื่น","q":"ทางเลือกใดเหมาะสม","opts":[{"t":"Amazon RDS แล้วขอสิทธิ์ SSH เข้า host เพื่อติดตั้ง agent","why":"(เพิ่มเติม) RDS ไม่ให้ OS-level access หรือ shell ไปยัง host ซึ่งเป็นข้อแลกเปลี่ยนของ managed service"},{"t":"Amazon DynamoDB เพราะไม่ต้องดูแล host และ scale ได้เอง","why":"DynamoDB เป็น NoSQL และไม่ได้ให้ OS access ซอฟต์แวร์ relational เดิมก็ใช้ไม่ได้"},{"t":"ติดตั้งฐานข้อมูลบน Amazon EC2 เพราะต้องการ OS access และการปรับแต่งที่ RDS ไม่เปิดให้","why":"สไลด์ 35 และ 76 ระบุให้ใช้ DB บน EC2 เมื่อต้องการ customization/OS access (แลกกับภาระดูแลที่เพิ่ม)"},{"t":"Amazon Redshift เพราะปรับแต่ง node ได้ละเอียดกว่า RDS","why":"Redshift เป็น managed data warehouse ไม่ใช่ที่รันซอฟต์แวร์ที่ต้องติดตั้ง agent บน host"}],"ans":2,"ref":"M8 · สไลด์ 22, 35, 76"},{"id":"m08-015","topic":"Multi-AZ และ Read replica","level":"know","story":"","q":"การ replicate จาก primary ไป standby ใน RDS Multi-AZ deployment เป็นแบบใด","opts":[{"t":"Asynchronous","why":"เป็นกลไกของ read replica ไม่ใช่ Multi-AZ standby"},{"t":"Batch replication ทุกชั่วโมง","why":"ไม่ใช่กลไกของ Multi-AZ เพราะ standby ต้องมีข้อมูลตรงกับ primary ตลอด"},{"t":"Synchronous","why":"สไลด์ 28–29: การเขียนถือว่าเสร็จเมื่อทั้งสองฝั่งบันทึก ได้ durability สูง"},{"t":"ไม่มี replication ใช้ EBS snapshot เท่านั้น","why":"Multi-AZ ใช้ synchronous replication ระหว่างสอง EBS volume ไม่ใช่เพียง snapshot"}],"ans":2,"ref":"M8 · สไลด์ 28–30"},{"id":"m08-016","topic":"Multi-AZ และ Read replica","level":"know","story":"","q":"ข้อใดเป็นเงื่อนไขที่ทริกเกอร์ automated failover ของ RDS Multi-AZ ตามสไลด์","opts":[{"t":"Replication lag ของ read replica เกินค่าที่ตั้งไว้","why":"ไม่อยู่ในเงื่อนไขของสไลด์ และ lag เป็นเรื่องของ read replica ไม่ใช่ standby"},{"t":"ผู้ใช้สร้าง snapshot ด้วยตนเอง","why":"การทำ snapshot ไม่ทำให้เกิด failover"},{"t":"Storage ของ primary ล้มเหลว","why":"เป็นหนึ่งในสี่เงื่อนไขในสไลด์ 30 ร่วมกับ AZ ล่ม, เสียการเชื่อมต่อเครือข่าย และ compute unit ล้มเหลว"},{"t":"ตารางหนึ่งมีจำนวนแถวมากเกินไป","why":"ขนาดตารางไม่ใช่เงื่อนไข failover ที่สไลด์ระบุ"}],"ans":2,"ref":"M8 · สไลด์ 30"},{"id":"m08-017","topic":"Multi-AZ และ Read replica","level":"apply","story":"","q":"ทีมต้องการสร้าง read replica จาก MySQL primary เดียวจำนวน 6 ตัวเพื่อรองรับโหลดอ่าน ผลที่คาดได้ตามข้อจำกัดในสไลด์คืออะไร","opts":[{"t":"Replication lag ของ read replica เกินค่าที่กำหนดไว้ในระบบ","why":"ไม่จริง read replica ยัง asynchronous และมีเพดานจำนวน"},{"t":"ผู้ใช้สร้าง manual snapshot ของ DB instance ด้วยตนเอง","why":"Standby ไม่รับ read และไม่ใช่ read replica"},{"t":"Storage ของ primary ล้มเหลว","why":"สไลด์ 32 ระบุสูงสุด 5 read replica ต่อ primary"},{"t":"ตารางหนึ่งมีจำนวนแถวมากเกินกว่าที่กำหนดเอาไว้","why":"สไลด์ 32 ระบุว่า MySQL รองรับ (พร้อม MariaDB, PostgreSQL, Oracle)"}],"ans":2,"ref":"M8 · สไลด์ 31–32"},{"id":"m08-018","topic":"Multi-AZ และ Read replica","level":"apply","story":"","q":"แอปเขียน order ลง primary แล้วอ่านหน้ายืนยันจาก read replica ทันที แต่บางครั้งไม่พบ order ใหม่ สาเหตุและวิธีแก้ที่ถูกต้องคือข้อใด","opts":[{"t":"สร้างได้ครบ 6 ตัว แต่ replication จะเปลี่ยนเป็น synchronous","why":"Replica รับข้อมูลได้ เพียงช้ากว่า และ Multi-AZ standby ไม่รับ read"},{"t":"สร้างได้ครบ 6 ตัว โดยนับ Multi-AZ standby เป็นตัวที่ 6","why":"สลับกลไก read replica ใช้ asynchronous ซึ่งเป็นต้นเหตุ"},{"t":"สร้างไม่ได้เลย เพราะ MySQL ไม่รองรับ read replica","why":"การเพิ่ม replica ไม่ลด lag ของแต่ละตัว"},{"t":"สร้างได้สูงสุด 5 ตัวต่อ primary จึงต้องปรับแผน","why":"สไลด์ 32 ระบุให้อ่านจาก primary เมื่อต้องการ strict read-after-write เพราะ replica อาจตามหลัง"}],"ans":3,"ref":"M8 · สไลด์ 31–32"},{"id":"m08-019","topic":"Multi-AZ และ Read replica","level":"apply","story":"","q":"ข้อใดเปรียบเทียบ Multi-AZ standby กับ read replica ได้ถูกต้อง","opts":[{"t":"Replica ไม่รับข้อมูลที่เขียนใหม่ จึงต้องเปลี่ยนไปใช้ Multi-AZ","why":"ผิดทั้งสองส่วน standby ไม่รับ read และใช้ synchronous"},{"t":"Primary ใช้ synchronous replication ทำให้ข้อมูลถึง replica ช้า","why":"Read replica ใช้ asynchronous และ standby ไม่รับ read"},{"t":"ต้องเพิ่มจำนวน read replica เพื่อให้ข้อมูลถึงเร็วขึ้น","why":"Primary ไม่รอ replica ยืนยัน จึงไม่เพิ่ม write latency"},{"t":"เป็น replication lag จาก asynchronous จึงควรอ่านจาก primary","why":"ตรงสไลด์ 29 และ 31 ต่างกันทั้ง replication และบทบาท"}],"ans":3,"ref":"M8 · สไลด์ 29, 31"},{"id":"m08-020","topic":"Multi-AZ และ Read replica","level":"scen","story":"แอปเว็บเชื่อมต่อ RDS Multi-AZ ผ่าน endpoint DNS เมื่อ AZ ของ primary ล่ม ระบบ failover สำเร็จภายในประมาณ 1-2 นาที แต่แอปแสดง connection error ต่อเนื่องจนต้อง restart service ทั้งที่ฐานข้อมูลใหม่พร้อมใช้งานแล้ว","q":"แนวทางแก้ใดตรงสาเหตุที่สุด","opts":[{"t":"Standby ไม่รับ read ส่วน read replica รับ read และ promote ได้","why":"(เพิ่มเติม) การเชื่อมต่อเดิมจะหลุดตอน failover แอปต้อง reconnect ผ่าน endpoint เดิม (สไลด์ 29)"},{"t":"Standby รับ read ได้ และ replicate แบบ asynchronous","why":"Primary เดิมคือเครื่องที่ล้มเหลว และ endpoint DNS ถูกออกแบบให้ไม่ต้องผูก IP"},{"t":"ทั้งสองแบบใช้ synchronous replication และรับ read ได้เหมือนกัน","why":"Replica ไม่ใช่กลไก failover อัตโนมัติ และไม่แก้ connection ที่ค้างอยู่"},{"t":"Read replica เพิ่ม write latency เพราะ primary ต้องรอยืนยัน","why":"Multi-AZ ใช้ synchronous และไม่ใช่ตัวแปรที่ทำให้ connection หลุด"}],"ans":0,"ref":"M8 · สไลด์ 29–30"},{"id":"m08-021","topic":"Multi-AZ และ Read replica","level":"scen","story":"ระบบรายงานของบริษัทใช้ RDS for PostgreSQL ที่ CPU primary สูง 90% จากแดชบอร์ดที่อ่านข้อมูลหนัก (อ่านราว 85% ของ query) ผู้จัดการเสนอเปิด Multi-AZ เพื่อแก้ปัญหาความช้า","q":"ข้อเสนอที่ดีกว่าคืออะไร","opts":[{"t":"เปลี่ยน connection string เป็น IP ของ primary เดิมที่ล่มไป","why":"Standby ไม่รับ read ของแอป ใช้ failover เท่านั้น จึงไม่ลดภาระ primary"},{"t":"เพิ่ม reconnect/retry เพราะ connection เดิมหลุดตอน CNAME เปลี่ยน","why":"Read replica ออกแบบมา offload read-heavy query ออกจาก primary (สไลด์ 31–32)"},{"t":"เพิ่ม read replica เพื่อรับ traffic แทน primary ที่ล่ม","why":"Synchronous replication เพิ่ม write latency เล็กน้อย ไม่ได้เร่ง read"},{"t":"เปลี่ยน Multi-AZ จาก synchronous เป็น asynchronous replication","why":"เป็นการเปลี่ยนเอนจินที่มีต้นทุนสูงทั้งที่ read replica แก้ปัญหา read-heavy ได้ตรงจุดกว่า"}],"ans":1,"ref":"M8 · สไลด์ 29, 31–32"},{"id":"m08-022","topic":"DynamoDB","level":"know","story":"","q":"composite primary key ของตาราง DynamoDB ประกอบด้วยอะไร","opts":[{"t":"Partition key และ sort key","why":"สไลด์ 55 และ 57: คู่ (partition key, sort key) ต้องไม่ซ้ำ"},{"t":"Partition key และ foreign key","why":"DynamoDB ไม่มี foreign key ตามโมเดล primary key ในสไลด์"},{"t":"Sort key และ secondary index","why":"Composite key ต้องมี partition key เสมอ"},{"t":"Attribute อย่างน้อยสองตัวที่เลือกอิสระ","why":"ต้องเป็น partition key + sort key ตามนิยาม"}],"ans":0,"ref":"M8 · สไลด์ 55, 57"},{"id":"m08-023","topic":"DynamoDB","level":"know","story":"","q":"สื่อจัดเก็บและคุณสมบัติด้านเวลาตอบสนองของ DynamoDB ตามสไลด์ Section 2 key takeaways คือข้อใด","opts":[{"t":"HDD ผสม SSD แบบ tiered ให้ latency ระดับวินาที","why":"ไม่ตรงสไลด์ ระบุ SSD เท่านั้น"},{"t":"memory ทั้งหมดและสูญหายเมื่อ node รีสตาร์ต","why":"DynamoDB เป็นฐานข้อมูล durable ไม่ใช่ memory-only"},{"t":"EBS magnetic volume ที่ผู้ใช้ attach เองกับตาราง","why":"DynamoDB เป็น managed ไม่มี volume ให้ผู้ใช้จัดการ"},{"t":"SSD เท่านั้น latency single-digit ms","why":"สไลด์ 58 ระบุ SSD only และ latency ระดับ single-digit ms ในทุกขนาด"}],"ans":3,"ref":"M8 · สไลด์ 53, 58"},{"id":"m08-024","topic":"DynamoDB","level":"know","story":"","q":"ใน DynamoDB การดำเนินการใดต้องอ่านทั้งตารางแล้วกรองตาม attribute จึงช้าและเปลืองกว่า","opts":[{"t":"Query by key","why":"Query ระบุ partition key ไปยัง partition ที่ถูกต้องโดยตรง จึงมีประสิทธิภาพ"},{"t":"Create table","why":"เป็นการสร้างตาราง ไม่ใช่การค้นหา item"},{"t":"Scan","why":"สไลด์ 56: SCAN หา item ตาม attribute ใดก็ได้โดยอ่านทั้งตาราง"},{"t":"Add item","why":"เป็นการเขียน item ไม่ใช่การอ่านทั้งตาราง"}],"ans":2,"ref":"M8 · สไลด์ 56"},{"id":"m08-025","topic":"DynamoDB","level":"apply","story":"","q":"ตาราง Orders มี partition key = CustomerId และ sort key = OrderDate มี item (C100, 2026-03-01) อยู่แล้ว ข้อใดเป็น key ที่สร้าง item ใหม่ได้โดยไม่ขัดกฎความไม่ซ้ำ","opts":[{"t":"(C100, 2026-03-01)","why":"คู่ key ซ้ำกับ item เดิม ขัดกฎ"},{"t":"(C100, 2026-03-02)","why":"Partition key ซ้ำได้ถ้า sort key ต่างกัน คู่ key จึงไม่ซ้ำ (สไลด์ 55, 57)"},{"t":"item ที่ไม่มี key ใด ๆ","why":"ทุก item ต้องมี primary key (สไลด์ 57)"},{"t":"(C100) โดยไม่ระบุ sort key","why":"ตารางนี้เป็น composite key ต้องระบุ sort key ด้วย (เพิ่มเติม)"}],"ans":1,"ref":"M8 · สไลด์ 55, 57"},{"id":"m08-026","topic":"DynamoDB","level":"apply","story":"","q":"ต้องดึงออเดอร์ของลูกค้า C100 ที่อยู่ในช่วง 1-7 มี.ค. อย่างมีประสิทธิภาพ ควรออกแบบ key อย่างไร","opts":[{"t":"PK = OrderDate อย่างเดียว แล้ว Scan กรอง CustomerId ภายหลัง","why":"Scan อ่านทั้งตาราง ช้าและเปลือง"},{"t":"PK = CustomerId, SK = OrderDate แล้ว Query ตามช่วง sort key","why":"Item ที่ partition key เดียวกันเรียงตาม sort key จึง query ช่วงค่าได้ (สไลด์ 55)"},{"t":"PK เป็น UUID สุ่ม ไม่มี sort key ใช้ Scan กรองทุกเงื่อนไข","why":"Key สุ่มไม่ผูกกับ CustomerId จึงต้อง Scan"},{"t":"PK = CustomerId อย่างเดียว แล้ว Scan กรองช่วงวันที่ภายหลัง","why":"ไม่มี sort key เรียงข้อมูล จึงค้นตามช่วงวันที่ไม่ได้อย่างมีประสิทธิภาพ"}],"ans":1,"ref":"M8 · สไลด์ 55–57"},{"id":"m08-027","topic":"DynamoDB","level":"apply","story":"","q":"ตาราง Products มี item สองตัวดังนี้\nitem A: {ProductId: \"P1\", Name: \"Lamp\", Color: \"White\"}\nitem B: {ProductId: \"P2\", Name: \"Radio\", BatteryHours: 20}\nกำหนด ProductId เป็น partition key\nข้อใดสรุปได้ถูกต้องเกี่ยวกับตารางนี้","opts":[{"t":"ผิด เพราะทุก item ในตารางต้องมี attribute ชุดเดียวกันทั้งหมด","why":"ขัดกับ differing attributes ของ DynamoDB"},{"t":"ผิด เพราะต้องประกาศคอลัมน์ Color และ BatteryHours ก่อนเพิ่ม item","why":"ไม่มี schema คอลัมน์ตายตัว ประกาศเฉพาะ key"},{"t":"อยู่ตารางเดียวกันได้ เพราะ attribute ต่างกันได้ ขอเพียงมี primary key","why":"สไลด์ 53, 57: schema แบบ dynamic ยกเว้น primary key"},{"t":"ถูก แต่ item B ต้องมี Color เป็นค่า null จึงจะบันทึกได้","why":"ไม่ต้องใส่ attribute ที่ไม่มี"}],"ans":2,"ref":"M8 · สไลด์ 53, 57"},{"id":"m08-028","topic":"DynamoDB","level":"scen","story":"ตารางงาน (jobs) ใช้ partition key = Status ซึ่งมีค่าเพียง PENDING, RUNNING, DONE และ 95% ของ item เป็น PENDING เมื่อโหลดเขียนสูงขึ้น พบ throttling ทั้งที่ provision throughput ของตารางรวมไว้สูง","q":"สาเหตุและการแก้ไขที่ถูกต้องคืออะไร","opts":[{"t":"DynamoDB จำกัดขนาดตาราง จึงต้องแยกตารางตามค่า Status","why":"สไลด์ระบุ virtually unlimited storage ปัญหาไม่ใช่ขนาดตาราง"},{"t":"เกิด hot partition ควรใช้ partition key ที่กระจายสูง เช่น JobId","why":"(เพิ่มเติม) ข้อมูลถูก hash ตาม partition key; ค่าที่กระจุกทำให้ partition เดียวรับโหลดเกินส่วนแบ่ง (สไลด์ 56)"},{"t":"ต้องเพิ่ม read replica ให้ตาราง เพื่อกระจายโหลดเขียน","why":"DynamoDB ไม่ใช้ read replica แบบ RDS และปัญหาคือ key distribution"},{"t":"เปลี่ยนไปใช้ Scan เพื่อกระจายภาระไปทั่วทุก partition","why":"Scan อ่านทั้งตารางและเปลืองกว่า ไม่แก้การกระจุกของ key"}],"ans":1,"ref":"M8 · สไลด์ 54–56"},{"id":"m08-029","topic":"DynamoDB","level":"scen","story":"ตาราง Users มี 50 ล้าน item โดยมี UserId เป็น partition key แต่ระบบ login ค้นหาผู้ใช้จาก email ด้วยการ Scan พร้อม filter ทำให้ช้าและค่าใช้จ่ายสูง","q":"ควรปรับอย่างไร","opts":[{"t":"เพิ่ม read replica ให้ DynamoDB เพื่อให้ Scan เร็วขึ้นกว่าเดิม","why":"DynamoDB ไม่มี read replica แบบ RDS และ Scan ยังต้องอ่านทั้งตาราง"},{"t":"ให้ Query ด้วย key ได้ เช่นใช้ email เป็น key หรือ index ที่ใช้ email","why":"Query by key ไปที่ partition โดยตรง ต่างจาก SCAN ที่อ่านทั้งตาราง (สไลด์ 56); index เป็นข้อเพิ่มเติม"},{"t":"ย้ายไป RDS Multi-AZ เพื่อให้ standby ช่วยรับงาน Scan","why":"Standby ไม่รับ read และไม่แก้ปัญหา access pattern"},{"t":"เพิ่ม sort key เป็นค่าสุ่มให้ทุก item เพื่อให้ค้นง่ายขึ้น","why":"ค่าสุ่มไม่ช่วยให้ค้นด้วย email ได้ จึงยังต้อง Scan"}],"ans":1,"ref":"M8 · สไลด์ 55–56"},{"id":"m08-030","topic":"Redshift","level":"know","story":"","q":"ใน Amazon Redshift ส่วนใดรับ query จาก SQL client สร้างแผนการประมวลผล และกระจายงานไปยัง compute node","opts":[{"t":"Leader node","why":"สไลด์ 64: Leader node รับ query สร้างแผน และกระจายงาน"},{"t":"Compute node","why":"Compute node ประมวลผลส่วนของข้อมูลที่เก็บเอง ไม่รับ query จาก client โดยตรง"},{"t":"Standby node","why":"ไม่ใช่ส่วนประกอบในสถาปัตยกรรม Redshift ที่สไลด์ระบุ"},{"t":"Amazon S3","why":"S3 เป็นแหล่งข้อมูลที่โหลดเข้า Redshift ไม่ได้วางแผน query"}],"ans":0,"ref":"M8 · สไลด์ 64"},{"id":"m08-031","topic":"Redshift","level":"apply","story":"","q":"ตาราง sales มี 100 คอลัมน์และหลายพันล้านแถว คำสั่ง SELECT SUM(amount) FROM sales ทำงานเร็วบน Redshift เพราะกลไกใดเป็นหลัก","opts":[{"t":"Redshift เก็บทุกแถวไว้ใน memory ของ leader node ทั้งหมด","why":"Leader node วางแผน/กระจายงาน ไม่ได้เก็บข้อมูลทั้งหมด"},{"t":"Columnar อ่านเฉพาะคอลัมน์ amount ลด I/O และประมวลผลขนาน","why":"สไลด์ 64, 69: columnar และ MPP ลดการอ่านดิสก์และกระจายงาน"},{"t":"Redshift ใช้ synchronous standby แยก query ไปยัง AZ อื่น","why":"เป็นกลไก RDS Multi-AZ ซึ่ง standby ก็ไม่รับ query"},{"t":"Redshift เปลี่ยนเป็น key-value store ระหว่างรัน query นี้","why":"Redshift ใช้ SQL แบบ columnar ตลอด ไม่ใช่ key-value"}],"ans":1,"ref":"M8 · สไลด์ 64, 69"},{"id":"m08-032","topic":"Redshift","level":"scen","story":"ทีม BI รันรายงานบน RDS MySQL ขนาด 3 TB ด้วย query ที่ join และรวมข้อมูลหลายตาราง ใช้เวลาหลายชั่วโมงและมีผู้ใช้ BI หลายคนพร้อมกัน ทีมต้องการใช้ BI tool และ SQL client เดิมโดยไม่เขียนใหม่ และขยายได้โดยไม่ downtime","q":"บริการใดตรงที่สุด","opts":[{"t":"Redshift เพราะเป็น MPP columnar รองรับ BI เดิมและ scale ไม่ downtime","why":"สไลด์ 64–66, 69 ระบุ MPP, columnar, compatible กับ SQL client/BI และ scale ไม่มี downtime"},{"t":"RDS ที่ใหญ่ขึ้นพร้อม read replica 5 ตัวเพื่อกระจายงาน","why":"RDS เหมาะ OLTP/light analytics ช่วง low-TB และ replica ไม่ได้ทำ MPP"},{"t":"Amazon DynamoDB พร้อมทำ Scan แบบขนานข้ามทุก partition","why":"เหมาะกับ key lookup ไม่ใช่ analytic query ซับซ้อนและ JOIN หลายตาราง"},{"t":"Amazon ElastiCache เพื่อ cache ผลลัพธ์ของ query ทั้งหมด","why":"เป็น in-memory cache ไม่ใช่ data warehouse"}],"ans":0,"ref":"M8 · สไลด์ 23, 64–69"},{"id":"m08-033","topic":"Aurora","level":"know","story":"","q":"Amazon Aurora เข้ากันได้กับฐานข้อมูลใดบ้าง","opts":[{"t":"Oracle และ Microsoft SQL Server","why":"เป็นเอนจินแยกที่ RDS รองรับ ไม่ใช่ความเข้ากันได้ของ Aurora"},{"t":"MongoDB และ Cassandra","why":"เป็น non-relational ซึ่ง Aurora เป็น relational"},{"t":"MariaDB และ Redis","why":"ไม่ใช่ความเข้ากันได้ที่สไลด์ระบุ"},{"t":"MySQL และ PostgreSQL","why":"สไลด์ 71: เข้ากันได้กับ MySQL หรือ PostgreSQL"}],"ans":3,"ref":"M8 · สไลด์ 71"},{"id":"m08-034","topic":"Aurora","level":"apply","story":"","q":"Aurora volume ถูกเก็บ 6 สำเนา กระจายข้าม 3 AZ (AZ ละ 2 สำเนา) ถ้า AZ หนึ่งล่มทั้งหมด จะส่งผลอย่างไร","opts":[{"t":"ข้อมูลสูญหายครึ่งหนึ่งจึงต้อง restore จาก S3 ทั้งก้อน","why":"การทำสำเนาข้าม AZ ป้องกันการสูญหายนี้ และ backup ใน S3 เป็นชั้นเสริม"},{"t":"Database หยุดเขียนจนกว่าจะสร้าง AZ ใหม่ขึ้นมาทดแทน","why":"การออกแบบทนการเสียสำเนาจึงไม่ต้องหยุด"},{"t":"เสีย 2 สำเนา เหลือ 4 ยังไม่สูญหายและยังอ่าน/เขียนได้","why":"(เพิ่มเติม) ออกแบบให้ทนการเสียสำเนาได้และยังอ่าน/เขียนต่อ; สไลด์ 73 แสดง 3 AZ"},{"t":"เสีย 3 สำเนา เหลือ 3 สำเนา และอ่านได้อย่างเดียว","why":"ผิดจำนวน: AZ ละ 2 สำเนา จึงเสีย 2 ไม่ใช่ 3"}],"ans":2,"ref":"M8 · สไลด์ 73"},{"id":"m08-035","topic":"Aurora","level":"apply","story":"","q":"ข้อใดอธิบาย resilient design ของ Aurora ถูกต้อง","opts":[{"t":"ส่ง snapshot ทั้งก้อนไปยัง standby ทุกครั้งที่ commit","why":"ไม่ใช่กลไกของ Aurora ซึ่งส่ง redo log"},{"t":"พึ่งผู้ใช้สั่ง restore จาก backup ด้วยตนเองเท่านั้น","why":"Aurora ทำ failure detection และ repair อัตโนมัติ (สไลด์ 71)"},{"t":"ส่ง redo log ไป storage layer ที่ซ่อมตัวเองได้ ไม่ replay ทั้งก้อน","why":"(เพิ่มเติม) สไลด์ 74 แสดงการซ่อมแซมด้วย redo log"},{"t":"ใช้ asynchronous read replica เป็นที่เก็บข้อมูลสำรองเพียงชุดเดียว","why":"ข้อมูลถูกเก็บหลายสำเนาข้าม 3 AZ ไม่ใช่พึ่ง read replica เท่านั้น"}],"ans":2,"ref":"M8 · สไลด์ 71, 73–74"},{"id":"m08-036","topic":"Aurora","level":"scen","story":"แอป MySQL เดิมจะย้ายขึ้นคลาวด์โดยไม่แก้โค้ด ต้องการให้ storage กระจายข้าม 3 AZ มี backup ต่อเนื่องไป S3 และ repair ระดับ storage ด้วย redo log รวมทั้ง provisioning, patching, recovery เป็นงานอัตโนมัติ","q":"บริการใดเหมาะที่สุด","opts":[{"t":"Amazon Aurora (MySQL-compatible)","why":"สไลด์ 71–75 ตรงทุกข้อ: เข้ากันได้กับ MySQL, ข้าม 3 AZ, backup ไป S3, redo log, fully managed"},{"t":"Amazon DynamoDB พร้อมเขียนแอปใหม่เป็น NoSQL","why":"ต้องเขียนแอปใหม่ให้เป็น NoSQL ขัดกับเงื่อนไขไม่แก้โค้ด"},{"t":"Amazon Redshift เพื่อใช้เป็นฐานข้อมูลของแอป","why":"เป็น data warehouse สำหรับ analytics ไม่ใช่ฐานข้อมูล transactional ของแอปเดิม"},{"t":"MySQL บน EC2 ที่ติดตั้งและดูแลเอง","why":"ต้องรับ patch, backup, HA เอง และไม่ได้ storage layer แบบ Aurora"}],"ans":0,"ref":"M8 · สไลด์ 71–76"},{"id":"m08-037","topic":"ต้นทุนและการคิดเงิน","level":"know","story":"","q":"ข้อใดอธิบาย clock-hour billing ของ Amazon RDS ได้ถูกต้อง","opts":[{"t":"คิดต่อเนื่องแม้ฐานข้อมูลถูกลบไปแล้วทั้งหมด","why":"คิดขณะรันเท่านั้น"},{"t":"คิดเป็นรายปีตามขนาดข้อมูลที่เก็บอยู่จริงเท่านั้น","why":"สไลด์ระบุคิดตามชั่วโมงที่รัน"},{"t":"คิดเฉพาะจำนวน request โดยไม่รวมขนาด instance","why":"ค่าบริการขึ้นกับ engine, size, memory class ด้วย"},{"t":"คิดเงินขณะรัน นับเป็นชั่วโมงตามนาฬิกา","why":"ตรงสไลด์ 36"}],"ans":3,"ref":"M8 · สไลด์ 36"},{"id":"m08-038","topic":"ต้นทุนและการคิดเงิน","level":"apply","story":"","q":"ระบบหนึ่งมีข้อมูลเข้า 10 TB และข้อมูลออกไปยังอินเทอร์เน็ต 2 TB ต่อเดือน\nตามหลักคิดเงิน data transfer ของ RDS ส่วนใดที่ถูกคิดค่าบริการ","opts":[{"t":"ทั้งขาเข้า 10 TB และขาออก 2 TB รวมกัน","why":"ขาเข้าไม่คิดค่า"},{"t":"เฉพาะขาออก 2 TB แบบขั้นบันได","why":"สไลด์ 39: ขาเข้าไม่คิดค่า ขาออกคิดแบบ tiered"},{"t":"เฉพาะขาเข้า 10 TB แบบอัตราเดียว","why":"ขาเข้าฟรี"},{"t":"ไม่คิดเลยทั้งสองทิศทางของข้อมูลทั้งหมด","why":"ขาออกถูกคิด"}],"ans":1,"ref":"M8 · สไลด์ 39"},{"id":"m08-039","topic":"ต้นทุนและการคิดเงิน","level":"apply","story":"","q":"DB instance ที่ active ขนาด 500 GB มีพื้นที่ backup รวม 650 GB\nส่วนที่เกินและถูกคิดเงินเป็นเท่าใด","opts":[{"t":"650 GB","why":"ลืมสิทธิ์ backup ฟรีสูงสุด 100% ของขนาด DB"},{"t":"150 GB","why":"ฟรีถึง 100% ของขนาด DB คือ 500 GB ส่วนเกิน 650 - 500 = 150 GB"},{"t":"500 GB","why":"คือส่วนที่ฟรี"},{"t":"0 GB","why":"เพราะ backup เกินสิทธิ์ฟรี"}],"ans":1,"ref":"M8 · สไลด์ 38"},{"id":"m08-040","topic":"ต้นทุนและการคิดเงิน","level":"scen","story":"ระบบ production รันฐานข้อมูล RDS ตลอด 24 ชั่วโมงอย่างต่อเนื่องมาแล้ว 3 ปีและจะรันต่อ ส่วน instance สำหรับทดสอบใช้งานเพียงสองสัปดาห์แล้วลบทิ้ง ทีมต้องการลดค่าใช้จ่ายรวม","q":"แนวทางใดเหมาะสม","opts":[{"t":"Reserved สำหรับ production และ On-Demand สำหรับตัวทดสอบ","why":"โหลดคงที่ยาวเหมาะกับ Reserved (สัญญา 1/3 ปี) ส่วนโหลดชั่วคราวเหมาะกับ On-Demand (สไลด์ 37)"},{"t":"On-Demand ทั้งหมด เพราะไม่มีข้อผูกมัดกับสัญญาระยะยาว","why":"ไม่ได้ส่วนลดสำหรับ production ที่รันนาน"},{"t":"Reserved ทั้งหมด รวมถึงตัวทดสอบที่ใช้แค่สองสัปดาห์","why":"ตัวทดสอบใช้สั้น จึงเสียสัญญา"},{"t":"เปิด Multi-AZ ให้ production เพื่อลดต้นทุนรวมของระบบ","why":"Multi-AZ เพิ่มค่า storage/I/O ไม่ได้ลดต้นทุน"}],"ans":0,"ref":"M8 · สไลด์ 37, 39"}],"w11":[{"id":"w11-001","topic":"ELB","level":"know","story":"","q":"ข้อใดอธิบายการทำงานของ Elastic Load Balancing (ELB) ได้ถูกต้องที่สุดตามสไลด์?","opts":[{"t":"กระจายทราฟฟิกขาเข้าไปยังหลาย target ในหนึ่ง AZ หรือมากกว่า","why":"ถูกต้อง — ELB รับทราฟฟิกแล้วส่งเฉพาะ target ที่ผ่าน health check และ scale ตามทราฟฟิกอัตโนมัติ"},{"t":"รับทราฟฟิกได้เฉพาะ internet-facing และต้องกำหนดจำนวน instance ของ load balancer เองล่วงหน้า","why":"ผิด — ELB มีทั้ง public (internet-facing) และ private (internal) และเป็น managed service ที่ scale ตามทราฟฟิกเอง"},{"t":"ทำงานได้เฉพาะใน AZ เดียว เพื่อให้ latency ระหว่าง LB กับ target ต่ำที่สุด และตรวจสุขภาพ target ทุกตัวพร้อมกัน","why":"ผิด — ELB กระจาย target ข้ามหนึ่ง AZ หรือมากกว่า และการข้าม AZ คือหัวใจของ HA"},{"t":"ส่ง request ไปทุก target ที่ลงทะเบียนเท่ากัน รวมตัวที่ health check ล้มเหลวด้วย แล้วให้ client retry เอง","why":"ผิด — ELB ส่ง request เฉพาะ target ที่ healthy และหยุดส่งให้ตัวที่ไม่ผ่าน health check"}],"ans":0,"ref":"W11 · สไลด์ 26"},{"id":"w11-002","topic":"ELB","level":"know","story":"","q":"Load balancer ชนิดใดทำงานที่ OSI Layer 7 และอ่าน URL, host, header, cookie ของ request เพื่อ route ตามเนื้อหาได้?","opts":[{"t":"Network Load Balancer (NLB)","why":"ผิด — NLB ทำงานที่ Layer 4 เห็นเพียง IP, port, protocol"},{"t":"Gateway Load Balancer (GWLB)","why":"ผิด — GWLB ทำงานที่ Layer 3 ส่งแพ็กเก็ตผ่าน virtual appliance ไม่อ่าน HTTP"},{"t":"Application Load Balancer (ALB)","why":"ถูกต้อง — ALB ทำงานที่ Layer 7 (HTTP/HTTPS) จึงเห็นเนื้อหา request"},{"t":"Classic Load Balancer ที่ผูกกับ EC2-Classic","why":"ผิด — เป็นรุ่น legacy ไม่ใช่ตัวที่สไลด์ใช้อธิบายการ route ตามเนื้อหา และไม่ควรใช้กับงานใหม่"}],"ans":2,"ref":"W11 · สไลด์ 27, 30"},{"id":"w11-003","topic":"ELB","level":"know","story":"","q":"ข้อมูลใดต่อไปนี้ที่ NLB (Layer 4) มองเห็นและใช้ตัดสินใจ?","opts":[{"t":"source/destination IP, source/destination port และ protocol (TCP/UDP/TLS)","why":"ถูกต้อง — NLB ส่งต่อ connection โดยไม่เปิด payload"},{"t":"URL path และ Host header","why":"ผิด — ข้อมูลนี้อยู่ใน payload ของ HTTP ซึ่งเป็น Layer 7"},{"t":"cookie และ HTTP method","why":"ผิด — ข้อมูลระดับ HTTP ที่ NLB ไม่ parse"},{"t":"HTTP status code ที่ target ตอบ","why":"ผิด — เป็นข้อมูล Layer 7 เช่นกัน NLB จึงตรวจสุขภาพด้วย TCP เป็นหลัก (HTTP check เป็นตัวเลือก)"}],"ans":0,"ref":"W11 · สไลด์ 32"},{"id":"w11-004","topic":"ELB","level":"know","story":"","q":"Gateway Load Balancer (GWLB) ใช้โปรโตคอลใดห่อ (encapsulate) แพ็กเก็ตเพื่อส่งไปยัง virtual appliance?","opts":[{"t":"VXLAN เหนือ UDP port 4789 เท่านั้น","why":"ผิด — สไลด์ระบุ GENEVE สำหรับ GWLB"},{"t":"IPsec tunnel mode","why":"ผิด — IPsec ไม่ใช่กลไกที่ GWLB ใช้ส่งแพ็กเก็ตถึง appliance"},{"t":"GRE","why":"ผิด — ไม่ใช่โปรโตคอลที่สไลด์ระบุสำหรับ GWLB"},{"t":"GENEVE","why":"ถูกต้อง — GWLB ส่งแพ็กเก็ตไป appliance แบบ encapsulation ด้วย GENEVE"}],"ans":3,"ref":"W11 · สไลด์ 27, 40–41"},{"id":"w11-005","topic":"ELB","level":"know","story":"","q":"ในองค์ประกอบของ load balancer ตามสไลด์ \"listener\" คืออะไร?","opts":[{"t":"กระบวนการที่ตรวจสอบ connection request ตาม protocol และ port ที่กำหนด (เช่น HTTPS:443)","why":"ถูกต้อง — listener กำหนด protocol/port และมี rule ที่ชี้ไป target group"},{"t":"กลุ่มของ target ที่ลงทะเบียน พร้อมค่า protocol, port และ health check ของกลุ่มนั้น","why":"ผิด — นั่นคือ target group"},{"t":"ใบรับรอง TLS ที่ออกโดย ACM และผูกกับ load balancer เพื่อถอดรหัส","why":"ผิด — ใบรับรองเป็นสิ่งที่ผูกกับ listener ไม่ใช่ตัว listener"},{"t":"instance หรือ container ที่ประมวลผล request จริงหลัง load balancer","why":"ผิด — นั่นคือ target (compute target)"}],"ans":0,"ref":"W11 · สไลด์ 28–29"},{"id":"w11-006","topic":"ELB","level":"know","story":"","q":"ALB ใช้ algorithm ใดเป็นค่าเริ่มต้นในการเลือก target ภายใน target group?","opts":[{"t":"Round robin","why":"ถูกต้อง — ค่าเริ่มต้นคือ round robin และเปลี่ยนเป็น least outstanding requests หรือ weighted random ได้ต่อ target group"},{"t":"Least outstanding requests","why":"ผิด — เป็นตัวเลือกที่ต้องตั้งค่าเอง"},{"t":"Weighted random","why":"ผิด — เป็นตัวเลือกที่ต้องตั้งค่าเอง"},{"t":"Flow hash","why":"ผิด — เป็นกลไกของ NLB ไม่ใช่ ALB"}],"ans":0,"ref":"W11 · สไลด์ 35"},{"id":"w11-007","topic":"ELB","level":"know","story":"","q":"NLB เลือก target จาก connection ใหม่ด้วยวิธีใด?","opts":[{"t":"round robin ตามลำดับ target เหมือน ALB","why":"ผิด — สไลด์ระบุว่า NLB ไม่ใช้ round robin เลย"},{"t":"flow hash จาก protocol, source/destination IP, source/destination port และ TCP sequence number","why":"ถูกต้อง — flow เดียวกันไป target เดียวตลอดอายุ connection"},{"t":"least outstanding requests ตามจำนวน request ค้าง","why":"ผิด — NLB ไม่เห็นระดับ request ของ HTTP จึงทำแบบนี้ไม่ได้"},{"t":"อ่าน cookie ที่ ALB ออกให้แล้วเลือก target เดิม","why":"ผิด — cookie เป็นข้อมูล Layer 7 ที่ NLB ไม่เห็น"}],"ans":1,"ref":"W11 · สไลด์ 35"},{"id":"w11-008","topic":"ELB","level":"know","story":"","q":"ALB sticky session แบบ duration-based ใช้ cookie ที่ ALB ออกเอง มีอายุกำหนดได้ในช่วงใด?","opts":[{"t":"1 วินาทีถึง 7 วัน","why":"ถูกต้อง — ตามสไลด์ Sticky sessions"},{"t":"1 นาทีถึง 24 ชั่วโมง","why":"ผิด — ช่วงจริงคือ 1 วินาทีถึง 7 วัน"},{"t":"30 วินาทีถึง 1 ชั่วโมง","why":"ผิด — ไม่ตรงช่วงที่สไลด์ระบุ"},{"t":"1 ชั่วโมงถึง 30 วัน","why":"ผิด — เพดานคือ 7 วัน ไม่ใช่ 30 วัน"}],"ans":0,"ref":"W11 · สไลด์ 37"},{"id":"w11-009","topic":"ELB","level":"know","story":"","q":"Sticky session ของ NLB ใช้อะไรเป็นตัวตรึง client กับ target?","opts":[{"t":"source IP — ทุก connection จาก client IP เดียวกันไป target เดียวกัน","why":"ถูกต้อง — NLB ไม่มี cookie เพราะไม่เห็น Layer 7"},{"t":"cookie ที่ NLB ออกเองแบบ duration-based","why":"ผิด — cookie เป็นกลไกของ ALB"},{"t":"session ID ใน URL path","why":"ผิด — NLB ไม่เห็น URL"},{"t":"TLS session ticket ที่เก็บใน ACM","why":"ผิด — ACM จัดการใบรับรอง ไม่เกี่ยวกับการตรึง target"}],"ans":0,"ref":"W11 · สไลด์ 37"},{"id":"w11-010","topic":"ELB","level":"know","story":"","q":"AWS Certificate Manager (ACM) มีบทบาทอะไรกับ load balancer ในสไลด์?","opts":[{"t":"ออกและต่ออายุใบรับรอง TLS ที่ผูกกับ listener (HTTPS/TLS)","why":"ถูกต้อง — ใบรับรองจาก ACM ผูกกับ listener ให้ถอดรหัสที่ load balancer"},{"t":"ตรวจ health check ของ target แทน load balancer แล้วแจ้งผลให้ listener","why":"ผิด — health check เป็นหน้าที่ของ load balancer/target group"},{"t":"กระจาย request ไปยัง target group ตาม rule ที่กำหนดไว้ในแต่ละ listener","why":"ผิด — เป็นหน้าที่ของ listener และ rule"},{"t":"ลงทะเบียน instance ใหม่ที่ Auto Scaling group เปิดเข้า target group ให้","why":"ผิด — Auto Scaling group เป็นผู้ลงทะเบียน"}],"ans":0,"ref":"W11 · สไลด์ 29, 31"},{"id":"w11-011","topic":"ELB","level":"know","story":"","q":"สถานะของ Classic Load Balancer (CLB) ตามสไลด์ คืออะไร?","opts":[{"t":"เป็น load balancer แนะนำสำหรับเว็บแอปใหม่เพราะรองรับทั้ง Layer 3 และ 7","why":"ผิด — สไลด์แนะนำ ALB เป็นค่าเริ่มต้นสำหรับเว็บ"},{"t":"ใช้แทน GWLB เมื่อต้องส่งทราฟฟิกผ่าน appliance","why":"ผิด — CLB ไม่มีกลไก GENEVE/appliance"},{"t":"legacy ยังมีอยู่ แต่ห้ามใช้กับงานใหม่","why":"ถูกต้อง — ใช้เมื่อยังอัปเกรดไม่ได้เท่านั้น"},{"t":"รองรับ static IP และ UDP จึงใช้แทน NLB","why":"ผิด — คุณสมบัตินี้เป็นของ NLB"}],"ans":2,"ref":"W11 · สไลด์ 27, 30"},{"id":"w11-012","topic":"ELB","level":"know","story":"","q":"ใครเป็นฝ่ายลงทะเบียน instance เข้า target group เมื่อใช้ Auto Scaling group หลัง load balancer?","opts":[{"t":"Load balancer ค้นหา instance ใน ASG เองแล้วเพิ่มเข้า listener","why":"ผิด — LB ไม่คุยกับ ASG โดยตรง"},{"t":"Listener ลงทะเบียน instance ตาม rule","why":"ผิด — listener ทำหน้าที่รับ connection และ forward"},{"t":"Auto Scaling group เป็นฝ่ายลงทะเบียน instance เข้า target group","why":"ถูกต้อง — load balancer อ่านเฉพาะ target group ไม่ได้คุยกับ ASG โดยตรง"},{"t":"ACM ลงทะเบียน instance ที่มีใบรับรองถูกต้อง","why":"ผิด — ACM ไม่เกี่ยวกับการลงทะเบียน target"}],"ans":2,"ref":"W11 · สไลด์ 28, 49–50"},{"id":"w11-013","topic":"ELB","level":"apply","story":"","q":"เรียงลำดับเส้นทาง request ที่ถูกต้องในแล็บ ELB","opts":[{"t":"Internet -> Listener -> Load balancer -> Instances -> Target group","why":"ผิด — target group อยู่ก่อน instance ไม่ใช่หลัง"},{"t":"Internet -> Target group -> Listener -> Load balancer -> Instances","why":"ผิด — listener ต้องรับ connection ก่อนที่จะ forward ไป target group"},{"t":"Internet -> Load balancer -> Target group -> Listener -> Instances","why":"ผิด — listener (พร้อม rule) เลือก target group ไม่ใช่กลับกัน"},{"t":"Internet -> Load balancer -> Listener -> Target group -> Instances","why":"ถูกต้อง — LB เป็นจุดเข้า listener ตรวจ protocol/port, target group บอกว่าใคร healthy, instance ประมวลผล"}],"ans":3,"ref":"W11 · สไลด์ 28–29"},{"id":"w11-014","topic":"ELB","level":"apply","story":"","q":"เว็บเซิร์ฟเวอร์หลัง ALB บันทึก IP ต้นทางเป็น IP ของ ALB ทุก request ต้องแก้อย่างไรเพื่อให้ได้ IP จริงของ client?","opts":[{"t":"เปลี่ยนเป็น NLB เสมอ เพราะ ALB ไม่สามารถส่ง IP client ได้ทุกกรณี","why":"ผิด — ALB ส่งผ่าน header ได้ ไม่จำเป็นต้องเปลี่ยน LB"},{"t":"เปิด sticky session เพื่อให้ ALB ส่ง source IP เดิม","why":"ผิด — sticky session ตรึง target ไม่เปลี่ยน IP ที่ server เห็น"},{"t":"ใช้ listener พอร์ต 443 แทน 80","why":"ผิด — พอร์ตไม่มีผลต่อ source IP ที่ target เห็น"},{"t":"อ่าน HTTP header X-Forwarded-For","why":"ถูกต้อง — ALB ยุติ connection แล้วเปิดใหม่ไป target จึงส่ง IP client มาใน header"}],"ans":3,"ref":"W11 · สไลด์ 33"},{"id":"w11-015","topic":"ELB","level":"apply","story":"","q":"ผู้ทดสอบรีเฟรชหน้าเว็บหลายครั้งผ่าน ALB (round robin, 3 target) แต่เห็น instance เดิมทุกครั้ง ข้อสรุปใดสมเหตุสมผลที่สุด?","opts":[{"t":"ALB เสีย เพราะ round robin ต้องเปลี่ยน target ทุก request ทุกกรณี","why":"ผิด — connection ที่ใช้ซ้ำทำให้ไม่เห็นการสลับ"},{"t":"เบราว์เซอร์ใช้ connection เดิมซ้ำ (keep-alive)","why":"ถูกต้อง — การเลือก target เกิดต่อ connection ใหม่ ตามเคล็ดลับการทดสอบในสไลด์"},{"t":"target อีกสองตัวไม่ผ่าน health check ตลอด จึงมีเพียงตัวเดียวที่รับ request ได้","why":"ไม่ใช่ข้อสรุปที่จำเป็น — ต้องดู health ใน target group ก่อน และอาการนี้อธิบายได้ด้วย keep-alive ง่ายกว่า"},{"t":"ALB เปิด sticky session ให้เองโดยอัตโนมัติสำหรับ connection แรกของทุก client","why":"ผิด — sticky session ต้องตั้งค่าเอง ไม่เปิดเอง"}],"ans":1,"ref":"W11 · สไลด์ 35"},{"id":"w11-016","topic":"ELB","level":"apply","story":"","q":"API มี request ที่ใช้เวลาประมวลผลต่างกันมาก (50 ms ถึงหลายวินาที) และพบว่า target บางตัวมีงานค้างสะสมขณะตัวอื่นว่าง ควรปรับ algorithm ของ ALB target group เป็นอะไร?","opts":[{"t":"คง round robin","why":"ผิด — round robin สมมติว่าทุก request ต้นทุนเท่ากัน จึงสะสมงานค้างที่ target ที่ได้ request หนัก"},{"t":"Least outstanding requests","why":"ถูกต้อง — ส่งไป target ที่มี request ค้างน้อยที่สุด เหมาะเมื่อเวลาประมวลผลต่างกันมาก"},{"t":"Weighted random","why":"ผิด — ยังกระจายเท่า ๆ กันแบบสุ่ม ไม่ดูงานค้าง"},{"t":"เปลี่ยนเป็น NLB แล้วใช้ flow hash","why":"ผิด — flow hash ตรึง flow ไป target เดียวและไม่ดูงานค้าง ทั้งยังเสีย Layer 7"}],"ans":1,"ref":"W11 · สไลด์ 35"},{"id":"w11-017","topic":"ELB","level":"apply","story":"","q":"ข้อใดเป็นข้อความที่ \"ผิด\" เกี่ยวกับ ALB และ NLB?","opts":[{"t":"ALB รองรับ WAF integration และ user authentication ส่วน NLB ไม่รองรับ","why":"ถูกตามตารางสไลด์ 33"},{"t":"NLB ให้ static IP ต่อ AZ ส่วน ALB ไม่ได้ให้ IP คงที่","why":"ถูก — ใช้กับกฎ firewall แบบ IP"},{"t":"ALB ไม่รองรับ UDP แต่ NLB รองรับ","why":"ถูก — UDP ต้องใช้ NLB"},{"t":"NLB route ตาม URL path และ Host header ได้เพราะเร็วกว่า","why":"ข้อความนี้ผิด — NLB ไม่เห็น path/host จึงทำ content-based routing ไม่ได้"}],"ans":3,"ref":"W11 · สไลด์ 32–33"},{"id":"w11-018","topic":"ELB","level":"apply","story":"","q":"ต้องการให้ TLS เข้ารหัสต่อเนื่องจาก client ถึง target โดย load balancer ไม่ถือ private key ควรตั้งค่าอย่างไร?","opts":[{"t":"ใช้ ALB HTTPS listener กับใบรับรองจาก ACM","why":"ผิด — ALB ทำ TLS termination ถือคีย์ถอดรหัสเพื่ออ่าน header แล้วเปิด connection ใหม่"},{"t":"ใช้ GWLB เพราะทำงานที่ Layer 3","why":"ผิด — GWLB มีไว้ส่งแพ็กเก็ตผ่าน appliance ไม่ใช่ตัวเลือก pass-through ของเว็บ"},{"t":"ใช้ ALB ร่วมกับ sticky session เพื่อรักษา session เดิม","why":"ผิด — sticky session ไม่เกี่ยวกับการเข้ารหัสต่อเนื่อง"},{"t":"ใช้ NLB แบบ pass-through ส่ง TLS ที่ยังเข้ารหัสไปถึง target","why":"ถูกต้อง — NLB ไม่ถือคีย์ในโหมด pass-through จึงไม่ถอดรหัสระหว่างทาง"}],"ans":3,"ref":"W11 · สไลด์ 31"},{"id":"w11-019","topic":"ELB","level":"apply","story":"","q":"เปิด ALB sticky session (duration-based) ไว้ แล้ว instance ที่ผู้ใช้ถูกตรึงอยู่ล่ม จะเกิดอะไรกับ session ของผู้ใช้?","opts":[{"t":"session ถูกย้ายไป target อื่นอัตโนมัติ พร้อมข้อมูลในหน่วยความจำของเครื่องเดิมครบ","why":"ผิด — LB ไม่ replicate state ในหน่วยความจำ"},{"t":"ALB ปฏิเสธ request ของผู้ใช้นั้นทั้งหมดจนกว่า cookie ที่ออกไปจะหมดอายุ","why":"ผิด — เมื่อ target ไม่ healthy ALB จะส่งไป target อื่น ผู้ใช้เสีย session ไม่ใช่ถูกบล็อก"},{"t":"target ใหม่อ่านข้อมูล session จากค่าที่เก็บไว้ใน cookie ของ ALB ได้","why":"ผิด — cookie เก็บเพียงตัวระบุการตรึง ไม่ใช่ข้อมูล session"},{"t":"ข้อมูล session ที่เก็บในหน่วยความจำของเครื่องนั้นหาย","why":"ถูกต้อง — ข้อเสียของ sticky session คือ target ตาย session ตายตาม"}],"ans":3,"ref":"W11 · สไลด์ 37"},{"id":"w11-020","topic":"ELB","level":"apply","story":"","q":"ALB listener HTTP:80 มี rule: /api/* -> TG-api และ default rule -> TG-web ผู้ใช้เรียก /images/logo.png จะไปที่ไหน?","opts":[{"t":"TG-api เพราะ rule ที่มีเงื่อนไขมีลำดับก่อนทุกกรณี","why":"ผิด — rule จะตรงเมื่อเงื่อนไขตรงเท่านั้น path นี้ไม่ตรง /api/*"},{"t":"ถูกปฏิเสธ เพราะไม่มี rule สำหรับ /images","why":"ผิด — default rule ครอบคลุม request ที่ไม่ตรง rule อื่น"},{"t":"TG-web เพราะไม่ตรง rule /api/*","why":"ถูกต้อง — request ที่ไม่ตรงเงื่อนไขใช้ default rule"},{"t":"ถูกส่งไปทุก target group พร้อมกัน","why":"ผิด — rule forward ไปยัง target group ที่ระบุเพียงที่เดียวต่อ action"}],"ans":2,"ref":"W11 · สไลด์ 29"},{"id":"w11-021","topic":"ELB","level":"apply","story":"","q":"ระบบมี traffic สม่ำเสมอสูงตลอดวัน และมี ALB อยู่แล้ว บาง path เป็น Lambda ขณะ path อื่นยังเป็น EC2 ควรเลือกวิธีใดเข้าถึง Lambda?","opts":[{"t":"ALB -> Lambda","why":"ถูกต้อง — ALB ผสม Lambda กับ EC2 ได้ และคุ้มเมื่อ volume สูงสม่ำเสมอ"},{"t":"API Gateway เพราะผสม Lambda กับ EC2 target ใน API เดียวได้","why":"ผิด — API Gateway ใช้ร่วมกับ EC2 target แบบ ALB ไม่ได้ตามตารางสไลด์"},{"t":"NLB เพราะมี throughput สูงสุด","why":"ผิด — NLB ไม่ route ตาม path ที่ต้องแยก Lambda กับ EC2"},{"t":"Route 53 Geolocation แยกผู้ใช้ไป Lambda","why":"ผิด — แยกตามตำแหน่งผู้ใช้ ไม่ใช่ตาม path"}],"ans":0,"ref":"W11 · สไลด์ 43"},{"id":"w11-022","topic":"ELB","level":"apply","story":"","q":"ต้องการตรวจสอบทราฟฟิกขาเข้าจาก Internet ด้วย GWLB แต่เมื่อสร้าง GWLB endpoint แล้วแพ็กเก็ตยังเข้า application subnet ตรง ๆ ขาดสิ่งใด?","opts":[{"t":"เพิ่ม read replica ให้กลุ่ม appliance เพื่อรองรับทราฟฟิกที่ตรวจสอบ","why":"ผิด — ไม่เกี่ยวกับ routing ของแพ็กเก็ต"},{"t":"เปลี่ยนโปรโตคอล encapsulation จาก GENEVE เป็น HTTP ระหว่าง GWLB กับ appliance","why":"ผิด — GENEVE เป็นกลไก encapsulation ที่ GWLB ใช้ ไม่ใช่สาเหตุ"},{"t":"ingress routing: route table ที่ผูกกับ internet gateway ชี้ prefix ของ subnet แอปไปที่ GWLB endpoint","why":"ถูกต้อง — ถ้าไม่มี route นี้แพ็กเก็ตจะไม่ผ่าน appliance"},{"t":"เปิด sticky session ที่ GWLB เพื่อให้แพ็กเก็ตเข้าทาง endpoint เสมอ","why":"ผิด — flow hash ของ GWLB ดูแลความสอดคล้องไป-กลับอยู่แล้ว ไม่ได้แก้ปัญหา route"}],"ans":2,"ref":"W11 · สไลด์ 41–42"},{"id":"w11-023","topic":"ELB","level":"apply","story":"","q":"API ต้องรองรับ request ที่ใช้เวลาประมวลผลของ Lambda ประมาณ 45 วินาที ตามตัวเลข default ในสไลด์ ตัวเลือกใดทำงานได้โดยไม่ต้องขยาย timeout?","opts":[{"t":"ALB -> Lambda เพราะ timeout default 60 วินาที","why":"ถูกต้อง — 45 < 60"},{"t":"API Gateway ที่ตั้งค่า default เพราะ timeout default 29 วินาที","why":"ผิด — 45 วินาทีเกิน 29 วินาที จะ timeout (REST ขยายได้แต่ต้องตั้งค่า)"},{"t":"NLB -> Lambda เพราะไม่มี timeout","why":"ผิด — NLB ไม่ใช่ตัวเลือกส่งตรงไป Lambda ตามตารางสไลด์"},{"t":"ไม่ได้ทั้งสองตัวเลือก ต้องใช้ GWLB","why":"ผิด — GWLB ใช้ตรวจสอบแพ็กเก็ตผ่าน appliance"}],"ans":0,"ref":"W11 · สไลด์ 43"},{"id":"w11-024","topic":"ELB","level":"apply","story":"","q":"เมื่อ target ตัวหนึ่งไม่ผ่าน ELB health check ในกลุ่มที่ ASG health check type เป็น EC2 เท่านั้น ผลที่ถูกต้องคือข้อใด?","opts":[{"t":"ASG ยุติและเปิด instance ใหม่ทันที เพราะ ELB รายงานว่า target ไม่ healthy","why":"ผิด — ASG แบบ EC2 ไม่รู้ว่าแอปพัง"},{"t":"ELB หยุดส่ง request ให้ target นั้น แต่ ASG ยังไม่ยุติ instance เพราะยังผ่าน EC2 status check","why":"ถูกต้อง — การตัดจาก rotation กับการแทนที่ instance เป็นสองกลไก ต้องตั้ง ASG health check เป็น ELB จึงแทนที่"},{"t":"ELB ยังส่ง request ให้ target ต่อไป เพราะ EC2 status check รายงานว่าปกติ","why":"ผิด — ELB ตัดสินจากผล health check ของตนเอง"},{"t":"target ถูกลบออกจาก target group อย่างถาวรและต้องลงทะเบียนใหม่ด้วยมือ","why":"ผิด — ยังอยู่ใน target group และกลับมารับ request ได้เมื่อผ่าน health check"}],"ans":1,"ref":"W11 · สไลด์ 28, 75"},{"id":"w11-025","topic":"ELB","level":"scen","story":"บริษัทพัฒนาเกมแบบ multiplayer เซิร์ฟเวอร์เกมสื่อสารด้วย UDP บน EC2 ใน Auto Scaling group ต้องการกระจายผู้เล่นหลายแสน connection พร้อมกัน latency ต่ำสุด ทีมเสนอใช้ ALB เพราะเป็นค่าเริ่มต้นสำหรับเว็บ","q":"ข้อใดเหมาะสมที่สุด?","opts":[{"t":"ใช้ ALB และเปลี่ยน client เป็น HTTP long polling โดยไม่แก้เกม","why":"ผิด — ALB รองรับเฉพาะ HTTP/HTTPS ไม่รองรับ UDP และการเปลี่ยนโปรโตคอลเกมไม่สมเหตุผล"},{"t":"ใช้ GWLB ส่งแพ็กเก็ต UDP ผ่าน appliance","why":"ผิด — GWLB ไม่ใช่ตัวกระจายโหลดไปแอป"},{"t":"ใช้ Classic Load Balancer เพราะรองรับ Layer 3 และ 7","why":"ผิด — CLB เป็น legacy ห้ามใช้กับงานใหม่"},{"t":"ใช้ NLB เพราะรองรับ UDP และ throughput สูง latency ต่ำ","why":"ถูกต้อง — NLB รองรับโปรโตคอลบน TCP/UDP"}],"ans":3,"ref":"W11 · สไลด์ 27, 34"},{"id":"w11-026","topic":"ELB","level":"scen","story":"SaaS provider วางบริการแบบรวมศูนย์บน EC2 ใน ASG หลาย AZ ลูกค้ากว่า 200 รายอยู่คนละ VPC บางรายใช้ CIDR ซ้อนทับกัน และไม่ต้องการให้ทราฟฟิกออก Internet ทีมไม่อยากทำ VPC peering ทีละราย","q":"ควรออกแบบอย่างไร?","opts":[{"t":"ใช้ ALB internet-facing แล้วให้ลูกค้าเรียกผ่าน Internet","why":"ผิด — ทราฟฟิกต้องออก Internet ขัดโจทย์"},{"t":"วาง NLB หน้าบริการ แล้วเผยแพร่เป็น endpoint service","why":"ถูกต้อง — PrivateLink ต้องมี NLB (หรือ GWLB) ด้านหน้า ไม่ผ่าน Internet ไม่ต้อง peering และไม่ติดปัญหา IP ซ้อน"},{"t":"ทำ VPC peering กับทุกลูกค้า","why":"ผิด — CIDR ซ้อนทับทำ peering ไม่ได้ และต้องจัดการรายราย"},{"t":"ใช้ Route 53 weighted routing ชี้ไป IP ของ instance","why":"ผิด — ยังเป็นการเข้าผ่านเครือข่ายสาธารณะ และไม่ใช่กลไก private connectivity"}],"ans":1,"ref":"W11 · สไลด์ 34, 39"},{"id":"w11-027","topic":"ELB","level":"scen","story":"องค์กรต้องส่งทราฟฟิกทุกชุดที่เข้า-ออก VPC ผ่าน firewall และ IDS/IPS ของบุคคลที่สามก่อนถึงแอป appliance ต้อง scale ได้ตามปริมาณทราฟฟิก และการเพิ่ม/ลด appliance ต้องไม่ต้องแก้ route ของแอป","q":"ข้อใดเหมาะสมที่สุด?","opts":[{"t":"ALB ที่มี WAF หน้าแอป","why":"ผิด — WAF บน ALB กรอง HTTP เท่านั้น ไม่ใช่การตรวจแพ็กเก็ตด้วย appliance ของบุคคลที่สาม"},{"t":"NLB ที่ forward ไป firewall instance โดยตรง","why":"ผิด — NLB เป็น Layer 4 ที่มีปลายทางที่แอป และไม่ทำ transparent bump-in-the-wire"},{"t":"Gateway Load Balancer + GWLB endpoint","why":"ถูกต้อง — GWLB เป็นทั้ง transparent gateway และ load balancer ที่ health-check กลุ่ม appliance"},{"t":"วาง firewall เพียงตัวเดียวใน subnet แล้วชี้ route table ไปที่ตัวนั้น","why":"ผิด — เป็นจุดล้มเหลวเดี่ยวและ scale ไม่ได้"}],"ans":2,"ref":"W11 · สไลด์ 27, 40"},{"id":"w11-028","topic":"ELB","level":"scen","story":"ระบบ 3 tier: ALB ด้านหน้า, web ใน ASG, ALB ภายใน, app ใน ASG, ฐานข้อมูล RDS Multi-AZ ทุกชั้นกระจายอยู่ใน AZ1 และ AZ2 เกิดเหตุ AZ1 ล่มทั้ง AZ","q":"ผลที่คาดได้ตามสถาปัตยกรรมนี้คืออะไร?","opts":[{"t":"ระบบล่มทั้งหมด จนกว่า ASG จะสร้าง VPC และ subnet ใหม่ขึ้นมาแทน AZ1","why":"ผิด — VPC ครอบ 2 AZ อยู่แล้ว"},{"t":"เฉพาะชั้นฐานข้อมูลล่ม เพราะ RDS Multi-AZ ไม่มี failover อัตโนมัติ ต้องกู้ด้วยมือ","why":"ผิด — Multi-AZ failover อัตโนมัติ endpoint DNS ชี้ไป standby"},{"t":"internal ALB หยุดทำงานเพราะเป็น private จึงต้องรอ operator สลับ AZ ให้","why":"ผิด — ELB ให้บริการข้ามหลาย AZ และไม่ต้องใช้คนสลับ"},{"t":"ทราฟฟิกวิ่งผ่าน AZ2 ต่อ","why":"ถูกต้อง — ทุกชั้นซ้ำซ้อนข้าม AZ ไม่มี single point of failure ต่อชั้น"}],"ans":3,"ref":"W11 · สไลด์ 26, 38"},{"id":"w11-029","topic":"ELB","level":"scen","story":"แอปตะกร้าสินค้าเก็บข้อมูล session ในหน่วยความจำของ web instance ทีมเปิด ALB sticky session ไว้ ผลคือ client ที่โหลดหนักถูกตรึงที่ instance เดียวจน CPU สูง และเมื่อ instance ถูกแทนที่ผู้ใช้เสียตะกร้า","q":"แนวทางแก้ที่ตรงจุดที่สุดคืออะไร?","opts":[{"t":"ขยาย duration ของ cookie เป็น 7 วัน เพื่อให้การตรึงผู้ใช้ครอบคลุมนานขึ้น","why":"ผิด — ยิ่งตรึงนาน โหลดยิ่งไม่สม่ำเสมอและ session ยังตายตาม instance"},{"t":"ย้าย session ไปไว้ shared store เช่น ElastiCache หรือ DynamoDB ให้ instance ใดก็ตอบได้ (stateless)","why":"ถูกต้อง — แก้สาเหตุคือแอปเก็บ state ในเครื่อง"},{"t":"เปลี่ยนเป็น NLB และใช้ sticky แบบ source IP แทน cookie ของ ALB","why":"ผิด — ยังเป็นการตรึง state ไว้ในเครื่อง ปัญหาเดิมยังอยู่"},{"t":"เพิ่ม max capacity ของ ASG อย่างเดียว เพื่อให้มี instance รับโหลดมากขึ้น","why":"ผิด — เพิ่ม instance ไม่ช่วยให้ session รอดเมื่อ instance ล้มเหลว"}],"ans":1,"ref":"W11 · สไลด์ 37"},{"id":"w11-030","topic":"ELB","level":"scen","story":"เว็บแอปเดิมบน EC2 กำลังย้ายทีละส่วนไป serverless: path /checkout/* เป็น Lambda ใหม่ ส่วน path อื่นยังเป็น EC2 หลัง ALB ที่ใช้งานอยู่ volume สูงสม่ำเสมอตลอดวัน","q":"ทางเลือกใดสมเหตุสมผลที่สุด?","opts":[{"t":"สร้าง API Gateway ใหม่ทั้งชุดและย้ายทุก path","why":"ผิด — ผสม EC2 target แบบเดิมไม่ได้และจ่ายต่อ request แพงขึ้นเมื่อ volume สูง"},{"t":"วาง NLB หน้า Lambda และใช้ flow hash แยก path","why":"ผิด — NLB ไม่เห็น path"},{"t":"สร้าง ALB ตัวที่สองเฉพาะ Lambda แล้วให้ผู้ใช้เลือกโดเมนเอง","why":"ผิด — ไม่จำเป็นและสร้างค่าใช้จ่ายรายชั่วโมงซ้ำ ทั้งที่ listener rule ทำได้"},{"t":"เพิ่ม Lambda เป็น target group","why":"ถูกต้อง — ALB ผสม Lambda กับ EC2 ใน listener เดียวได้ และถูกเมื่อ volume สูงสม่ำเสมอ"}],"ans":3,"ref":"W11 · สไลด์ 29, 43"},{"id":"w11-031","topic":"ELB","level":"scen","story":"API หลัง ALB (round robin) มี endpoint รายงาน ใช้เวลา 5–8 วินาที ปนกับ endpoint ปกติ 50 ms เมื่อรายงานถูกเรียกพร้อมกัน target บางตัวมี request ค้างหลายสิบรายการ ขณะตัวอื่นเกือบว่าง CPU เฉลี่ยของ ASG ยังไม่ถึงเกณฑ์ scale","q":"การเปลี่ยนใดแก้ตรงสาเหตุที่สุด?","opts":[{"t":"ตั้ง min capacity เป็นสองเท่า","why":"ผิด — เพิ่ม target แต่ round robin ยังส่งงานหนักสลับแบบไม่ดูคิว และเพิ่มค่าใช้จ่าย"},{"t":"ตั้ง algorithm ของ target group เป็น least outstanding requests","why":"ถูกต้อง — ส่ง request ใหม่ไป target ที่มีงานค้างน้อยสุด ลดการสะสมคิวที่ตัวหนัก"},{"t":"เปลี่ยนเป็น NLB เพื่อลด latency","why":"ผิด — flow hash ตรึงแบบ connection และไม่ดูงานค้าง"},{"t":"เปิด sticky session ด้วย cookie 1 วัน","why":"ผิด — ตรึงผู้ใช้กับ target ทำให้โหลดไม่สม่ำเสมอยิ่งขึ้น"}],"ans":1,"ref":"W11 · สไลด์ 35, 37"},{"id":"w11-032","topic":"ELB","level":"scen","story":"ข้อกำหนด compliance ระบุว่าทราฟฟิกต้องเข้ารหัส TLS จาก client ถึง application server และ load balancer ห้ามถือ private key แอปให้บริการ TCP บน port 443 หลาย instance ใน ASG","q":"ข้อใดเหมาะสมที่สุด?","opts":[{"t":"ALB HTTPS listener ใช้ใบรับรองจาก ACM","why":"ผิด — ALB terminate TLS และถือคีย์เพื่ออ่าน header จึงขัดข้อกำหนด"},{"t":"NLB แบบ TCP listener พอร์ต 443 ส่ง TLS ที่ยังเข้ารหัสไปถึง target","why":"ถูกต้อง — NLB ไม่ถอดรหัสในโหมด pass-through จึงรักษา end-to-end encryption"},{"t":"ALB HTTP listener พอร์ต 80 แล้วเข้ารหัสที่ชั้นแอปเอง","why":"ผิด — เป็นการเปลี่ยนโจทย์และไม่ใช่ TLS จาก client ถึง server ตามที่กำหนด"},{"t":"GWLB ตรวจแพ็กเก็ตแล้ว forward ไปยัง instance","why":"ผิด — GWLB ไม่ใช่ตัวกระจายโหลดสำหรับแอปและไม่ได้แก้เรื่องคีย์"}],"ans":1,"ref":"W11 · สไลด์ 31"},{"id":"w11-033","topic":"ELB","level":"scen","story":"ทีม DevOps สร้าง target group และ ALB listener ถูกต้อง instance แรกสองตัวรับทราฟฟิกได้ แต่เมื่อ ASG scale out เปิด instance ใหม่ ตัวใหม่ไม่เคยได้รับ request ทั้งที่แอปบน instance ใหม่ทำงานปกติ","q":"สาเหตุที่น่าจะเป็นที่สุดคืออะไร?","opts":[{"t":"ALB ไม่รองรับ instance ที่เปิดขึ้นหลังจากสร้าง listener เสร็จแล้ว","why":"ผิด — ELB รองรับ target ที่เพิ่มภายหลัง"},{"t":"ต้องเพิ่ม instance ใหม่เข้า listener rule ด้วยมือทุกครั้งที่ scale out","why":"ผิด — rule ชี้ไปที่ target group ไม่ใช่ instance รายตัว"},{"t":"ASG ไม่ได้ผูก (attach) กับ target group ทำให้ instance ใหม่ไม่ถูกลงทะเบียน","why":"ถูกต้อง — ASG ต้องเป็นฝ่ายลงทะเบียน instance เข้า target group ที่ LB อ่าน"},{"t":"health check ถูกปิดไว้ ทำให้ LB ตัด instance ใหม่ออกจากการหมุนเวียน","why":"ผิด — ถ้าไม่มี health check ก็ไม่ใช่เหตุให้ตัดทิ้ง และอาการนี้ชี้ที่การลงทะเบียนมากกว่า"}],"ans":2,"ref":"W11 · สไลด์ 28, 49–50"},{"id":"w11-034","topic":"ELB","level":"scen","story":"สถาปัตยกรรม 3 tier ต้องให้ชั้น app เรียกได้เฉพาะจากชั้น web ภายใน VPC และไม่ให้เข้าถึงจาก Internet ชั้น web รับจากผู้ใช้ทั่วโลก ทั้งสองชั้นต้องกระจายโหลดข้าม 2 AZ","q":"ออกแบบ load balancer อย่างไร?","opts":[{"t":"ALB internet-facing ตัวเดียวหน้าทั้งสองชั้น โดยใช้ listener rule แยกตาม path","why":"ผิด — ชั้น app จะเปิดสู่ Internet ขัดข้อกำหนด"},{"t":"internal ALB หน้าชั้น web เท่านั้น แล้วให้ web เรียก instance ชั้น app ตรง ๆ","why":"ผิด — ผู้ใช้ Internet เข้า web ไม่ได้ และชั้น app ไม่มีการกระจายโหลด/health check"},{"t":"ALB internet-facing หน้าชั้น web และ internal ALB หน้าชั้น app","why":"ถูกต้อง — ELB รองรับทั้ง public และ private และแยก scale/ล้มเหลวอิสระตามแผนภาพสไลด์ 38"},{"t":"NLB หน้าชั้น web เพราะ ALB ใช้ได้เฉพาะแบบ internal เท่านั้น","why":"ผิด — ALB รองรับ internet-facing ด้วย"}],"ans":2,"ref":"W11 · สไลด์ 26, 38"},{"id":"w11-035","topic":"ELB","level":"scen","story":"เว็บแอปบน ALB (HTTPS) ใช้ใบรับรองที่ซื้อนอก AWS และนำเข้ามาเอง ฝ่ายปฏิบัติการต้องเปลี่ยนใบรับรองด้วยมือทุกปีและเคยลืมจนเว็บขึ้นเตือนใบรับรองหมดอายุ","q":"แนวทางใดลดความเสี่ยงนี้ตามกลไกในสไลด์?","opts":[{"t":"ใช้ใบรับรองจาก ACM ผูกกับ HTTPS listener","why":"ถูกต้อง — ACM ออกและต่ออายุใบรับรองที่ผูกกับ listener ให้อัตโนมัติ"},{"t":"เปลี่ยน listener เป็น HTTP:80 เพื่อไม่ต้องใช้ใบรับรอง","why":"ผิด — ข้อมูลไม่ถูกเข้ารหัสระหว่างทาง ขัดหลัก protect data in transit"},{"t":"ย้ายไปใช้ Classic Load Balancer เพราะไม่ต้องมีใบรับรอง","why":"ผิด — CLB เป็น legacy และไม่ได้ลดงานดูแลใบรับรอง"},{"t":"เพิ่ม sticky session ให้ผู้ใช้เก็บ session ของใบรับรองเดิม","why":"ผิด — ไม่เกี่ยวกับการหมดอายุของใบรับรอง"}],"ans":0,"ref":"W11 · สไลด์ 10, 29"},{"id":"w11-036","topic":"ELB","level":"scen","story":"บริษัทเปิดเกมแบบ real-time (UDP) พร้อมพอร์ทัลผู้ดูแลระบบแบบเว็บ (HTTPS) ที่ต้องมี WAF, user authentication และ route /admin ไปยังบริการแยก","q":"ข้อใดเหมาะสมที่สุด?","opts":[{"t":"ใช้ ALB ตัวเดียวสำหรับทั้งสอง","why":"ผิด — ALB ไม่รองรับ UDP"},{"t":"ใช้ NLB สำหรับ UDP ของเกม และ ALB สำหรับพอร์ทัลเว็บ","why":"ถูกต้อง — แต่ละตัวทำสิ่งที่อีกตัวทำไม่ได้: UDP เป็นของ NLB, WAF/auth/path routing เป็นของ ALB"},{"t":"ใช้ NLB ตัวเดียวสำหรับทั้งสอง","why":"ผิด — NLB ไม่รองรับ WAF/authentication และ routing ตาม path"},{"t":"ใช้ GWLB ตัวเดียวสำหรับทั้งสอง","why":"ผิด — GWLB ส่งแพ็กเก็ตผ่าน appliance ไม่ใช่ load balancer ของแอป"}],"ans":1,"ref":"W11 · สไลด์ 33–34"},{"id":"w11-037","topic":"Well-Architected และ Reliability","level":"know","story":"","q":"ข้อใดไม่ใช่ pillar ของ AWS Well-Architected Framework?","opts":[{"t":"Sustainability","why":"เป็น pillar (ที่หก) ว่าด้วยการลดผลกระทบต่อสิ่งแวดล้อม"},{"t":"Elasticity","why":"ถูกต้อง — ไม่ใช่ pillar elasticity เป็นคุณสมบัติที่ได้จากการ scale"},{"t":"Operational Excellence","why":"เป็น pillar ว่าด้วยการดำเนินงานและปรับปรุงกระบวนการ"},{"t":"Performance Efficiency","why":"เป็น pillar ว่าด้วยการเลือกทรัพยากรให้เหมาะกับความต้องการ"}],"ans":1,"ref":"W11 · สไลด์ 6"},{"id":"w11-038","topic":"Well-Architected และ Reliability","level":"know","story":"","q":"ตามสไลด์ ข้อใดคือนิยามของ MTBF?","opts":[{"t":"MTBF = MTTF − MTTR","why":"ผิด — เวลาซ่อมถูกบวก ไม่ใช่ลบ"},{"t":"MTBF = MTTF + MTTR หรือเวลารวมที่ระบบให้บริการหารด้วยจำนวนครั้งที่ล้มเหลว","why":"ถูกต้อง — MTBF ครอบคลุมช่วงทำงานจนล้มเหลวบวกช่วงซ่อม"},{"t":"MTBF คือเวลาเฉลี่ยจากล้มเหลวจนซ่อมเสร็จเท่านั้น","why":"ผิด — นั่นคือ MTTR"},{"t":"MTBF คือเวลาเฉลี่ยจากออนไลน์จนล้มเหลวครั้งแรกเท่านั้น","why":"ผิด — นั่นคือ MTTF"}],"ans":1,"ref":"W11 · สไลด์ 21–22"},{"id":"w11-039","topic":"Well-Architected และ Reliability","level":"know","story":"","q":"AWS Trusted Advisor ให้คำแนะนำในหมวดใดตามสไลด์?","opts":[{"t":"เฉพาะ Cost Optimization และ Billing","why":"ผิด — มีห้าหมวด ไม่ใช่เฉพาะด้านค่าใช้จ่าย"},{"t":"Cost Optimization, Performance, Security, Fault Tolerance และ Service Limits","why":"ถูกต้อง — ห้าหมวดตามสไลด์"},{"t":"Compute, Storage, Network, Database และ Analytics","why":"ผิด — นั่นเป็นหมวดบริการ ไม่ใช่หมวดคำแนะนำ"},{"t":"Operational Excellence, Reliability, Sustainability, Agility และ Governance","why":"ผิด — ไม่ใช่รายการหมวดที่สไลด์ระบุ"}],"ans":1,"ref":"W11 · สไลด์ 19"},{"id":"w11-040","topic":"Well-Architected และ Reliability","level":"apply","story":"","q":"ระบบต้องมี downtime รวมไม่เกินประมาณ 5 นาทีต่อปี (เช่น ระบบ ATM) ต้องมีเป้า availability ระดับใดตามตาราง?","opts":[{"t":"99.99% (four 9s)","why":"ผิด — อนุญาต downtime ราว 52 นาทีต่อปี"},{"t":"99.95%","why":"ผิด — อนุญาตราว 4 ชั่วโมง 22 นาที"},{"t":"99.999% (five 9s)","why":"ถูกต้อง — ประมาณ 5 นาทีต่อปี"},{"t":"99.9%","why":"ผิด — อนุญาตราว 8 ชั่วโมง 45 นาที"}],"ans":2,"ref":"W11 · สไลด์ 23, 25"},{"id":"w11-041","topic":"Well-Architected และ Reliability","level":"apply","story":"","q":"สามคอมโพเนนต์ต่อกันแบบอนุกรม (ตัวใดตัวหนึ่งเสียระบบเสีย) แต่ละตัว reliability 0.99 reliability ของระบบรวมใกล้เคียงข้อใด?","opts":[{"t":"0.99 เท่ากับแต่ละตัว","why":"ผิด — การต่ออนุกรมทำให้ reliability รวมลดลง"},{"t":"0.997 เพราะเฉลี่ยกัน","why":"ผิด — ไม่ใช้ค่าเฉลี่ย ต้องคูณ"},{"t":"ประมาณ 1.0 เพราะมีหลายตัวช่วยกัน","why":"ผิด — ช่วยกันคือการต่อขนาน (redundancy) ไม่ใช่อนุกรม"},{"t":"ประมาณ 0.970 เพราะคูณกัน 0.99³","why":"ถูกต้อง (เพิ่มเติม) — อนุกรมคือผลคูณ จึงต่ำกว่าตัวที่ต่ำสุด"}],"ans":3,"ref":"W11 · สไลด์ 21"},{"id":"w11-042","topic":"Well-Architected และ Reliability","level":"apply","story":"","q":"ทีมเปลี่ยนฐานข้อมูลจาก Single-AZ เป็น Multi-AZ เพื่อเพิ่มความทนทาน ผลกระทบต่อ pillar ใดที่ต้องชั่งน้ำหนักควบคู่กับ Reliability?","opts":[{"t":"Cost Optimization เพราะต้องจ่ายสำหรับ standby เพิ่ม","why":"ถูกต้อง — pillar ต่าง ๆ มี trade-off กัน เพิ่ม redundancy ทำให้ต้นทุนสูงขึ้น"},{"t":"Sustainability เสียหายทันที เพราะ Multi-AZ ห้ามใช้ managed service","why":"ผิด — ไม่มีกฎดังกล่าว"},{"t":"Security ถูกยกเลิก เพราะ standby ใช้การเข้ารหัสไม่ได้","why":"ผิด — ไม่มีการลดการเข้ารหัสจากการทำ Multi-AZ"},{"t":"ไม่มี pillar ใดได้รับผลกระทบ เพราะ pillar เป็นอิสระต่อกัน","why":"ผิด — กรอบนี้ต้องยอมรับ trade-off ระหว่าง pillar"}],"ans":0,"ref":"W11 · สไลด์ 5, 15"},{"id":"w11-043","topic":"Well-Architected และ Reliability","level":"scen","story":"เว็บร้านค้ารัน EC2 หลาย instance ข้าม 2 AZ หลัง ALB (fault tolerance ดี) แต่ใช้ instance จำนวนคงที่ 4 ตัว ช่วง flash sale ทราฟฟิกเป็น 6 เท่าของปกติและบริการล่มเพราะภาระเกินความจุ แม้ไม่มี component ใดเสีย","q":"ตามปัจจัยด้าน availability ในสไลด์ จุดอ่อนหลักคือข้อใด?","opts":[{"t":"Fault tolerance — ต้องเพิ่ม AZ ที่สามอย่างเดียว","why":"ผิด — ไม่มี component เสียและมี 2 AZ แล้ว"},{"t":"Recoverability — ต้องทำ backup บ่อยขึ้น","why":"ผิด — ไม่ใช่เหตุการณ์ร้ายแรงที่ต้องฟื้นข้อมูล"},{"t":"Scalability — ไม่สามารถรองรับความจุที่เพิ่มขึ้นโดยไม่เปลี่ยนการออกแบบ","why":"ถูกต้อง — ปัญหาคือโหลดเกินความจุ ไม่ใช่ความซ้ำซ้อน"},{"t":"Sustainability — ต้องย้ายไป Region พลังงานสะอาด","why":"ผิด — เป็น pillar ที่ไม่เกี่ยวกับการล่มจากโหลด"}],"ans":2,"ref":"W11 · สไลด์ 44"},{"id":"w11-044","topic":"Well-Architected และ Reliability","level":"scen","story":"เซิร์ฟเวอร์ล้มเฉลี่ยทุก 500 ชั่วโมง (MTTF) การกู้คืนด้วยมือใช้เวลา 2 ชั่วโมง ทีมกำลังเลือกระหว่างซื้อฮาร์ดแวร์ที่ MTTF เพิ่มเป็น 600 ชั่วโมง กับทำ auto recovery ให้ MTTR เหลือประมาณ 5 นาที (0.083 ชั่วโมง) ใช้ availability ≈ MTTF/(MTTF+MTTR)","q":"ข้อใดสรุปได้ถูกต้อง?","opts":[{"t":"auto recovery ให้ ≈ 99.983% ดีกว่าฮาร์ดแวร์ใหม่ที่ ≈ 99.67% เพราะการลด MTTR มีผลมาก","why":"ถูกต้อง (เพิ่มเติม) — 500/500.083 ≈ 99.983% ส่วน 600/602 ≈ 99.67%"},{"t":"hardware ใหม่ดีกว่า เพราะ 600/602 ให้ประมาณ 99.99% ซึ่งสูงกว่าแบบ auto recovery","why":"ผิด — 600/602 ≈ 99.67%"},{"t":"ทั้งสองทางให้ availability เท่ากัน เพราะ MTBF ของทั้งสองทางเท่ากัน","why":"ผิด — MTBF ต่างกัน และ availability ขึ้นกับสัดส่วน MTTF ต่อ MTBF"},{"t":"auto recovery ไม่เปลี่ยน availability เพราะไม่ได้ลดจำนวนครั้งที่ล้ม","why":"ผิด — availability ขึ้นกับ MTTR ด้วย ถึงล้มเท่าเดิมก็ได้เวลาให้บริการเพิ่ม"}],"ans":0,"ref":"W11 · สไลด์ 22–23"},{"id":"w11-045","topic":"Auto Scaling","level":"know","story":"","q":"ตามสไลด์ vertical scaling กับ horizontal scaling ต่างกันอย่างไร?","opts":[{"t":"vertical แทนที่ resource ด้วยตัวที่ขนาดต่างกัน","why":"ถูกต้อง — scale up/down คือขนาด scale out/in คือจำนวน"},{"t":"vertical เพิ่มจำนวน instance ส่วน horizontal เปลี่ยนขนาดของ instance ที่มีอยู่","why":"ผิด — สลับความหมาย"},{"t":"vertical ใช้ได้เฉพาะกับฐานข้อมูล ส่วน horizontal ใช้ได้เฉพาะกับ EC2","why":"ผิด — ทั้งสองแบบเป็นแนวคิดทั่วไป"},{"t":"ทั้งสองแบบเป็นการเพิ่มจำนวน instance แต่ต่างกันที่จำนวน AZ ที่ใช้","why":"ผิด — ต่างกันที่ขนาด/จำนวน ไม่ใช่ AZ"}],"ans":0,"ref":"W11 · สไลด์ 48"},{"id":"w11-046","topic":"Auto Scaling","level":"know","story":"","q":"Launch template ของ Auto Scaling group กำหนดสิ่งใด?","opts":[{"t":"ค่า min/max/desired capacity","why":"ผิด — ค่า capacity เป็นของ ASG"},{"t":"เกณฑ์ที่ alarm ใช้ scale","why":"ผิด — อยู่ที่ scaling policy/CloudWatch alarm"},{"t":"วิธีสร้าง instance เช่น AMI ID, instance type, key pair, security group","why":"ถูกต้อง — มี version ได้"},{"t":"path routing ของ listener","why":"ผิด — เป็นเรื่องของ ALB listener rule"}],"ans":2,"ref":"W11 · สไลด์ 49–50"},{"id":"w11-047","topic":"Auto Scaling","level":"know","story":"","q":"กลไก scaling ของ EC2 Auto Scaling แบบใดใช้ machine learning วิเคราะห์รูปแบบทราฟฟิกในอดีตเพื่อเตรียมความจุล่วงหน้า?","opts":[{"t":"Dynamic scaling policy","why":"ผิด — ตอบสนองต่อ metric ที่ติดตาม (reactive)"},{"t":"Scheduled action","why":"ผิด — ตามวันเวลาที่กำหนดเอง ไม่ใช้ ML"},{"t":"Step scaling policy","why":"ผิด — เป็นประเภทหนึ่งของ dynamic ที่ปรับตามขนาดการฝ่า threshold"},{"t":"Predictive scaling policy","why":"ถูกต้อง — proactive ใช้ ML จากรูปแบบเดิม"}],"ans":3,"ref":"W11 · สไลด์ 51"},{"id":"w11-048","topic":"Auto Scaling","level":"apply","story":"","q":"ASG มี 10 instance step scaling ตามตาราง (71–100% = +30%, 61–70% = +10%, 40–60% = ไม่เปลี่ยน) CPU เฉลี่ยขึ้นเป็น 75% ผลคือ?","opts":[{"t":"เพิ่ม 3 instance (+30% ของ 10)","why":"ถูกต้อง — 75% อยู่ในช่วง 71–100%"},{"t":"เพิ่ม 1 instance","why":"ผิด — นั่นคือ +10% ของช่วง 61–70%"},{"t":"ไม่เปลี่ยน","why":"ผิด — 75% อยู่นอกช่วง 40–60%"},{"t":"เพิ่ม 7 instance","why":"ผิด — ไม่มีขั้นที่ให้เพิ่ม 70%"}],"ans":0,"ref":"W11 · สไลด์ 53"},{"id":"w11-049","topic":"Auto Scaling","level":"apply","story":"","q":"ASG มี 20 instance step scaling ตามตาราง (30–39% = −10%, น้อยกว่า 30% = −30%) CPU เฉลี่ยเป็น 35% ผลคือ?","opts":[{"t":"ลด 6 instance","why":"ผิด — −30% ใช้กับ CPU ต่ำกว่า 30%"},{"t":"ลด 2 instance (−10%)","why":"ถูกต้อง — 35% อยู่ในช่วง 30–39% ลดเป็นเปอร์เซ็นต์ของความจุปัจจุบัน"},{"t":"ไม่เปลี่ยน","why":"ผิด — ช่วงไม่เปลี่ยนคือ 40–60%"},{"t":"เพิ่ม 2 instance","why":"ผิด — CPU ต่ำ ไม่ใช่สูง ต้อง scale in"}],"ans":1,"ref":"W11 · สไลด์ 53"},{"id":"w11-050","topic":"Auto Scaling","level":"apply","story":"","q":"ASG ตั้ง min = 1, desired = 2, max = 3 เมื่อโหลดสูงต่อเนื่องจน scale out ครบ แล้วโหลดยังเพิ่มอีก จะเกิดอะไร?","opts":[{"t":"เปิดเป็น 4 instance เพราะ desired ปรับได้ไม่จำกัด","why":"ผิด — desired ต้องอยู่ระหว่าง min และ max"},{"t":"ลดลงเหลือ 1 instance เพื่อประหยัดตาม min","why":"ผิด — min คือขอบล่างของ scale in"},{"t":"ASG แจ้ง ELB ให้หยุดรับ request","why":"ผิด — ASG ไม่ได้สั่งหยุดรับทราฟฟิก แค่ถึงเพดานความจุ"},{"t":"ASG หยุดที่ 3 instance เพราะ max เป็นเพดาน","why":"ถูกต้อง — max ป้องกันค่าใช้จ่ายพุ่ง"}],"ans":3,"ref":"W11 · สไลด์ 50, 52"},{"id":"w11-051","topic":"Auto Scaling","level":"apply","story":"","q":"ต้อง scale ตารางของ DynamoDB และ ECS service ด้วยนโยบาย target tracking จากจุดเดียว ควรใช้บริการใด?","opts":[{"t":"EC2 Auto Scaling เท่านั้น","why":"ผิด — ปรับจำนวน instance ภายใน ASG ไม่ใช่ DynamoDB/ECS"},{"t":"ELB health check","why":"ผิด — ไม่ใช่กลไก scale ความจุ"},{"t":"Route 53 weighted routing","why":"ผิด — กระจายทราฟฟิก DNS ไม่ได้ปรับความจุทรัพยากร"},{"t":"Application Auto Scaling (หรือ AWS Auto Scaling ผ่าน scaling plan)","why":"ถูกต้อง — scale หลายทรัพยากรด้วย target tracking/step/scheduled"}],"ans":3,"ref":"W11 · สไลด์ 54, 63"},{"id":"w11-052","topic":"Auto Scaling","level":"scen","story":"API ที่ใช้ ASG พร้อม max capacity สูงมาก ถูกยิง request ปลอมจำนวนมากจากบอตเน็ต instance ขยายจนบิลเดือนนี้สูงผิดปกติหลายเท่า แม้บริการยังตอบได้ ตามนิยาม EDoS","q":"แนวทางป้องกันใดตรงจุดที่สุด?","opts":[{"t":"ตั้ง max capacity ที่เหมาะสม ตั้ง AWS Budgets/billing alarm และกรองทราฟฟิกด้วย AWS WAF ที่ ALB","why":"ถูกต้อง — จำกัดเพดานการขยาย แจ้งเตือนค่าใช้จ่าย และกรองทราฟฟิกที่ไม่พึงประสงค์"},{"t":"ตั้ง min capacity ให้เท่ากับ max capacity เพื่อให้มีความจุสูงสุดตลอดเวลา","why":"ผิด — เพิ่มค่าใช้จ่ายถาวรโดยไม่กรองทราฟฟิกโจมตี"},{"t":"เปลี่ยน ASG ไปใช้ scheduled action เท่านั้นแทน dynamic policy","why":"ผิด — ไม่ได้กรองทราฟฟิกที่ไม่พึงประสงค์"},{"t":"เพิ่ม instance type ให้ใหญ่ขึ้นอย่างเดียว เพื่อรับ request ปลอมได้มากขึ้น","why":"ผิด — ต้นทุนต่อเครื่องสูงขึ้น ไม่แก้ที่ต้นทาง"}],"ans":0,"ref":"W11 · สไลด์ 56"},{"id":"w11-053","topic":"Auto Scaling","level":"scen","story":"ระบบจองตั๋วมีโหลดสูงขึ้นทุกวันธรรมดาตอน 09:00 และลดลงตอน 18:00 อย่างคาดการณ์ได้ แต่ CPU-based dynamic scaling เพิ่งเริ่มเพิ่ม instance หลัง 09:00 ผู้ใช้ช่วง 09:00–09:05 เจอ latency สูงเพราะ instance ใหม่ยังเปิดไม่เสร็จ","q":"ปรับอย่างไรจึงตรงสาเหตุ?","opts":[{"t":"ลด threshold ของ alarm ลงเหลือ 5% CPU เพื่อให้ scale out ตั้งแต่ต้นวัน","why":"ผิด — เพิ่ม scale out ผิดจังหวะตลอดวันและยังรอเปิด instance"},{"t":"ใช้ vertical scaling รีสตาร์ท instance เป็นขนาดใหญ่ก่อน 09:00","why":"ผิด — ต้อง restart เกิด downtime และเป็นจุดล้มเหลวเดี่ยว"},{"t":"เพิ่ม min capacity เป็น max ตลอด 24 ชั่วโมงทุกวัน","why":"ผิด — แก้ได้แต่ไม่ elastic และสิ้นเปลืองนอกช่วงโหลดสูง"},{"t":"เพิ่ม scheduled action (หรือ predictive policy) ให้ขยายความจุก่อน 09:00 ผสม dynamic รับส่วนที่เกินคาด","why":"ถูกต้อง — dynamic เป็น reactive ส่วน scheduled/predictive เป็น proactive"}],"ans":3,"ref":"W11 · สไลด์ 48, 51"},{"id":"w11-054","topic":"Scaling ฐานข้อมูล","level":"know","story":"","q":"ทำไม Aurora เพิ่ม read replica ได้เร็วตามสไลด์?","opts":[{"t":"ทุก DB instance ใช้ cluster volume ร่วมกัน replica ใหม่จึงไม่ต้องคัดลอกข้อมูลทั้งชุด","why":"ถูกต้อง — storage แยกจาก compute"},{"t":"replica แต่ละตัวมี EBS volume ของตนและคัดลอกข้อมูลด้วย asynchronous replication","why":"ผิด — นั่นคือสถาปัตยกรรม RDS read replica"},{"t":"Aurora โหลดข้อมูลจาก S3 โดยตรงทุกครั้งที่ replica ใหม่เริ่มทำงาน","why":"ผิด — ใช้ cluster volume ที่เก็บสำเนาบน EBS ในแต่ละ AZ"},{"t":"Aurora ไม่ต้องมี storage ร่วมกัน เพราะ replica อ่านจาก memory ของ writer","why":"ผิด — มี cluster volume ที่ scale โดยบริการ"}],"ans":0,"ref":"W11 · สไลด์ 60"},{"id":"w11-055","topic":"Scaling ฐานข้อมูล","level":"know","story":"","q":"ACU (Aurora Capacity Unit) คืออะไร?","opts":[{"t":"หน่วยความจุเขียนของ DynamoDB","why":"ผิด — ของ DynamoDB คือ RCU/WCU"},{"t":"หน่วยคิดค่าใช้จ่ายของ ALB ตามจำนวน connection","why":"ผิด — ALB ใช้ LCU"},{"t":"หน่วยกำลังประมวลผลและหน่วยความจำของ Aurora Serverless","why":"ถูกต้อง — กำหนด ACU ต่ำสุด/สูงสุดของ cluster"},{"t":"หน่วยจำนวน read replica ของ RDS","why":"ผิด — ไม่ใช่หน่วยจำนวน replica"}],"ans":2,"ref":"W11 · สไลด์ 61"},{"id":"w11-056","topic":"Scaling ฐานข้อมูล","level":"apply","story":"","q":"แอปเขียนที่ primary ของ RDS แล้วอ่านทันทีจาก read replica เป็นบางครั้งไม่เห็นข้อมูลที่เพิ่งเขียน สาเหตุเชิงกลไกคืออะไร?","opts":[{"t":"read replica เป็น synchronous จึงช้ากว่าและเขียนทีละรายการ","why":"ผิด — read replica เป็น asynchronous"},{"t":"replica ไม่สามารถอ่านข้อมูลได้เลยจนกว่าจะถูก promote เป็น primary","why":"ผิด — replica มีไว้ scale การอ่าน"},{"t":"primary ปฏิเสธการเขียนทุกครั้งที่มี replica ที่ยังตามไม่ทัน","why":"ผิด — การเขียนยังทำที่ primary ได้ปกติ"},{"t":"replication เป็น asynchronous จึงเกิด replica lag ข้อมูลที่อ่านอาจเก่ากว่า primary","why":"ถูกต้อง — eventual consistency ของ read replica"}],"ans":3,"ref":"W11 · สไลด์ 62"},{"id":"w11-057","topic":"Scaling ฐานข้อมูล","level":"apply","story":"","q":"DynamoDB provisioned table ที่เปิด auto scaling พบ throttle ที่ query ผ่าน GSI ทั้งที่ base table ไม่ throttle ควรตรวจอะไร?","opts":[{"t":"เปลี่ยนเป็น Multi-AZ","why":"ผิด — DynamoDB ไม่มีการตั้ง Multi-AZ แบบ RDS"},{"t":"GSI มี RCU/WCU ของตนเอง ต้องให้ auto scaling ครอบคลุมทั้ง base table และ GSI","why":"ถูกต้อง — ความจุของ GSI แยกกัน"},{"t":"เพิ่ม instance class","why":"ผิด — DynamoDB ไม่มี instance class"},{"t":"เพิ่ม read replica ของ RDS","why":"ผิด — ไม่ใช่ DynamoDB"}],"ans":1,"ref":"W11 · สไลด์ 63–64"},{"id":"w11-058","topic":"Scaling ฐานข้อมูล","level":"scen","story":"ทีมรายงานรัน query อ่านหนักบน RDS primary ทำให้ระบบช้า ทีมเสนอเปิด Multi-AZ เพื่อให้ standby รับ query รายงานแทน","q":"ข้อใดถูกต้องที่สุด?","opts":[{"t":"ได้ผล เพราะ standby รับ query แบบ read ทุก query โดยอัตโนมัติ","why":"ผิด — ตามปกติ standby ไม่รับ read"},{"t":"ต้องย้ายระบบทั้งหมดไปใช้ DynamoDB ทันทีเพื่อรองรับการอ่าน","why":"ผิด — เกินจำเป็น ปัญหาคือการอ่านหนัก"},{"t":"ไม่ตรงจุด เพราะ Multi-AZ standby ทำ synchronous replication","why":"ถูกต้อง — read replica เป็น horizontal scaling สำหรับการอ่าน"},{"t":"ลดจำนวน instance ลงเพื่อให้ primary มีทรัพยากรต่อ query มากขึ้น","why":"ผิด — ทำให้ความจุลดลง"}],"ans":2,"ref":"W11 · สไลด์ 38, 62"},{"id":"w11-059","topic":"Scaling ฐานข้อมูล","level":"scen","story":"ระบบพัฒนาของทีมใช้ Aurora เฉพาะบางช่วงของวัน โหลดคาดเดายาก ทีมไม่อยากเลือก instance size ล่วงหน้าและอยากจ่ายตามที่ใช้","q":"ควรเลือกอะไร?","opts":[{"t":"RDS Single-AZ ขนาดใหญ่ที่สุดตลอดเวลา","why":"ผิด — สิ้นเปลืองและต้องเลือกขนาดเอง"},{"t":"Aurora Serverless","why":"ถูกต้อง — แต่ละ instance ปรับ ACU อิสระภายในช่วง"},{"t":"RDS ที่ปรับ instance class ด้วยมือทุกวัน","why":"ผิด — ต้องรีสตาร์ท/ใช้แรงคน"},{"t":"DynamoDB provisioned ตั้งค่าคงที่","why":"ผิด — เป็นฐานข้อมูลคนละชนิด และ provisioned คงที่ไม่เหมาะกับโหลดคาดเดายาก"}],"ans":1,"ref":"W11 · สไลด์ 61, 64"},{"id":"w11-060","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"know","story":"","q":"ใน CloudWatch ข้อใดใช้ระบุ metric ของ resource เฉพาะตัว เช่น แยก CPUUtilization ของแต่ละ EC2?","opts":[{"t":"Dimension เช่น InstanceId","why":"ถูกต้อง — dimension เป็นคู่ name/value"},{"t":"Namespace เช่น AWS/EC2","why":"ผิด — namespace เป็นตัวกลุ่มของ metric"},{"t":"Data point timestamp","why":"ผิด — เป็นค่าในชุด metric"},{"t":"Metric filter","why":"ผิด — ใช้สร้าง metric จาก log"}],"ans":0,"ref":"W11 · สไลด์ 69"},{"id":"w11-061","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"know","story":"","q":"เมื่อ CloudWatch alarm เปลี่ยนเป็นสถานะ ALARM สามารถทำ action ใดตามแผนภาพสไลด์?","opts":[{"t":"แก้ไข launch template อัตโนมัติ","why":"ผิด — ไม่ใช่ action ของ alarm ตามสไลด์"},{"t":"เปลี่ยน DNS record ของโดเมนทันที","why":"ผิด — Route 53 health check ทำ failover คนละกลไก"},{"t":"ส่งไป SNS topic หรือกระตุ้น EC2 Auto Scaling policy","why":"ถูกต้อง — เป็นจุดเชื่อมของ dynamic scaling"},{"t":"รีสตาร์ทฐานข้อมูล RDS","why":"ผิด — ไม่ใช่ action ที่สไลด์ระบุ"}],"ans":2,"ref":"W11 · สไลด์ 70"},{"id":"w11-062","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"apply","story":"","q":"ข้อใดแยก EventBridge event bus กับ pipe ได้ถูกต้อง?","opts":[{"t":"pipe เป็น router หลาย target ส่วน bus เป็นการเชื่อม source กับ target เดียว","why":"ผิด — สลับความหมาย"},{"t":"ทั้งสองส่งได้เฉพาะ target ที่อยู่ใน account และ Region เดียวกับ source","why":"ผิด — target อยู่ account/Region อื่นได้"},{"t":"event bus รับได้เฉพาะ schedule และไม่รับ event จากบริการ AWS","why":"ผิด — bus รับ event จากบริการ AWS และ EventBridge Scheduler"},{"t":"event bus เป็น router รับ event แล้วส่งไป target หนึ่งหรือหลายตัวตาม rule ส่วน pipe เชื่อม source หนึ่งกับ target หนึ่งแบบ point-to-point","why":"ถูกต้อง — ตามสไลด์ EventBridge"}],"ans":3,"ref":"W11 · สไลด์ 72–73"},{"id":"w11-063","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"apply","story":"","q":"ข้อใดจับคู่ health check, CloudWatch และ EventBridge กับรูปแบบได้ถูกต้อง?","opts":[{"t":"health check = passive / CloudWatch = active / EventBridge = reactive","why":"ผิด — health check คือ LB เรียก target"},{"t":"health check = active (LB เรียก target) / CloudWatch = passive (บริการส่งข้อมูลมา) / EventBridge = reactive","why":"ถูกต้อง — ตามตารางสไลด์ 74"},{"t":"ทั้งสามเป็น passive เหมือนกัน ต่างกันเพียงชื่อบริการ","why":"ผิด — ต่างกันตามสไลด์"},{"t":"EventBridge = active polling ตรวจ target ทุกตัวเป็นระยะ","why":"ผิด — EventBridge ส่งต่อ event"}],"ans":1,"ref":"W11 · สไลด์ 74"},{"id":"w11-064","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"apply","story":"","q":"ต้องแจ้งทีมเมื่อค่าใช้จ่ายจริงหรือพยากรณ์เกินงบประมาณที่ตั้ง ควรใช้เครื่องมือใด?","opts":[{"t":"AWS Cost Explorer เพียงอย่างเดียว","why":"ผิด — ใช้วิเคราะห์ย้อนหลัง ไม่ใช่ตั้ง threshold แจ้งเตือนเป็นหลัก"},{"t":"AWS Cost and Usage Report","why":"ผิด — รายงานรายละเอียดสูงส่งออกไฟล์"},{"t":"AWS Budgets","why":"ถูกต้อง — ตั้งงบและรับแจ้งเตือน"},{"t":"CloudWatch dashboard","why":"ผิด — แสดงผล ไม่ใช่การตั้งงบ"}],"ans":2,"ref":"W11 · สไลด์ 76"},{"id":"w11-065","topic":"Monitoring (CloudWatch/EventBridge/health check)","level":"scen","story":"ทีมต้องการให้ระบบเพิ่ม instance เมื่อ CPU เฉลี่ยของ ASG เกิน 70% ติดต่อกัน 5 นาที และส่งอีเมลแจ้งทีม ปัจจุบันมีแต่ dashboard ที่คนต้องเปิดดู","q":"ควรทำอย่างไร?","opts":[{"t":"สร้าง CloudWatch alarm บน metric CPUUtilization ให้ส่ง SNS topic และกระตุ้น EC2 Auto Scaling policy","why":"ถูกต้อง — dashboard ใช้ดู ส่วนการตอบสนองอัตโนมัติใช้ alarm"},{"t":"ใช้เฉพาะ CloudWatch dashboard แล้วให้คนกดเพิ่ม instance เมื่อเห็นกราฟ","why":"ผิด — ไม่อัตโนมัติ"},{"t":"ใช้ ELB health check แทน เพราะตรวจสถานะของ target ได้อยู่แล้ว","why":"ผิด — health check ตัดสินว่า target ควรได้ request หรือไม่ ไม่ใช่ metric CPU"},{"t":"ใช้ Cost Explorer ติดตาม CPU ย้อนหลังแล้วตั้งการแจ้งเตือน","why":"ผิด — เป็นเครื่องมือค่าใช้จ่าย"}],"ans":0,"ref":"W11 · สไลด์ 70–71"},{"id":"w11-066","topic":"Route 53","level":"know","story":"","q":"Public hosted zone กับ private hosted zone ของ Route 53 ต่างกันอย่างไร?","opts":[{"t":"public ตอบเฉพาะ query ภายใน VPC ส่วน private ตอบ query จากอินเทอร์เน็ต","why":"ผิด — สลับกัน"},{"t":"public ตอบ query จากอินเทอร์เน็ต ส่วน private ตอบเฉพาะ query ภายใน VPC ที่ผูกไว้","why":"ถูกต้อง — ตามสไลด์"},{"t":"ทั้งสองตอบ query จากอินเทอร์เน็ตได้เหมือนกัน ต่างกันที่ชนิด record","why":"ผิด — private จำกัดใน VPC"},{"t":"private hosted zone ใช้เก็บ record ชนิด MX เท่านั้น","why":"ผิด — สไลด์แสดง private มี A, AAAA, NS"}],"ans":1,"ref":"W11 · สไลด์ 83"},{"id":"w11-067","topic":"Route 53","level":"know","story":"","q":"ในการ DNS lookup ผ่าน resolver ของ ISP เมื่อ root name server ถูกถาม มันตอบอะไร?","opts":[{"t":"IP ของ www.myweb.com โดยตรง","why":"ผิด — root ไม่รู้ record ของโดเมน"},{"t":"ตำแหน่ง name server ของ myweb.com โดยตรง","why":"ผิด — TLD เป็นผู้ตอบข้อนี้"},{"t":"ตำแหน่งของ name server ของ TLD (.com) เป็น referral","why":"ถูกต้อง — authoritative เท่านั้นที่รู้ record จริง"},{"t":"ใบรับรอง TLS ของเว็บ","why":"ผิด — ไม่เกี่ยวกับ DNS lookup"}],"ans":2,"ref":"W11 · สไลด์ 79"},{"id":"w11-068","topic":"Route 53","level":"apply","story":"","q":"ต้องการ canary: ส่งทราฟฟิก 10% ไปเวอร์ชันใหม่ และ 90% ไปเวอร์ชันเดิม ผ่าน DNS ควรใช้ routing policy ใด?","opts":[{"t":"Latency","why":"ผิด — เลือก Region ที่ latency ต่ำสุด"},{"t":"Geolocation","why":"ผิด — เลือกตามตำแหน่งผู้ใช้"},{"t":"Weighted","why":"ถูกต้อง — แบ่งตามน้ำหนัก เช่น 90/10"},{"t":"Failover","why":"ผิด — เป็น active-passive ไม่ใช่แบ่งสัดส่วน"}],"ans":2,"ref":"W11 · สไลด์ 82"},{"id":"w11-069","topic":"Route 53","level":"scen","story":"กฎหมายกำหนดให้ผู้ใช้จากสหภาพยุโรปต้องถูกส่งไปยัง endpoint ใน Region ยุโรปเท่านั้น แม้ Region อื่นจะ latency ต่ำกว่า","q":"ควรเลือก routing policy ใด?","opts":[{"t":"Latency","why":"ผิด — อาจส่งไป Region ที่ไม่ใช่ยุโรปหากเร็วกว่า"},{"t":"Weighted","why":"ผิด — แบ่งตามน้ำหนัก ไม่รับประกันตำแหน่ง"},{"t":"Simple","why":"ผิด — ตอบเหมือนกันทุกครั้ง"},{"t":"Geolocation","why":"ถูกต้อง — ตามตำแหน่งผู้ใช้ (ทวีป ประเทศ รัฐ)"}],"ans":3,"ref":"W11 · สไลด์ 82"},{"id":"w11-070","topic":"Route 53","level":"scen","story":"ระบบรัน 2 Region ใช้ Route 53 failover routing พร้อม health check แต่ record มี TTL 24 ชั่วโมง เมื่อ Region หลักล่ม ผู้ใช้จำนวนมากยังเข้า Region ที่ล่มอยู่หลายชั่วโมง","q":"สาเหตุและวิธีแก้คืออะไร?","opts":[{"t":"Route 53 ไม่รองรับ failover routing ข้าม Region จึงต้องสลับด้วยมือ","why":"ผิด — รองรับ"},{"t":"resolver cache คำตอบเก่าตาม TTL จึงควรตั้ง TTL ต่ำสำหรับ record ที่ต้อง failover เร็ว","why":"ถูกต้อง — failover มีผลเมื่อ cache หมดอายุ"},{"t":"health check ล้มเหลวเพราะ ALB ไม่ทำงานที่ Layer 7","why":"ผิด — ไม่เกี่ยวกับ TTL"},{"t":"เปลี่ยนเป็น Simple routing เพื่อให้ตัด endpoint ที่ล่มออก","why":"ผิด — ไม่ตัด endpoint ที่ unhealthy"}],"ans":1,"ref":"W11 · สไลด์ 79, 80, 84"}],"w12":[{"id":"w12-001","topic":"หลักการ Caching","level":"know","story":"","q":"เหตุใด cache จึงให้ประโยชน์ได้ แม้มีขนาดเล็กกว่าข้อมูลทั้งหมดใน origin มาก?","opts":[{"t":"cache ทำสำเนาข้อมูลทั้งหมดของ origin ไว้ใน RAM โดยบีบอัดข้อมูลให้เล็กลงมาก","why":"ผิด: cache เก็บเพียง subset ไม่ใช่สำเนาทั้งหมด และประโยชน์ไม่ได้มาจากการบีบอัด"},{"t":"cache รวมการเขียนกลับ origin เป็น batch ทำให้ origin รับ write ทีละน้อย ๆ ไม่พร้อมกัน","why":"ผิด: สไลด์อธิบายประโยชน์ด้านการอ่านซ้ำ (read) ไม่ใช่การรวม write"},{"t":"cache ตอบเฉพาะ request ที่ miss เพื่อให้ origin รับเฉพาะ request ที่ซ้ำ","why":"ผิดทิศทาง: hit คือตอบจาก cache ส่วน miss เท่านั้นที่ไปถึง origin"},{"t":"ข้อมูลยอดนิยมกระจุกตัว subset ที่ถูกเรียกบ่อยจึงให้ hit ส่วนใหญ่","why":"ถูกต้อง: อาศัย locality of reference ทำให้ subset เล็ก ๆ ก็ให้ hit ratio สูง"}],"ans":3,"ref":"W12 · สไลด์ 4–5"},{"id":"w12-002","topic":"หลักการ Caching","level":"apply","story":"","q":"cache มี access time 2 หน่วย ส่วน origin มี 30 หน่วย ถ้า hit ratio = 80% latency เฉลี่ยของ request คือเท่าใด (latency เฉลี่ย = hit x t_cache + (1 - hit) x t_origin)?","opts":[{"t":"16 หน่วย","why":"คือค่าเฉลี่ยเลขคณิตของ 2 กับ 30 ซึ่งไม่คำนึงถึงสัดส่วน hit/miss"},{"t":"24.4 หน่วย","why":"สลับน้ำหนัก (0.2x2 + 0.8x30) ซึ่งเท่ากับ hit ratio 20% ไม่ใช่ 80%"},{"t":"4.8 หน่วย","why":"คือผลของ hit ratio 90% (0.9x2 + 0.1x30) ไม่ใช่ 80%"},{"t":"7.6 หน่วย","why":"0.8x2 + 0.2x30 = 1.6 + 6.0 = 7.6"}],"ans":3,"ref":"W12 · สไลด์ 5"},{"id":"w12-003","topic":"หลักการ Caching","level":"apply","story":"","q":"ข้อมูลใดมีลักษณะที่ไม่เหมาะกับการ cache มากที่สุด?","opts":[{"t":"ยอดเงินในบัญชีที่เปลี่ยนทุกไม่กี่วินาที ต้อง strongly consistent ทุกครั้งที่อ่าน","why":"ข้อมูลเปลี่ยนบ่อยและต้องสดเสมอ ทำให้ hit ratio ต่ำและเสี่ยงข้อมูลเก่า (เพิ่มเติม สไลด์ 6)"},{"t":"รูปภาพโปรไฟล์ผู้ใช้ที่ถูกเปิดดูหลายพันครั้งต่อวัน และแทบไม่มีการเปลี่ยนแปลงใด ๆ เลย","why":"เหมาะมาก: static และอ่านซ้ำบ่อย stale เกิดน้อย"},{"t":"ผลลัพธ์ของ query ที่ join และ aggregate หลายตาราง ซึ่งเรียกซ้ำบ่อย","why":"เหมาะ: query หนักและซ้ำ ลดภาระ database ได้มาก"},{"t":"ผลคำนวณที่ใช้ CPU สูงมาก และให้ output เดิมทุกครั้งเมื่อ input เดิม","why":"เหมาะ: deterministic การเก็บผลช่วยประหยัด CPU"}],"ans":0,"ref":"W12 · สไลด์ 6"},{"id":"w12-004","topic":"หลักการ Caching","level":"scen","story":"หน้าสินค้าของร้านค้าออนไลน์ถูก cache ด้วย TTL 24 ชั่วโมง ได้ hit ratio 98% และ database โหลดต่ำมาก แต่ฝ่ายธุรกิจร้องเรียนว่าเมื่อแก้ราคาแล้ว ลูกค้ายังเห็นราคาเก่าอยู่นานหลายชั่วโมง ข้อกำหนดทางธุรกิจคือราคาต้องสะท้อนภายในไม่เกิน 5 นาที","q":"ควรตัดสินใจอย่างไรให้สอดคล้องกับ trade-off ของ caching?","opts":[{"t":"เพิ่มขนาด cache node เพื่อให้ hit ratio สูงขึ้นอีก","why":"ขนาด memory ไม่ได้เปลี่ยนอายุของ key ข้อมูลยังเก่านาน 24 ชั่วโมงเท่าเดิม"},{"t":"เปลี่ยน eviction policy เป็น allkeys-lfu","why":"eviction ทำงานเมื่อ memory เต็ม ไม่เกี่ยวกับการหมดอายุตามเวลา จึงไม่ควบคุมความสด"},{"t":"ลด TTL ลงให้ไม่เกิน 300 วินาที และยอมรับว่า hit ratio จะลดลง","why":"TTL คือขอบเขตบนของความเก่า ยิ่งสั้นข้อมูลยิ่งสด แลกกับ hit ratio ต่ำลง ตามสไลด์ 7"},{"t":"เพิ่ม TTL เป็น 7 วันเพื่อลดภาระ database ให้มากขึ้น","why":"ทำให้ข้อมูลเก่านานขึ้น ขัดกับข้อกำหนด 5 นาทีโดยตรง"}],"ans":2,"ref":"W12 · สไลด์ 7, 41"},{"id":"w12-005","topic":"หลักการ Caching","level":"know","story":"","q":"ข้อใดจับคู่ ชนิดของ caching กับบริการ AWS และแหล่งที่ตอบ ได้ถูกต้อง?","opts":[{"t":"static caching: ElastiCache ตอบจาก edge location / database caching: CloudFront ตอบจากชั้น in-memory","why":"สลับบริการ: edge location คือ CloudFront ส่วน in-memory คือ ElastiCache"},{"t":"static caching และ database caching ใช้ CloudFront ทั้งคู่ โดยต่างกันที่ TTL","why":"CloudFront เป็น edge cache ของไฟล์/web object ไม่ใช่ชั้น cache ของ query database"},{"t":"static caching และ database caching ใช้ ElastiCache ทั้งคู่ โดยต่างกันที่ engine","why":"ElastiCache อยู่ใน VPC หน้า database ไม่ได้ตอบจาก edge location ใกล้ผู้ใช้"},{"t":"static caching: CloudFront ตอบจาก edge location / database caching: ElastiCache ตอบจากชั้น in-memory","why":"ตรงกับสไลด์ 8"}],"ans":3,"ref":"W12 · สไลด์ 8"},{"id":"w12-006","topic":"CloudFront และ TTL","level":"know","story":"","q":"เมื่อ request ไปถึง edge location แล้วเกิด cache miss CloudFront จะดำเนินการขั้นถัดไปอย่างไร?","opts":[{"t":"ไปที่ origin ทันที เพราะ Regional edge cache ถูกใช้เฉพาะ dynamic content เท่านั้น","why":"Regional edge cache ทำหน้าที่ชั้นที่สองของ cache สำหรับเนื้อหา ไม่ได้จำกัดเฉพาะ dynamic"},{"t":"ส่ง request ไปยัง edge location ใกล้เคียงอื่นในภูมิภาคเดียวกันเพื่อขอสำเนา","why":"สถาปัตยกรรมคือ edge -> Regional edge cache -> origin ไม่ใช่ edge ถามกันเอง"},{"t":"ถาม Regional edge cache ก่อน หาก miss อีกจึงไปที่ origin","why":"ตามสไลด์ 14: Regional edge cache เก็บ object ที่ไม่ค่อยนิยมได้นานกว่า และรวม miss จากหลาย edge"},{"t":"ตอบ error 404 เพราะ edge location เก็บเฉพาะข้อมูลที่ push มาล่วงหน้า","why":"object ถูก cache แบบ on-demand เมื่อมี request ไม่ได้ push ล่วงหน้า (สไลด์ 21)"}],"ans":2,"ref":"W12 · สไลด์ 14–15, 21"},{"id":"w12-007","topic":"CloudFront และ TTL","level":"know","story":"","q":"Price Class 100 ของ CloudFront ใช้ edge location ในภูมิภาคใดบ้าง?","opts":[{"t":"เฉพาะ US/Mexico/Canada และ Europe/Israel","why":"ตามตาราง Price Class 100 คือกลุ่มที่ถูกที่สุด ใช้เพียงสองภูมิภาคนี้"},{"t":"ทุกภูมิภาคยกเว้น South America และ Australia/NZ","why":"นั่นคือ Price Class 200"},{"t":"US/Mexico/Canada, Europe/Israel และ Japan","why":"Japan ไม่รวมใน Class 100 (มีใน Class 200 และ All)"},{"t":"ทุกภูมิภาคที่มี edge location","why":"นั่นคือ Price Class All ซึ่งแพงที่สุด"}],"ans":0,"ref":"W12 · สไลด์ 19"},{"id":"w12-008","topic":"CloudFront และ TTL","level":"apply","story":"","q":"distribution ตั้ง Price Class 100 ส่วนผู้ชมอยู่ในประเทศไทย จะเกิดอะไรขึ้นกับ request ของผู้ชมกลุ่มนี้?","opts":[{"t":"ถูกบล็อกและได้ HTTP 403 เพราะประเทศไทยไม่อยู่ในภูมิภาคของ class นี้เลย","why":"การบล็อกตามประเทศเป็นหน้าที่ของ geo restriction ไม่ใช่ price class"},{"t":"ยังเสิร์ฟจาก edge location ในประเทศไทยเหมือนเดิม แต่ค่าบริการถูกลงมาก","why":"Class 100 ไม่รวมภูมิภาคของไทย จึงไม่ใช้ edge ในไทย"},{"t":"ใช้งานไม่ได้จนกว่าจะเปลี่ยนเป็น Price Class All","why":"ไม่จำเป็น ผู้ชมยังใช้งานได้ เพียงช้าลง"},{"t":"ยังได้รับเนื้อหา แต่เสิร์ฟจาก edge ในภูมิภาคที่รวมอยู่ (ไกลกว่า) จึง latency สูงขึ้น","why":"การจำกัด class ลดต้นทุนโดยไม่บล็อกผู้ชม (สไลด์ 19)"}],"ans":3,"ref":"W12 · สไลด์ 19"},{"id":"w12-009","topic":"CloudFront และ TTL","level":"know","story":"","q":"CloudFront หา TTL ใน Step 1 โดยอ่านคำสั่งจาก origin ตามลำดับใด (ตัวแรกที่พบชนะ)?","opts":[{"t":"Expires, max-age, s-maxage, แล้วจึงใช้ Default TTL","why":"ลำดับกลับด้าน และ Expires ถูกละเลยเมื่อมี Cache-Control"},{"t":"s-maxage, max-age, Expires, แล้วจึงใช้ Default TTL เมื่อไม่มีเลย","why":"ลำดับตามสไลด์ 24"},{"t":"Default TTL, max-age, s-maxage, Expires","why":"Default TTL เป็น fallback ใช้เป็นลำดับสุดท้ายเมื่อ origin ไม่ส่ง header"},{"t":"max-age, Expires, Default TTL แล้ว s-maxage","why":"s-maxage มีลำดับก่อน max-age และไม่ใช่ตัวสุดท้าย"}],"ans":1,"ref":"W12 · สไลด์ 24"},{"id":"w12-010","topic":"CloudFront และ TTL","level":"apply","story":"","q":"origin ส่ง response header Cache-Control: max-age=300 และ Expires ที่ระบุเวลาอีก 1 วันข้างหน้า cache policy ตั้ง Min/Default/Max = 0 / 1h / 1y CloudFront จะ cache object นี้นานเท่าไร?","opts":[{"t":"1 วัน","why":"ตามค่า Expires แต่ Expires ถูกละเลยเมื่อมี Cache-Control"},{"t":"300 วินาที","why":"Step 1 ใช้ max-age=300 (Expires ถูกละเลยเมื่อมี Cache-Control) Step 2 ค่าอยู่ในช่วง [0, 1y] จึงไม่เปลี่ยน"},{"t":"1 ชั่วโมง","why":"เป็น Default TTL ซึ่งใช้เฉพาะเมื่อ origin ไม่ส่ง caching header เลย"},{"t":"1 ปี","why":"เป็น Maximum TTL ซึ่งเป็นเพดาน ไม่ใช่ค่าที่ถูกเลือกใช้"}],"ans":1,"ref":"W12 · สไลด์ 24, 26"},{"id":"w12-011","topic":"CloudFront และ TTL","level":"know","story":"","q":"การตั้งค่า Minimum / Default / Maximum TTL ของ CloudFront ทำที่ใด?","opts":[{"t":"ใน cache policy ที่แนบกับ cache behavior","why":"ตามสไลด์ 25: policy ครอบ path pattern เช่น /images/*"},{"t":"ใน origin request policy ที่เลือก header/cookie/query string ส่งไป origin","why":"origin request policy เลือกค่าที่ส่งไป origin ไม่ใช่เรื่อง TTL"},{"t":"ใน Origin Custom Headers ของ origin settings","why":"เป็น header ที่ CloudFront แนบเมื่อเรียก origin ไม่ใช่การกำหนด TTL"},{"t":"ใน metadata ของแต่ละ object บน S3","why":"metadata เป็นที่ตั้ง Cache-Control ซึ่งเป็นคำสั่งต่อ object ไม่ใช่ min/default/max"}],"ans":0,"ref":"W12 · สไลด์ 22, 25"},{"id":"w12-012","topic":"CloudFront และ TTL","level":"scen","story":"เว็บไซต์ static บน S3 อยู่หลัง CloudFront ที่แนบ AWS WAF พร้อม rate-based rule แต่ bucket ถูกตั้งเป็น public ต่อมาพบว่าบอทเรียกไฟล์โดยตรงจาก URL ของ S3 ทำให้ค่าใช้จ่าย request บน S3 พุ่ง ขณะที่ WAF ที่ distribution ไม่เห็น traffic ส่วนนี้เลย","q":"ควรแก้อย่างไร?","opts":[{"t":"ตั้ง bucket เป็น private ใช้ OAC และ bucket policy รับเฉพาะจาก distribution นั้น","why":"ล็อก origin ให้เข้าได้ผ่าน CloudFront เท่านั้น ทำให้ WAF และ cache ถูกใช้ทุก request (สไลด์ 30–31)"},{"t":"เพิ่ม rate-based rule ใน WAF ของ distribution ให้เข้มงวดและครอบคลุมมากขึ้น","why":"traffic ที่เรียก S3 ตรงไม่ผ่าน distribution จึงไม่ถูกตรวจโดย WAF นี้"},{"t":"เปลี่ยนเป็น Price Class 100 เพื่อลดจำนวน edge location","why":"Price Class เลือกภูมิภาค edge ไม่เกี่ยวกับทางเข้าตรงสู่ origin"},{"t":"เพิ่ม Maximum TTL ให้ยาวขึ้น","why":"TTL ลด miss ที่ไป origin ผ่าน CloudFront แต่ไม่ปิดช่องที่บอทเรียก S3 ตรง"}],"ans":0,"ref":"W12 · สไลด์ 30–31"},{"id":"w12-013","topic":"CloudFront และ TTL","level":"scen","story":"ไฟล์ static บน origin ถูกเสิร์ฟผ่าน CloudFront โดย cache policy ตั้ง Min/Default/Max = 0 / 24h / 1y ต้องการให้ CloudFront cache ไฟล์ 1 ชั่วโมง ขณะที่อายุที่เบราว์เซอร์ทั่วไปใช้ควรสั้นเพียง 60 วินาที และไม่ต้องการแก้ค่าที่กระทบ object อื่นทั้ง behavior","q":"ควรตั้งค่าอย่างไร?","opts":[{"t":"ให้ origin ส่ง Cache-Control: max-age=3600 เท่านั้น","why":"เบราว์เซอร์จะ cache 1 ชั่วโมงด้วย ไม่ได้ให้ 60 วินาที"},{"t":"ตั้ง Minimum TTL = 3600 ใน cache policy เพื่อให้ CloudFront เก็บอย่างน้อย 1 ชั่วโมง","why":"กระทบทุก object ใน behavior และยกค่าที่ต่ำกว่า (รวม no-store) ขึ้นเป็น 1 ชั่วโมง"},{"t":"ตั้ง Default TTL = 3600 ใน cache policy เพื่อให้ object นี้ถูกเก็บ 1 ชั่วโมง","why":"Default ถูกใช้เมื่อ origin ไม่ส่ง header เลย แต่ที่นี่ origin ส่ง Cache-Control แล้ว จึงไม่มีผล"},{"t":"ให้ origin ส่ง Cache-Control: max-age=60, s-maxage=3600","why":"s-maxage มีผลกับ CloudFront (shared cache) และถูกอ่านก่อน max-age ส่วน max-age=60 ใช้กับฝั่งเบราว์เซอร์ (เพิ่มเติม)"}],"ans":3,"ref":"W12 · สไลด์ 24–27"},{"id":"w12-014","topic":"ElastiCache (engine/strategy)","level":"know","story":"","q":"ตามสไลด์ ElastiCache แต่ละ engine scale cluster ได้ถึงกี่ node?","opts":[{"t":"Memcached สูงสุด 250 node ส่วน Redis สูงสุด 20 node","why":"สลับตัวเลขกัน"},{"t":"Memcached สูงสุด 20 node ส่วน Redis ถึง 250 node","why":"ตรงตามสไลด์ 38 (ค่าจริงของ AWS เปลี่ยนตามเวอร์ชัน/โควตา)"},{"t":"ทั้ง Memcached และ Redis สูงสุด 20 node","why":"Redis ไปได้ไกลกว่านั้น (250 node ตามสไลด์)"},{"t":"ทั้งสอง engine ไม่จำกัดจำนวน node","why":"สไลด์ระบุขีดจำกัดของทั้งสอง engine"}],"ans":1,"ref":"W12 · สไลด์ 38"},{"id":"w12-015","topic":"ElastiCache (engine/strategy)","level":"know","story":"","q":"ข้อใดเกี่ยวกับ Valkey ใน ElastiCache ถูกต้อง?","opts":[{"t":"เป็น fork ของ Redis 7.2.4 มี persistence/HA แบบ Redis OSS และ node ถูกกว่าราว 20%","why":"ตรงตามตารางสไลด์ 37"},{"t":"เป็น engine แบบ string/blob ล้วนเหมือน Memcached แต่รองรับ multithreaded I/O","why":"Valkey รองรับ hash, list, set, sorted set, snapshot และ replica ไม่ใช่ string อย่างเดียว"},{"t":"เป็น Redis รุ่นเก่ากว่า 7.x ที่ AWS ประกาศเลิกสนับสนุนบน ElastiCache แล้ว","why":"Valkey คือ default สำหรับงานใหม่ ไม่ใช่รุ่นเก่า"},{"t":"ไม่มี replica และ Multi-AZ failover จึงต้องจับคู่กับ Memcached เพื่อความทนทาน","why":"Valkey มี replica และ Multi-AZ failover เหมือน Redis OSS"}],"ans":0,"ref":"W12 · สไลด์ 37"},{"id":"w12-016","topic":"ElastiCache (engine/strategy)","level":"apply","story":"","q":"แอปใช้ lazy loading อ่านข้อมูล 1,000 ครั้ง hit ratio 90% โดย hit ใช้ 1 trip และ miss ใช้ 3 trips (ถาม cache, อ่าน database, เขียนกลับ cache) รวมกี่ trips?","opts":[{"t":"1,000 trips","why":"ไม่ได้นับ trips เพิ่มของ miss (ใช้ 3 ไม่ใช่ 1)"},{"t":"1,100 trips","why":"เท่ากับนับ miss เพียง 2 trips ขาด trip การเขียนกลับ cache"},{"t":"3,000 trips","why":"เท่ากับนับทุก request เป็น miss ทั้งที่ 90% เป็น hit"},{"t":"1,200 trips","why":"hit 900x1 + miss 100x3 = 900 + 300 = 1,200"}],"ans":3,"ref":"W12 · สไลด์ 43, 45"},{"id":"w12-017","topic":"ElastiCache (engine/strategy)","level":"apply","story":"","q":"แอปใช้ write-through โดยทุก write ต้องเขียน database แล้วอัปเดต cache (2 trips) ถ้ามี write 200 ครั้ง จะมี trips ฝั่ง write รวมเท่าใด?","opts":[{"t":"200 trips","why":"ลืมนับ trip การเขียน cache ซึ่งเป็นต้นทุนเพิ่มของ write-through"},{"t":"600 trips","why":"คือ 3 trips ต่อครั้ง ซึ่งเป็นต้นทุนของ miss ใน lazy loading ไม่ใช่ write-through"},{"t":"400 trips","why":"200 x 2 = 400 (เขียน database 1 และ cache 1 ต่อครั้ง)"},{"t":"800 trips","why":"นับซ้ำสองเท่า ไม่มีขั้นตอนที่สามหรือสี่ในลำดับของ write-through"}],"ans":2,"ref":"W12 · สไลด์ 44–45"},{"id":"w12-018","topic":"ElastiCache (engine/strategy)","level":"apply","story":"","q":"โค้ดเดิมมี 2 ฟังก์ชัน: get_course() ใช้ lazy loading (miss แล้ว cache.set ด้วย ttl=600) และ update_course() เรียก db.update_course() แล้ว cache.set(..., ttl=600) — หากลบบรรทัด cache.set ใน update_course() ออก (เหลือเฉพาะ db.update_course) จะส่งผลอย่างไร?","opts":[{"t":"ผู้อ่านเห็นค่าเก่าตลอดไปจนกว่าจะมีการ restart แอปหรือ restart cache node","why":"key มี TTL 600 วินาที จึงหมดอายุเองและถูกโหลดใหม่"},{"t":"ผู้อ่านทุกคนได้ error เพราะ cache เก็บค่าที่ไม่สอดคล้องกับ database","why":"cache ไม่ตรวจความสอดคล้อง ผลคือข้อมูลเก่า ไม่ใช่ error"},{"t":"ผู้อ่านเห็นค่าเก่าได้จน TTL ของ key หมด (ไม่เกิน 600 วินาที) แล้วจึงได้ค่าใหม่จาก miss","why":"ไม่มีการอัปเดต cache ตอนเขียน จึงเหลือเพียง lazy loading ที่อาศัย TTL เป็นขอบเขตความเก่า"},{"t":"ข้อมูลใน cache ถูกลบทันทีเมื่อ database อัปเดต","why":"ลบอัตโนมัติไม่มี ต้องมีโค้ด invalidate หรือรอ TTL"}],"ans":2,"ref":"W12 · สไลด์ 43–46"},{"id":"w12-019","topic":"ElastiCache (engine/strategy)","level":"scen","story":"เว็บแอปรันบน EC2 หลัง ALB ที่เปิด sticky sessions โดยเก็บ session ในหน่วยความจำของแต่ละ instance เมื่อ Auto Scaling ทำ scale-in ปิด instance ผู้ใช้ที่ผูกกับ instance นั้นถูก logout กลางคัน ทีมต้องการให้ instance สับเปลี่ยนกันได้ และ session รอดแม้ cache node หนึ่งล่ม","q":"ควรออกแบบอย่างไร?","opts":[{"t":"ใช้ ElastiCache for Memcached หลาย node เป็น session store กลางแบบกระจาย key ด้วย hash","why":"Memcached ไม่มี replication/persistence node ล่ม = session บน node นั้นหาย"},{"t":"คง sticky sessions ไว้ แต่ยืด cooldown ของ scale-in ให้นานขึ้นเพื่อลดการปิด instance","why":"ยังเก็บ state ใน instance เดี่ยว instance ล่มหรือถูกปิดก็ยัง logout และโหลดไม่กระจาย"},{"t":"เก็บ session ใน Memcached node เดียวที่ใหญ่ขึ้นและมีหน่วยความจำมากพอ","why":"เป็น single point of failure และไม่มีสำเนาข้อมูล"},{"t":"ปิด sticky sessions เก็บ session ใน ElastiCache (Valkey) แบบ replica + Multi-AZ ตั้ง TTL = session timeout","why":"state อยู่นอก instance และ replication ทำให้ node ล่มแล้ว session ไม่หาย (สไลด์ 47)"}],"ans":3,"ref":"W12 · สไลด์ 36–37, 47"},{"id":"w12-020","topic":"ElastiCache (engine/strategy)","level":"scen","story":"ทีมต้องการ cache ผลลัพธ์ query และ HTML fragment ที่เป็น string/blob ล้วน ๆ โดยการสูญเสีย cache เมื่อ node ล่มไม่เป็นปัญหา ใช้ node ขนาดใหญ่หลาย core และนักพัฒนาใช้ Memcached client อยู่แล้ว ไม่ต้องการ persistence, sorted set หรือ automatic failover","q":"engine ใดตรงตามเกณฑ์ในสไลด์มากที่สุด?","opts":[{"t":"ElastiCache for Memcached","why":"ตรงเกณฑ์: key-value พื้นฐาน, multithreaded บน node ใหญ่, ข้อมูลหายได้, ใช้ Memcached client เดิม"},{"t":"ElastiCache for Redis OSS เพราะต้องมี automatic failover ระหว่าง AZ","why":"โจทย์ระบุว่าไม่ต้องการ failover/persistence จึงไม่มีเหตุให้จ่ายความสามารถส่วนนั้น"},{"t":"ElastiCache for Valkey เพราะต้องมี sorted set ไว้จัดอันดับข้อมูล","why":"ไม่มี requirement เรื่อง sorted set หรือ data type ซับซ้อน"},{"t":"ElastiCache for Valkey แบบ cluster mode เพราะต้องมี snapshot เพื่อกู้ข้อมูล","why":"โจทย์ไม่ต้องการ persistence snapshot"}],"ans":0,"ref":"W12 · สไลด์ 36–37"},{"id":"w12-021","topic":"ElastiCache (engine/strategy)","level":"scen","story":"ระบบลงทะเบียนมี traffic ที่คาดเดาไม่ได้ บางวันแทบไม่มี บางวันพุ่งสูงมาก ทีมขนาดเล็กไม่ต้องการทำ capacity planning เรื่องจำนวน node หรือ shard และต้องการให้ cache ขยายตัวอัตโนมัติ","q":"รูปแบบ ElastiCache ใดเหมาะที่สุด?","opts":[{"t":"cluster ที่ออกแบบเอง 3 shard x 3 node แล้วเพิ่ม shard ด้วยมือเมื่อโหลดสูง","why":"ต้องกำหนดจำนวน shard/node เองและปรับด้วยมือ ซึ่งขัดกับโจทย์"},{"t":"ElastiCache Serverless ที่ AWS ปรับ capacity ให้อัตโนมัติ","why":"ไม่ต้องเลือกจำนวน node/shard ลดงาน capacity planning (สไลด์ 40) และต้องคำนึงเรื่องราคาตามการใช้งาน"},{"t":"Memcached node เดียวขนาดใหญ่","why":"ไม่ขยายอัตโนมัติ และเป็น single point of failure"},{"t":"เพิ่ม read replica ของ database แทน cache","why":"ไม่ใช่ in-memory cache จึงไม่ลด latency ระดับ sub-millisecond และยังมีค่า provision ล่วงหน้า"}],"ans":1,"ref":"W12 · สไลด์ 39–40"},{"id":"w12-022","topic":"Cache failure patterns และ Eviction","level":"know","story":"","q":"วิธีใดแก้ปัญหา stampede (thundering herd) ของ key ยอดนิยมที่หมดอายุได้ตรงจุด?","opts":[{"t":"เพิ่ม random jitter ให้ TTL ของทุก key","why":"jitter กระจายเวลาหมดอายุของหลาย key (avalanche) ไม่ช่วยกรณี key เดียวที่ร้อนมาก"},{"t":"ใช้ lock ให้ request เดียวสร้างค่าใหม่ ตัวอื่นรอหรือ retry","why":"เปลี่ยนจากการ rebuild พร้อมกัน N ครั้งเป็น 1 ครั้ง (สไลด์ 49)"},{"t":"cache ผลลัพธ์ not found ด้วย TTL สั้น","why":"เป็นวิธีของ penetration ที่ key ไม่มีอยู่จริง"},{"t":"เก็บสำเนา key:1 ถึง key:N แล้วสุ่มเลือกอ่านหนึ่งตัว","why":"เป็นวิธีของ hot key เพื่อกระจาย read ข้าม shard ไม่ใช่ลดการ rebuild พร้อมกัน"}],"ans":1,"ref":"W12 · สไลด์ 49, 53"},{"id":"w12-023","topic":"Cache failure patterns และ Eviction","level":"apply","story":"","q":"เพื่อป้องกัน avalanche ทีมตั้ง TTL = 600 วินาที + random jitter 0 ถึง 60 วินาที ให้ทุก key ที่ warm พร้อมกัน key เหล่านี้จะหมดอายุในช่วงเวลาใด?","opts":[{"t":"ระหว่าง 600 ถึง 660 วินาทีหลัง warm","why":"ฐาน 600 บวกค่าสุ่ม 0–60 จึงกระจายในช่วง 600–660 วินาที"},{"t":"พร้อมกันที่ 600 วินาทีพอดี","why":"คือกรณีไม่มี jitter ซึ่งทำให้เกิด avalanche"},{"t":"ระหว่าง 540 ถึง 660 วินาที","why":"jitter ในโจทย์เป็นการบวกเพิ่ม ไม่ลบ จึงไม่มี key ที่หมดก่อน 600"},{"t":"ระหว่าง 0 ถึง 60 วินาที","why":"ค่านี้คือขนาด jitter ไม่ใช่เวลาหมดอายุรวม"}],"ans":0,"ref":"W12 · สไลด์ 50"},{"id":"w12-024","topic":"Cache failure patterns และ Eviction","level":"apply","story":"","q":"จากมุมมอง CloudWatch เมื่อ database load พุ่ง พบว่า cache hit rate ปกติ แต่ CPU ของ cache node เพียงตัวเดียวสูงมาก ขณะ node อื่นว่าง ข้อใดเป็นการวินิจฉัยที่เป็นไปได้มากที่สุด?","opts":[{"t":"stampede ของ key ที่เพิ่งหมดอายุ","why":"stampede ทำให้ hit rate ตกชั่วขณะแล้วฟื้น และ load พุ่งที่ database"},{"t":"avalanche จาก TTL ที่เท่ากัน","why":"avalanche ทำให้ miss rate พุ่งหลาย key พร้อมกัน hit rate ต้องตก"},{"t":"hot key: key เดียวรับ traffic เกินกว่าที่ node/shard รับไหว","why":"hit rate ปกติแต่ CPU ของ node เดียวสูง ชี้ไปที่ hot key (สไลด์ 52–53 เพิ่มเติม)"},{"t":"penetration จาก ID ที่ไม่มีอยู่จริง","why":"penetration ทำให้ hit rate ต่ำต่อเนื่อง เพราะ key ไม่เคยถูกเติมใน cache"}],"ans":2,"ref":"W12 · สไลด์ 53"},{"id":"w12-025","topic":"Cache failure patterns และ Eviction","level":"know","story":"","q":"ข้อใดเกี่ยวกับ eviction policy ของ ElastiCache ถูกต้อง?","opts":[{"t":"default คือ noeviction ซึ่งคืน error ทันทีเมื่อ memory ของ cache เต็ม","why":"noeviction ต้องตั้งเอง ไม่ใช่ default"},{"t":"default คือ allkeys-lfu ซึ่งลบ key ที่ใช้ความถี่น้อยที่สุดจากทุก key","why":"ไม่ใช่ default และสไลด์ระบุ volatile-lru"},{"t":"Memcached ให้เลือกได้ทั้ง LRU และ LFU","why":"Memcached ไม่มี policy ให้เลือก ใช้ LRU คงที่"},{"t":"default ของ Valkey/Redis คือ volatile-lru ส่วน Memcached เลือก policy ไม่ได้ (LRU เสมอ)","why":"ตรงตามสไลด์ 56"}],"ans":3,"ref":"W12 · สไลด์ 56"},{"id":"w12-026","topic":"Cache failure patterns และ Eviction","level":"apply","story":"","q":"key หนึ่งถูกเขียนด้วย TTL 3,600 วินาที แต่ผ่านไปเพียง 10 นาทีก็ถูก cache miss ขณะที่ memory ของ node ใกล้เต็มและ metric Evictions เพิ่มขึ้นต่อเนื่อง — กลไกใดอธิบายการหายไปของ key นี้ได้ดีที่สุด?","opts":[{"t":"expiration: key หมดอายุตาม TTL ตามปกติ","why":"TTL ยังไม่ถึง (10 นาที < 60 นาที) จึงไม่ใช่ expiration"},{"t":"stampede: request จำนวนมากลบ key พร้อมกัน","why":"stampede คือการ rebuild พร้อมกันหลัง key หมดอายุ ไม่ใช่การลบ key"},{"t":"eviction: cache เต็ม engine จึงลบ key ตาม policy ก่อน TTL","why":"eviction ขับเคลื่อนด้วย memory และ key อาจหายก่อน TTL มาก (สไลด์ 55)"},{"t":"penetration: key ถูกร้องขอทั้งที่ไม่มีใน database","why":"เกิดเมื่อข้อมูลไม่มีใน database ไม่เกี่ยวกับ key ที่เคยถูกเขียนแล้วหาย"}],"ans":2,"ref":"W12 · สไลด์ 55, 57"},{"id":"w12-027","topic":"Cache failure patterns และ Eviction","level":"scen","story":"cluster ElastiCache มี 6 shard วันลงทะเบียน นักศึกษาจำนวนมากรีเฟรชจำนวนที่นั่งของวิชายอดนิยมวิชาเดียว key เดียวนั้นอยู่บน shard 3 ซึ่ง CPU ขึ้นถึง 95% ขณะที่ shard อื่นต่ำกว่า 10% และ latency ของ request ที่ไปถึง shard 3 สูงขึ้น","q":"ทางแก้ใดตรงจุดที่สุด?","opts":[{"t":"เพิ่มจำนวน shard จาก 6 เป็น 12 เพื่อกระจาย keyspace ให้กว้างขึ้น","why":"key หนึ่งอยู่ใน shard เดียว การเพิ่ม shard ไม่ลด load ของ key นั้น"},{"t":"เพิ่ม read replica แล้วกระจาย read และเก็บ local cache อายุสั้นในแอป","why":"ลดการอ่าน key เดียวบน shard เดียว (สไลด์ 52)"},{"t":"ลด TTL ของ key นั้นให้สั้นลงเพื่อให้ข้อมูลสดขึ้นและลดการค้างของ cache","why":"miss มากขึ้น request ไป database เพิ่ม และไม่ลด read ต่อ key บน shard"},{"t":"เปลี่ยน eviction policy เป็น allkeys-lfu","why":"ปัญหาคือ traffic ไม่ใช่ memory เต็ม eviction จึงไม่เกี่ยว"}],"ans":1,"ref":"W12 · สไลด์ 52–53"},{"id":"w12-028","topic":"Cache failure patterns และ Eviction","level":"scen","story":"cache tier ใช้ Memcached 4 node เมื่อ node หนึ่งล่ม key ทั้งหมดบน node นั้นหายพร้อมกัน miss rate พุ่งและ database ถูกถล่มเป็นช่วงสั้น ๆ ทีมต้องการให้การล่มของ node เดียวไม่ทำให้ cache ว่างบางส่วน","q":"ควรแก้อย่างไร?","opts":[{"t":"เพิ่ม random jitter ให้ TTL","why":"jitter กระจายเวลาหมดอายุ แต่ไม่ช่วยเมื่อ key หายเพราะ node ล่ม"},{"t":"ใช้ lock ให้ request เดียวสร้างค่าใหม่แทน request ที่ miss พร้อมกัน","why":"เป็นวิธีของ stampede (key เดียว) ไม่ครอบคลุม key จำนวนมากที่หายพร้อมกัน"},{"t":"ย้ายไป Valkey ใช้ replica และ Multi-AZ ให้ node ล่มแล้ว cache ไม่ว่าง","why":"สไลด์ 50: replica และ Multi-AZ รองรับกรณี node ล่ม ซึ่ง Memcached ไม่มี replication"},{"t":"เพิ่ม TTL ให้ยาวขึ้น","why":"key ที่อยู่บน node ที่ล่มหายไปแล้ว TTL ยาวไม่ช่วย"}],"ans":2,"ref":"W12 · สไลด์ 36–37, 50"},{"id":"w12-029","topic":"Decoupling และ coupling","level":"know","story":"","q":"ข้อใดเป็นลักษณะของ tight coupling ตามสไลด์?","opts":[{"t":"การสื่อสารเป็น synchronous และ web server ติดต่อกับ app server โดยตรง","why":"ตามสไลด์ 67: ส่งแล้วรอคำตอบ และรู้ที่อยู่/ตัวตนของกัน"},{"t":"ผู้ส่งวางข้อความใน queue แล้วไปทำงานต่อโดยไม่รอผู้รับ","why":"เป็นลักษณะ asynchronous ซึ่งเป็น loose coupling"},{"t":"มี load balancer คั่นระหว่างแต่ละ tier","why":"ตัวกลางเป็นแนวทางของ loose coupling"},{"t":"แต่ละฟังก์ชันแยก deploy และ scale เป็นอิสระ","why":"เป็นลักษณะของ microservice (loose coupling)"}],"ans":0,"ref":"W12 · สไลด์ 67–68"},{"id":"w12-030","topic":"Decoupling และ coupling","level":"apply","story":"","q":"web tier มี 3 server เชื่อมตรงกับ app tier 3 server แบบ many-to-many ถ้าเพิ่ม web server อีก 1 ตัว ต้องเพิ่ม connection ในโค้ดกี่เส้นเทียบกับกรณีมี ALB1 และ ALB2 คั่น?","opts":[{"t":"tight coupling เพิ่ม 1 เส้น ส่วนแบบมี ALB เพิ่ม 1 เส้น","why":"web server ใหม่ต้องเชื่อมกับ app server ทุกตัวในกรณี tight coupling ไม่ใช่เส้นเดียว"},{"t":"tight coupling เพิ่ม 12 เส้น เพราะต้องเชื่อมทั้งตาราง ส่วนแบบมี ALB เพิ่ม 2 เส้น","why":"12 คือจำนวนเส้นรวมของ 4 x 3 ไม่ใช่จำนวนที่เพิ่มจาก server หนึ่งตัว"},{"t":"tight coupling เพิ่ม 3 เส้น ส่วนแบบมี ALB เพิ่ม 2 เส้น","why":"web server ใหม่ต้องรู้จัก app server ทุกตัว (3) แต่ถ้ามี ALB ต้องการเพียง 2 connection (สไลด์ 68–69)"},{"t":"tight coupling เพิ่ม 3 เส้น ส่วนแบบมี ALB เพิ่ม 3 เส้น","why":"ALB ทำให้ไม่ต้องรู้จัก app server แต่ละตัว จึงไม่ต้องเพิ่มเท่ากับจำนวน app server"}],"ans":2,"ref":"W12 · สไลด์ 68–69"},{"id":"w12-031","topic":"Decoupling และ coupling","level":"know","story":"","q":"การแยกฟังก์ชันของ monolith เป็น microservice ให้ประโยชน์เชิงกลไกข้อใดตามสไลด์?","opts":[{"t":"ทุก service ใช้ CPU และ memory ร่วมกันใน process เดียวเพื่อประสิทธิภาพสูงสุด","why":"นั่นคือลักษณะของ monolith ที่ทำให้ฟังก์ชันหนึ่งกินทรัพยากรของฟังก์ชันอื่น"},{"t":"แต่ละ service deploy และ scale เป็นอิสระ และความล้มเหลวถูกจำกัดขอบเขต (fault isolation)","why":"ตามสไลด์ 71: เพิ่ม instance เฉพาะ transcoding ได้ และ service หนึ่งล่มไม่ทำให้ service อื่นล่ม"},{"t":"ลดความซับซ้อนของระบบเพราะไม่ต้องเรียกข้าม service","why":"ตรงข้าม: microservice เพิ่มความซับซ้อนแบบกระจาย (เพิ่มเติม เช่น service discovery, observability)"},{"t":"ทำให้การสื่อสารระหว่าง service เป็น asynchronous โดยอัตโนมัติ","why":"microservice หลัง ALB ยังเป็น synchronous จะเป็น async ต้องมี queue/topic"}],"ans":1,"ref":"W12 · สไลด์ 70–71, 74"},{"id":"w12-032","topic":"Decoupling และ coupling","level":"apply","story":"","q":"ข้อใดจัดประเภทโซลูชัน loose coupling ได้ถูกต้องตามสไลด์?","opts":[{"t":"ELB: sync infra, microservice: sync app, SQS: async queue, SNS: async topic","why":"ตรงตามตารางสไลด์ 74"},{"t":"ELB: asynchronous (queue based), SQS: synchronous (infrastructure level)","why":"ELB เป็น synchronous และ SQS เป็น asynchronous ที่ใช้ queue"},{"t":"microservice: asynchronous (topic based), SNS: synchronous (application level)","why":"microservice เป็น synchronous ระดับ application และ SNS เป็น asynchronous แบบ topic"},{"t":"ELB และ SQS: synchronous ทั้งคู่ ต่างกันที่ระดับ infrastructure กับ application","why":"SQS เป็น asynchronous เพราะผู้ส่งไม่รอผู้รับ"}],"ans":0,"ref":"W12 · สไลด์ 74"},{"id":"w12-033","topic":"Decoupling และ coupling","level":"scen","story":"web application เดียวรวมการประมวลผลธุรกรรมการเงิน การ transcode รูปภาพ และการคำนวณไว้ใน codebase เดียวบน application server เมื่อมีงาน transcode หนัก CPU ขึ้น 100% ธุรกรรมการเงินช้าและ timeout และต้อง scale ทั้งแอปทั้งที่คอขวดคือ transcode อย่างเดียว","q":"ควรปรับสถาปัตยกรรมอย่างไรให้ตรงจุดที่สุด?","opts":[{"t":"แยกเป็น microservice ให้ transcode ผ่าน SQS แล้ว scale เฉพาะ transcoding consumer","why":"ตัดการแชร์ CPU/memory และ scale เฉพาะส่วนที่เป็นคอขวด ด้วย fault isolation (สไลด์ 71–72)"},{"t":"เพิ่มขนาด instance ของ application server ให้ใหญ่ขึ้นเพื่อรับงานหนักได้มากขึ้น","why":"ทุกฟังก์ชันยังแชร์ทรัพยากรใน process เดียว งานหนักยังแย่ง CPU กับธุรกรรมเงินได้"},{"t":"เพิ่ม web server อีกหลายตัวหลัง ALB1 เพื่อรองรับ request มากขึ้น","why":"web tier ไม่ใช่จุดคอขวด coupling อยู่ที่ฟังก์ชันภายใน application tier"},{"t":"เปิด sticky sessions ที่ ALB2","why":"sticky ผูก session กับ instance เดิม ไม่แก้การแย่งทรัพยากรภายในแอป"}],"ans":0,"ref":"W12 · สไลด์ 70–72"},{"id":"w12-034","topic":"Decoupling และ coupling","level":"scen","story":"โรงงานประมวลผลภาพในศูนย์ข้อมูลองค์กร (on-premises) มี image producer ที่ส่งข้อความผ่าน message broker แบบ RabbitMQ ด้วยโปรโตคอล AMQP อยู่แล้ว ต้องการย้าย consumer ที่ transcode ไปรันบน AWS โดยไม่เขียนโค้ด messaging ใหม่","q":"บริการ AWS ใดเหมาะที่สุด?","opts":[{"t":"Amazon SQS แบบ standard queue","why":"ใช้ API เฉพาะของ AWS ต้องเปลี่ยนโค้ดฝั่ง producer และ consumer"},{"t":"Amazon SNS แบบ standard topic","why":"เป็น pub/sub แบบ push ที่ไม่เก็บข้อความ และใช้ API เฉพาะของ AWS เช่นกัน"},{"t":"Application Load Balancer แบบ internal","why":"เป็น synchronous load balancing ที่กระจาย request ไม่ใช่ message broker"},{"t":"Amazon MQ (managed broker สำหรับ ActiveMQ/RabbitMQ)","why":"รองรับโปรโตคอลมาตรฐาน (เพิ่มเติม เช่น AMQP, JMS) จึงย้ายโดยไม่ต้องเขียนโค้ดใหม่ (สไลด์ 73)"}],"ans":3,"ref":"W12 · สไลด์ 73–74"},{"id":"w12-035","topic":"Decoupling และ coupling","level":"scen","story":"web server แต่ละตัวตั้งค่า IP ของ app server 2 ตัวไว้ในโค้ดโดยตรง เมื่อ app server ตัวหนึ่งล่ม thread ของ web server ที่รอคำตอบค้างและ timeout ทั้งระบบช้า และการเพิ่ม app server ใหม่ต้อง redeploy web server ทุกตัว","q":"ข้อใดแก้ปัญหา coupling ระดับ tier ได้ตรงจุดที่สุด?","opts":[{"t":"เพิ่มค่า timeout ของ web server ให้นานขึ้นเพื่อรอ app server ที่ช้า","why":"เพียงทำให้ thread ค้างนานขึ้น ความล้มเหลวยังลามตามเดิม"},{"t":"วาง ALB ระหว่าง web tier กับ app tier ให้ web เรียก DNS ของ ALB และให้ ALB ทำ health check","why":"ตัดการพึ่งพา instance รายตัว ส่ง request เฉพาะ target ที่ healthy และ scale โดยไม่แก้โค้ด (สไลด์ 69)"},{"t":"เพิ่ม app server ตัวที่ 3 แล้ว hardcode IP ในทุก web server เพื่อกระจายโหลด","why":"เพิ่มจำนวน connection ที่ต้องดูแลตามผลคูณ และยังผูกกับ instance รายตัว"},{"t":"เพิ่ม CPU ให้ app server ทุกตัว","why":"ไม่แก้ปัญหา hardcode และการพึ่งพา instance ที่ล่ม"}],"ans":1,"ref":"W12 · สไลด์ 67–69"},{"id":"w12-036","topic":"SQS","level":"know","story":"","q":"ข้อใดคือคุณสมบัติของ SQS standard queue?","opts":[{"t":"Exactly-once processing และส่งตามลำดับที่ส่งเข้าเสมอ","why":"เป็นคุณสมบัติของ FIFO queue"},{"t":"At-most-once delivery โดยข้อความอาจสูญหายแต่ไม่ซ้ำ","why":"standard รับประกันอย่างน้อยหนึ่งครั้ง ไม่ใช่อย่างมากหนึ่งครั้ง"},{"t":"Exactly-once processing แต่ลำดับอาจสลับ","why":"exactly-once เป็นของ FIFO และ standard อาจส่งซ้ำ"},{"t":"At-least-once delivery และ best-effort ordering","why":"ตามสไลด์ 82 ผู้รับจึงควรเป็น idempotent"}],"ans":3,"ref":"W12 · สไลด์ 82"},{"id":"w12-037","topic":"SQS","level":"know","story":"","q":"ข้อใดเกี่ยวกับค่า retention และ visibility timeout เริ่มต้นของ SQS ถูกต้อง?","opts":[{"t":"retention เริ่มต้น 14 วัน และ visibility timeout เริ่มต้น 12 ชั่วโมง","why":"14 วันและ 12 ชั่วโมงคือค่าสูงสุด ไม่ใช่ค่าเริ่มต้น"},{"t":"retention เริ่มต้น 30 วินาที และ visibility timeout เริ่มต้น 4 วัน","why":"สลับกัน"},{"t":"message retention เริ่มต้น 4 วัน (ตั้งได้สูงสุด 14 วัน) และ visibility timeout เริ่มต้น 30 วินาที","why":"ตรงตามข้อมูลเพิ่มเติมในสไลด์ 80 (ค่าเริ่มต้นเป็นข้อมูลเพิ่มเติม)"},{"t":"retention เริ่มต้น 1 วัน และ visibility timeout เริ่มต้น 5 นาที","why":"ไม่ตรงกับค่าเริ่มต้นของ SQS"}],"ans":2,"ref":"W12 · สไลด์ 80"},{"id":"w12-038","topic":"SQS","level":"know","story":"","q":"dead-letter queue (DLQ) ของ SQS ใช้ทำอะไร?","opts":[{"t":"เก็บข้อความที่ส่งซ้ำออกไปเพื่อให้ standard queue ประมวลผลแบบ exactly-once ได้","why":"การลดข้อความซ้ำเป็นหน้าที่ของ FIFO/deduplication ไม่ใช่ DLQ"},{"t":"เก็บข้อความที่ประมวลผลไม่สำเร็จ (เกิน maxReceiveCount) เพื่อตรวจสอบสาเหตุ","why":"ตามสไลด์ 80 (maxReceiveCount เป็นข้อมูลเพิ่มเติม)"},{"t":"เก็บข้อความที่ผู้ส่งยังส่งไม่สำเร็จเมื่อ queue เต็มหรือถูกจำกัด throughput","why":"DLQ รับข้อความที่ consumer ประมวลผลไม่สำเร็จ ไม่ใช่ที่พักฝั่ง producer"},{"t":"เก็บสำเนาข้อความทุกตัวสำรองไว้เพื่อ replay ภายหลังเมื่อต้องการ","why":"DLQ เก็บเฉพาะข้อความที่ล้มเหลว ไม่ใช่สำเนาทั้งหมด"}],"ans":1,"ref":"W12 · สไลด์ 80"},{"id":"w12-039","topic":"SQS","level":"apply","story":"","q":"consumer ตั้ง receive message wait time เป็น 10 วินาที ผลต่อพฤติกรรมการ poll คืออะไร?","opts":[{"t":"long polling: SQS ถือ request ค้างได้ถึง 10 วินาทีจนมีข้อความ","why":"wait time > 0 คือ long polling (สไลด์ 83)"},{"t":"เป็น short polling: SQS ตอบทันทีแม้ queue ว่าง","why":"short polling คือ wait time = 0"},{"t":"ข้อความที่ถูกรับจะซ่อนจาก consumer อื่นนาน 10 วินาที","why":"นั่นคือ visibility timeout คนละพารามิเตอร์กับ wait time"},{"t":"ข้อความจะอยู่ใน queue ได้อย่างมาก 10 วินาที","why":"อายุข้อความควบคุมด้วย retention period"}],"ans":0,"ref":"W12 · สไลด์ 83–84"},{"id":"w12-040","topic":"SQS","level":"apply","story":"","q":"consumer รับข้อความจาก queue ที่ visibility timeout 30 วินาที แล้ว process ล่มก่อนส่งคำสั่ง delete — ข้อความนั้นจะเกิดอะไรขึ้น?","opts":[{"t":"ถูกลบทันทีที่ consumer รับ","why":"receive ไม่ลบ ต้องส่ง delete อย่างชัดเจน"},{"t":"ถูกซ่อนจนครบ 30 วินาที แล้วกลับมาให้เห็นและถูกประมวลผลซ้ำ","why":"การ receive ไม่ใช่การลบ ข้อความอยู่จนกว่าจะถูก delete (สไลด์ 84–85)"},{"t":"สูญหายถาวรเพราะ consumer ล่ม","why":"ข้อความไม่หาย กลับมาเมื่อ visibility timeout หมด"},{"t":"ถูกย้ายไป DLQ ทันทีหลังจาก visibility timeout ครั้งแรกหมดลง","why":"ย้ายไป DLQ เมื่อรับเกิน maxReceiveCount ไม่ใช่ครั้งแรก"}],"ans":1,"ref":"W12 · สไลด์ 84–85"},{"id":"w12-041","topic":"SQS","level":"apply","story":"","q":"แผนภาพแสดงข้อความหมายเลข 3, 2, 1 ถูกส่งเข้า queue แล้วผู้รับได้ลำดับ 2, 3, 1, 3 — queue ชนิดใดให้พฤติกรรมนี้ และเพราะเหตุใด?","opts":[{"t":"FIFO queue เพราะ throughput สูงทำให้ลำดับสลับ","why":"FIFO ส่งตามลำดับ (3, 2, 1) และไม่ซ้ำ"},{"t":"FIFO queue เพราะ exactly-once ทำให้ลำดับสลับแต่ไม่ซ้ำ","why":"ผลนี้ซ้ำ และ FIFO รักษาลำดับ"},{"t":"ไม่ใช่ queue ใดเลย เป็นผลจาก visibility timeout สั้นเกินไปเท่านั้น","why":"visibility timeout ทำให้ซ้ำได้ แต่ไม่ใช่เหตุที่ลำดับสลับ ซึ่งมาจากชนิด queue"},{"t":"standard queue: best-effort ordering และ at-least-once","why":"ตรงกับสไลด์ 82"}],"ans":3,"ref":"W12 · สไลด์ 82"},{"id":"w12-042","topic":"SQS","level":"scen","story":"คิวคำสั่งซื้อมีข้อความรอประมวลผลสูงถึง 50,000 ข้อความในช่วงลงทะเบียน ขณะที่ order fulfillment ใช้ EC2 คงที่ 2 instance ทำให้ข้อความค้างนาน ทีมต้องการให้จำนวน consumer เพิ่มอัตโนมัติเมื่อคิวยาว","q":"ควรใช้สัญญาณใดเป็นตัวกระตุ้น scaling?","opts":[{"t":"queue length (เช่น ApproximateNumberOfMessagesVisible) ผ่าน CloudWatch alarm","why":"ใช้ queue length เป็นตัวบ่งชี้โหลดของ consumer (สไลด์ 86)"},{"t":"ค่า CPU เฉลี่ยของ instance ฝั่ง producer (order capture) ผ่าน CloudWatch alarm","why":"producer รับ request อยู่แล้ว ส่วนคอขวดคือ consumer ที่ดึงจากคิว"},{"t":"เพิ่ม visibility timeout ให้ยาวขึ้นเพื่อให้ consumer มีเวลาประมวลผลมากขึ้น","why":"ไม่เพิ่มอัตราการประมวลผล มีผลเพียงช่วงที่ข้อความถูกซ่อน"},{"t":"เปลี่ยน queue เป็น short polling เพื่อให้ consumer ได้รับข้อความเร็วขึ้น","why":"short polling เพิ่ม empty response และ request ไม่ได้เพิ่มจำนวน consumer"}],"ans":0,"ref":"W12 · สไลด์ 81, 86"},{"id":"w12-043","topic":"SQS","level":"scen","story":"order capture เขียนคำสั่งซื้อลง Amazon RDS โดยตรงทุก request เมื่อ traffic พุ่งเป็น 10 เท่าในช่วงเปิดลงทะเบียน connection ของ database หมดและบางคำสั่งซื้อล้มเหลว ทีมต้องการรับคำสั่งซื้อทั้งหมดโดยไม่หาย และเขียนลง database ในอัตราที่ database รับไหว","q":"ควรออกแบบอย่างไร?","opts":[{"t":"ให้ order capture ส่งเข้า SQS แล้วให้ consumer ดึงไปเขียน database ตามอัตราที่รับไหว","why":"queue ซึมซับ spike และ decouple ความเร็วของ producer จาก consumer (สไลด์ 81, 86)"},{"t":"ให้ order capture publish ไป SNS topic แล้วให้ database เป็น subscriber ผ่าน endpoint ของมัน","why":"SNS push ทันทีและไม่เก็บข้อความ database ก็ยังโดน spike เต็มที่ และเป็น subscriber โดยตรงไม่ได้"},{"t":"เปิด sticky sessions ที่ ALB หน้า order capture","why":"ไม่ลดจำนวน write ที่ไปถึง database"},{"t":"เพิ่ม TTL ของ cache หน้า database","why":"คำสั่งซื้อเป็น write ซึ่ง cache ไม่ช่วยรับ"}],"ans":0,"ref":"W12 · สไลด์ 81, 86"},{"id":"w12-044","topic":"SNS และ SNS vs SQS","level":"know","story":"","q":"ข้อใดเปรียบเทียบ SNS กับ SQS ได้ถูกต้องตามสไลด์?","opts":[{"t":"SNS: one to one, pull, เก็บข้อความ / SQS: one to many, push, ไม่เก็บข้อความ","why":"สลับคุณสมบัติของสองบริการ"},{"t":"SNS: pub-sub, one to many, push, ไม่เก็บ / SQS: producer-consumer, one to one, pull, เก็บ","why":"ตรงตามตารางสไลด์ 95"},{"t":"SNS: one to many, pull, เก็บข้อความ / SQS: one to one, push, ไม่เก็บข้อความ","why":"SNS ผลัก (push) และไม่เก็บ ส่วน SQS ให้ consumer ดึง (pull) และเก็บ"},{"t":"SNS และ SQS: one to many ทั้งคู่ ต่างกันที่กลไก push กับ pull","why":"SQS เป็น one to one: แต่ละข้อความถูกประมวลผลโดย consumer ตัวเดียว"}],"ans":1,"ref":"W12 · สไลด์ 95"},{"id":"w12-045","topic":"SNS และ SNS vs SQS","level":"know","story":"","q":"ข้อใดไม่ใช่ปลายทางที่ subscribe SNS topic ได้ตามสไลด์?","opts":[{"t":"AWS Lambda function","why":"เป็น subscriber ที่รองรับ"},{"t":"SQS queue","why":"เป็น subscriber ที่รองรับ และเป็นรูปแบบ fan-out ที่ใช้บ่อย"},{"t":"Amazon RDS DB instance","why":"ไม่อยู่ในรายการ subscriber ของ SNS"},{"t":"HTTP หรือ HTTPS endpoint","why":"เป็น subscriber ที่รองรับ (ต้องยืนยัน subscription ก่อน)"}],"ans":2,"ref":"W12 · สไลด์ 91"},{"id":"w12-046","topic":"SNS และ SNS vs SQS","level":"apply","story":"","q":"publisher ส่งข้อความ 10 ข้อความ กรณี A: SNS topic ที่มี 3 subscriber กรณี B: SQS queue เดียวที่มี consumer 3 ตัวแย่งกันดึง — จำนวนการส่งมอบ (delivery) ถึงปลายทางรวมกรณี A และ B คือเท่าใด?","opts":[{"t":"A = 10 และ B = 30 เพราะ consumer ทุกตัวได้ทุกข้อความ","why":"สลับกัน: SNS ส่งสำเนาถึงทุก subscriber"},{"t":"A = 30 และ B = 30","why":"consumer หลายตัวในคิวเดียวกันแย่งข้อความ แต่ละข้อความไม่ซ้ำถึงทุกตัว"},{"t":"A = 10 และ B = 10","why":"SNS ส่งสำเนาถึง subscriber ทั้ง 3 ราย"},{"t":"A = 30 และ B = 10","why":"SNS เป็น one to many ส่วน SQS เป็น one to one (สไลด์ 77, 89, 95)"}],"ans":3,"ref":"W12 · สไลด์ 77, 89, 95"},{"id":"w12-047","topic":"SNS และ SNS vs SQS","level":"apply","story":"","q":"publisher ส่งข้อความผิดพลาดไปยัง SNS topic ที่มี subscriber หลายราย เพิ่งตรวจพบทันทีหลัง publish — ข้อใดเป็นจริงเกี่ยวกับการแก้สถานการณ์นี้?","opts":[{"t":"ลบข้อความออกจาก topic ได้ เพราะ topic เก็บข้อความไว้จนกว่าจะส่งครบทุกราย","why":"SNS ไม่เก็บข้อความถาวร ไม่มีที่ให้ลบ"},{"t":"เรียกคืนไม่ได้ ต้อง publish ข้อความแก้ไขตามไป","why":"SNS ไม่มี recall (สไลด์ 94)"},{"t":"ตั้ง visibility timeout ให้ข้อความหายไปชั่วคราว","why":"visibility timeout เป็นแนวคิดของ SQS ไม่ใช่ SNS"},{"t":"ใช้ delivery policy ของ HTTP/HTTPS เพื่อสั่งยกเลิกการส่งที่ค้างอยู่ทั้งหมด","why":"delivery policy ปรับพฤติกรรม retry ไม่ใช่เรียกคืนข้อความ"}],"ans":1,"ref":"W12 · สไลด์ 94"},{"id":"w12-048","topic":"SNS และ SNS vs SQS","level":"know","story":"","q":"เมื่อใดควรเลือก FIFO topic แทน standard topic ของ SNS?","opts":[{"t":"เมื่อต้องส่งข้อความไปยังผู้รับได้ไม่จำกัดจำนวนโดยไม่สนใจลำดับ","why":"กรณีลำดับไม่สำคัญควรเลือก standard topic"},{"t":"เมื่อต้องการให้ SNS เก็บข้อความไว้นานกว่า retry","why":"SNS ไม่เก็บข้อความถาวรทั้งสองชนิด การเก็บทำได้ด้วย SQS"},{"t":"เมื่อต้องการลำดับการส่งที่แน่นอน","why":"ตามสไลด์ 94 ใช้ standard topic หากลำดับไม่สำคัญ และใช้ FIFO topic หากต้องการลำดับ"},{"t":"เมื่อต้องการ recall ข้อความที่ publish ผิด","why":"SNS ไม่มี recall ทั้งสองชนิด"}],"ans":2,"ref":"W12 · สไลด์ 94"},{"id":"w12-049","topic":"SNS และ SNS vs SQS","level":"scen","story":"ระบบประมวลผลรูปอัปโหลด: S3 ส่ง event ไปยัง SNS topic ซึ่ง fan-out ไปยัง SQS 3 queue (mobile size, thumbnail, web size) โดยแต่ละ queue มี Auto Scaling group ของตัวเอง ตอนนี้ต้องเพิ่มงาน watermark เป็นงานที่ 4 โดยไม่แก้ S3 หรือ producer และไม่กระทบงานเดิม","q":"ควรทำอย่างไร?","opts":[{"t":"แก้การตั้งค่า S3 ให้ส่ง event ไปยัง queue ที่ 4 โดยตรงอีกทางหนึ่งควบคู่กับ topic","why":"ต้องแก้ฝั่ง publisher และเลิกใช้ประโยชน์ของ topic ที่เพิ่ม subscriber ได้โดยไม่แก้โค้ด"},{"t":"สร้าง SQS queue + Auto Scaling group สำหรับ watermark แล้ว subscribe เข้า topic เดิม","why":"topic ส่งสำเนาไปยัง subscriber เพิ่มได้โดย publisher ไม่ต้องแก้ และ queue ของแต่ละงานแยกกัน (สไลด์ 89, 93)"},{"t":"ให้ consumer ของ thumbnail ทำ watermark ต่อจากงานเดิมภายในแอปเดียวกัน","why":"รวมงานเข้าด้วยกันทำให้เกิด tight coupling และ scale แยกไม่ได้"},{"t":"ให้ mobile client เขียนลง queue ที่ 4 เองหลังอัปโหลดเสร็จ","why":"ผูก client กับรายละเอียดของงานหลังบ้าน และข้ามจุดกระจายของ SNS"}],"ans":1,"ref":"W12 · สไลด์ 89, 93"},{"id":"w12-050","topic":"SNS และ SNS vs SQS","level":"scen","story":"ระบบแจ้งเตือนใช้ SNS topic ส่งเหตุการณ์ไปยัง HTTPS endpoint ของระบบปลายทาง เมื่อ endpoint ปิดซ่อมบำรุงนาน 2 ชั่วโมง ข้อความที่ publish ในช่วงนั้นสูญหายหลัง retry หมด ทั้งที่ต้องการให้ประมวลผลได้ครบเมื่อระบบกลับมา","q":"ควรปรับอย่างไรให้ได้ความทนทานของข้อความ?","opts":[{"t":"เปลี่ยน topic เป็น FIFO topic","why":"FIFO topic รับประกันลำดับ ไม่ได้ทำให้เก็บข้อความระหว่างที่ปลายทางล่ม"},{"t":"เพิ่มความถี่ในการ publish ซ้ำ","why":"เป็นการส่งซ้ำโดยไม่มีที่เก็บรองรับ และเพิ่มข้อความซ้ำ"},{"t":"subscribe SQS queue เข้า topic แล้วให้ปลายทางดึงจาก queue เมื่อพร้อม","why":"SQS เก็บข้อความ (persist) จนกว่า consumer จะลบ ส่วน SNS ไม่เก็บ (สไลด์ 94–95)"},{"t":"เรียก recall ข้อความที่ส่งไม่สำเร็จแล้ว publish ใหม่เมื่อ endpoint กลับมา","why":"SNS ไม่มี recall และการ publish ใหม่ไม่แก้ปัญหาปลายทางไม่พร้อม"}],"ans":2,"ref":"W12 · สไลด์ 94–95"}],"w13":[{"id":"w13-001","topic":"Serverless และ Microservices","level":"know","story":"","q":"ตามสไลด์ 4 ข้อใดเป็นประโยชน์ของบริการ serverless บน AWS?","opts":[{"t":"ผู้ใช้เลือก instance type และ patch OS ของทุกชั้นได้ด้วยตัวเอง","why":"ผิด นั่นคือแบบ server ใน VPC; serverless ผู้ใช้ไม่ต้อง provision/patch OS (No server management)"},{"t":"ต้องกำหนด Auto Scaling group ล่วงหน้าเพื่อให้ได้ continuous scaling","why":"ผิด การ scale เกิดภายในบริการ ไม่ต้องกำหนด Auto Scaling group หรือ capacity ล่วงหน้า"},{"t":"Built-in high availability: ทำงานข้ามหลาย AZ โดยค่าเริ่มต้น","why":"ถูก ผู้ใช้ไม่ต้องออกแบบ redundancy ข้าม AZ เอง เพราะบริการถูกออกแบบให้กระจายข้าม AZ อยู่แล้ว"},{"t":"ค่าบริการคิดตามความจุที่จองไว้ล่วงหน้าตลอดทั้งเดือน","why":"ผิด Pay-for-value คิดตามการใช้งานที่วัดได้ เช่น request, duration, memory, state transition"}],"ans":2,"ref":"W13 · สไลด์ 4, 7"},{"id":"w13-002","topic":"Serverless และ Microservices","level":"know","story":"","q":"ใน web app three-tier แบบ serverless (สไลด์ 6) บริการใดทำหน้าที่ web tier สำหรับ static content (HTML/JS/CSS)?","opts":[{"t":"Amazon API Gateway เรียก AWS Lambda","why":"ผิด ชุดนี้คือ app tier ที่รับ API request และรัน business logic"},{"t":"Amazon CloudFront ดึงเนื้อหาจาก Amazon S3","why":"ถูก CloudFront เป็น entry point และดึง static content จาก S3 แทน Web EC2 + ALB"},{"t":"Amazon Cognito ร่วมกับ Amazon DynamoDB","why":"ผิด Cognito ทำ authentication ส่วน DynamoDB คือ data tier"},{"t":"Application Load Balancer กับ EC2 ใน Auto Scaling group","why":"ผิด นี่คือ web tier แบบ server-based ในสไลด์ 3 ซึ่ง serverless ไม่ใช้"}],"ans":1,"ref":"W13 · สไลด์ 3, 6"},{"id":"w13-003","topic":"Serverless และ Microservices","level":"know","story":"","q":"ข้อใดเป็นลักษณะ \"Specialized\" ของ microservice ตามสไลด์ 9?","opts":[{"t":"ใช้โค้ดส่วนกลางร่วมกับ microservice อื่นโดยแก้ codebase เดียวกัน","why":"ผิด ลักษณะ Autonomous ระบุว่าไม่แชร์โค้ดกับ microservice อื่น"},{"t":"เก็บ session state ไว้ในตัวบริการเพื่อให้ตอบ request ซ้ำได้เร็ว","why":"ผิด microservice ต้อง stateless; state ต้องอยู่ในที่เก็บภายนอก"},{"t":"ทำ business function เดียว มีทีมเล็กเป็นเจ้าของ เลือกเครื่องมือเองได้","why":"ถูก เป็นลักษณะในกลุ่ม Specialized"},{"t":"อ่านและเขียนตารางในฐานข้อมูลของบริการอื่นโดยตรงเพื่อลดการเรียก API","why":"ผิด แต่ละบริการต้องมี data store ของตัวเอง และสื่อสารผ่าน well-defined API"}],"ans":2,"ref":"W13 · สไลด์ 9"},{"id":"w13-004","topic":"Serverless และ Microservices","level":"apply","story":"","q":"จากตาราง Operational task comparison (สไลด์ 16) งานใดที่ผู้ใช้ยังต้องทำเองแม้ใช้ serverless?","opts":[{"t":"Update operating system (OS) ของ instance ที่รันแอป","why":"ผิด ใน serverless เป็น No ผู้ให้บริการดูแล OS"},{"t":"Build and deploy apps และ Monitor and maintain apps","why":"ถูก สองแถวนี้เป็น Yes ทั้งใน server ใน VPC และ serverless ตามสไลด์ 16"},{"t":"Configure automatic scaling and load balancing ให้แอป","why":"ผิด ใน serverless เป็น No เพราะ scaling อยู่ในบริการ"},{"t":"Install application platform บน instance ก่อนรันแอป","why":"ผิด ใน serverless เป็น No ผู้ใช้ไม่ต้องติดตั้ง platform บน instance"}],"ans":1,"ref":"W13 · สไลด์ 16"},{"id":"w13-005","topic":"Serverless และ Microservices","level":"apply","story":"","q":"ระบบรับข้อมูล clickstream ต่อเนื่องจากเว็บไซต์ และต้องการ pattern แบบ serverless microservice ข้อใดตรงกับแบบ Streaming ในสไลด์ 12 และโมเดลการเรียกของ Lambda?","opts":[{"t":"Kinesis รับสตรีม แล้ว Lambda ดึงเป็น batch ผ่าน event source mapping","why":"ถูก ช่องทางเข้า Kinesis เป็น stream ที่ Lambda poll เป็น batch (สไลด์ 12, 24)"},{"t":"API Gateway รับ request แล้ว invoke Lambda แบบ synchronous โดยผู้เรียกรอผลลัพธ์","why":"ผิด นี่คือ pattern RESTful APIs แบบ request/response ไม่ใช่ streaming"},{"t":"ALB กระจาย request ไปยังคอนเทนเนอร์บน Fargate ที่ต่อกับ data store แบบ serverless","why":"ผิด นี่คือ pattern Containers ซึ่งเป็น synchronous request ผ่าน load balancer"},{"t":"CloudFront ดึงข้อมูลจาก S3 แล้วให้ Cognito ออก token ก่อนส่งถึงผู้ใช้","why":"ผิด เป็นชั้น web/authentication ไม่ใช่การประมวลผลสตรีม"}],"ans":0,"ref":"W13 · สไลด์ 12, 24"},{"id":"w13-006","topic":"Serverless และ Microservices","level":"scen","story":"ทีมแยกระบบ messaging เป็น User, Topic และ Message service แล้ว แต่ทั้ง 3 service ยังอ่านเขียนฐานข้อมูล relational ก้อนเดียว เมื่อทีม Topic แก้ schema ของตาราง ต้องประสานและ redeploy อีก 2 service ทุกครั้ง ขณะที่ Message service ถูกเรียกถี่กว่า User service ราว 10 เท่า","q":"ควรแก้อย่างไรเพื่อให้ได้ประโยชน์ด้าน independent deployment ของ microservice?","opts":[{"t":"แยก data store ต่อ service และให้ service อื่นเข้าถึงข้อมูลผ่าน API ที่นิยามไว้","why":"ถูก ตัด coupling ระดับ schema ทำให้ deploy/scale แยกกันได้ โดยแลกกับความซับซ้อนเรื่อง consistency ข้ามบริการ"},{"t":"รวม 3 service กลับเป็นแอปเดียวเพื่อไม่ต้องประสานการเปลี่ยน schema ระหว่างทีม","why":"ผิด ย้อนกลับเป็น monolith ที่ต้อง deploy และ scale ทั้งก้อน เสียประโยชน์ flexible scaling"},{"t":"เพิ่มจำนวน instance ของทั้ง 3 service เท่ากันเพื่อรองรับภาระของ Message service","why":"ผิด ไม่แก้ coupling ของ schema และ scale ทั้งหมดเป็นการสิ้นเปลือง ต่างจาก scale เฉพาะบริการ"},{"t":"สร้างไลบรารีกลางที่เก็บ schema ร่วมและให้ทุก service import ไปใช้งานร่วมกัน","why":"ผิด ยังคงแชร์โค้ดและฐานข้อมูลร่วมกัน ฝ่าฝืนหลัก autonomous จึงเป็น distributed monolith"}],"ans":0,"ref":"W13 · สไลด์ 9–11"},{"id":"w13-007","topic":"Serverless และ Microservices","level":"scen","story":"เว็บ three-tier แบบ serverless มี route /orders และ /profiles ทีม orders deploy วันละหลายครั้ง ส่วนทีม profiles แทบไม่เปลี่ยนโค้ด ปัจจุบันทั้งสอง route ชี้ไปที่ Lambda function ตัวเดียวและใช้ DynamoDB table เดียว ทำให้ deploy ของทีมหนึ่งกระทบอีกทีม","q":"โครงสร้างใดสอดคล้องกับสไลด์ 13 (microservice ภายใน app และ data tier)?","opts":[{"t":"คง Lambda ตัวเดียวแต่แยกโค้ดเป็นหลายไฟล์ในแพ็กเกจเดียวกัน","why":"ผิด ยัง deploy เป็นหน่วยเดียวจึงยังกระทบกันอยู่"},{"t":"ย้าย app tier ไปรันบน EC2 ใน Auto Scaling group สองชุดแยกกัน","why":"ผิด กลับไปจัดการ server และ ASG เอง ไม่จำเป็นเพื่อแยกบริการ"},{"t":"API Gateway เดียว route แยกไป Lambda และ DynamoDB table คนละชุดต่อบริการ","why":"ถูก แต่ละ API operation เป็น microservice ที่มี compute และ data store ของตัวเอง deploy แยกกันได้"},{"t":"ใช้ Cognito สร้าง user pool แยกต่อ route เพื่อแยกบริการ","why":"ผิด Cognito ทำ authentication อยู่นอกกรอบ microservice ไม่ได้แยก compute/data ของบริการ"}],"ans":2,"ref":"W13 · สไลด์ 13, 14"},{"id":"w13-008","topic":"AWS Lambda","level":"know","story":"","q":"AWS Lambda รองรับรูปแบบการ deploy function แบบใดตามสไลด์ 17?","opts":[{"t":"เฉพาะไฟล์ .zip เท่านั้น เพราะ container image ใช้ได้กับ ECS เท่านั้น","why":"ผิด Lambda รัน function จาก container image ได้ด้วย"},{"t":"ไฟล์ .zip, container image หรือ AMI ที่เตรียมไว้ล่วงหน้า","why":"ผิด AMI ใช้กับ EC2 ไม่ใช่รูปแบบ deploy ของ Lambda"},{"t":"เฉพาะ container image เพื่อให้ dependency ถูกบรรจุครบ","why":"ผิด ยังมีรูปแบบ .zip ที่ใช้กันทั่วไป"},{"t":"ไฟล์ .zip หรือ container image ตามที่ function กำหนด","why":"ถูก ทั้งสองรูปแบบถูกระบุในสไลด์ 17"}],"ans":3,"ref":"W13 · สไลด์ 17"},{"id":"w13-009","topic":"AWS Lambda","level":"know","story":"","q":"แต่ละ Lambda function ในบริการ Lambda ถูกแยก isolation จากผู้ใช้อื่นด้วยกลไกใดตามสไลด์ 18?","opts":[{"t":"Docker container บน ECS cluster ใน VPC ของผู้ใช้","why":"ผิด function ไม่ได้รันใน VPC ของผู้ใช้โดยค่าเริ่มต้น"},{"t":"EC2 instance เฉพาะต่อผู้ใช้ในบัญชีของผู้ใช้เอง","why":"ผิด instance ถูกจัดการโดย Lambda ไม่ใช่ของผู้ใช้"},{"t":"process แยกกันภายใน OS เดียวกันที่ regional edge cache","why":"ผิด edge cache เป็นที่รันของ Lambda@Edge ไม่ใช่การแยก function ในบริการ Lambda"},{"t":"Firecracker microVM บน Lambda EC2 instance ใน Lambda service VPC","why":"ถูก function รันใน VPC ที่ AWS Lambda เป็นเจ้าของ และแยกด้วย microVM ระดับ VM"}],"ans":3,"ref":"W13 · สไลด์ 18"},{"id":"w13-010","topic":"AWS Lambda","level":"know","story":"","q":"ข้อใดอธิบาย Lambda layer ได้ถูกต้องตามสไลด์ 26?","opts":[{"t":"ชั้นเครือข่ายที่เชื่อม function เข้ากับ subnet ใน VPC ของผู้ใช้","why":"ผิด การเชื่อม VPC ทำด้วย VPC configuration (subnet + security group) และ ENI ไม่ใช่ layer"},{"t":"พื้นที่เก็บ state ถาวรที่แชร์ข้ามการ invoke ของ function ทั้งหมด","why":"ผิด layer เป็นไฟล์ที่ถูกแตกลงใน execution environment ไม่ใช่ที่เก็บ state"},{"t":"นโยบายที่กำหนดสิทธิ์ IAM ของ function ทุกตัวพร้อมกันในครั้งเดียว","why":"ผิด สิทธิ์กำหนดด้วย execution role ไม่เกี่ยวกับ layer"},{"t":"แพ็กเกจ .zip เก็บ dependency หรือ custom runtime ให้หลาย function ใช้ร่วม","why":"ถูก ทำให้แพ็กเกจ function เหลือเฉพาะ function code และไม่มีสำเนา dependency ซ้ำ"}],"ans":3,"ref":"W13 · สไลด์ 26"},{"id":"w13-011","topic":"AWS Lambda","level":"apply","story":"","q":"1 import json\n2 def lambda_handler(event, context):\n3     length=event['length']\n4     width=event['width']\n5     area = calculate_area(length, width)\n6     data = {\"area\": area}\n7     return json.dumps(data)\n8 def calculate_area(length, width):\n9     return length*width\nถ้า invoke handler ในสไลด์ 25 ด้วย event {\"length\": 4, \"width\": 5} ค่าที่ return คืออะไร?","opts":[{"t":"dict ของ Python ที่มี key area เท่ากับ 20","why":"ผิด บรรทัด 7 ใช้ json.dumps จึงได้ string ไม่ใช่ dict"},{"t":"JSON string ที่มีเนื้อหา {\"area\": 20}","why":"ถูก handler คำนวณ 4*5=20 แล้ว json.dumps แปลง dict เป็น JSON string"},{"t":"ตัวเลข 9 จากการบวก length กับ width","why":"ผิด calculate_area คูณ ไม่ได้บวก"},{"t":"KeyError เพราะ event ไม่มี key ชื่อ area","why":"ผิด handler อ่าน key length และ width ซึ่งมีอยู่ใน event; area เป็นค่าที่คำนวณขึ้นเอง"}],"ans":1,"ref":"W13 · สไลด์ 25"},{"id":"w13-012","topic":"AWS Lambda","level":"apply","story":"","q":"function ที่ CPU-bound ตั้ง memory 1024 MB ใช้เวลา 4 วินาที ถ้าเพิ่มเป็น 2048 MB จะเกิดอะไรขึ้นโดยทั่วไป?","opts":[{"t":"CPU เพิ่มตามสัดส่วน memory อาจลด duration แต่ราคาต่อ ms สูงขึ้น ต้องวัดต้นทุนรวม","why":"ถูก CPU ของ Lambda scale ตาม memory (สไลด์ 17) และราคาคิดจาก duration กับ memory"},{"t":"CPU คงเดิม เพราะ memory ของ function ไม่มีผลต่อกำลังประมวลผลที่ได้รับ","why":"ผิด ผู้ใช้กำหนดเฉพาะ memory แต่ CPU เพิ่มตามสัดส่วน"},{"t":"เพดาน timeout เพิ่มจาก 15 เป็น 30 นาที ตามสัดส่วนของ memory ที่เพิ่มขึ้น","why":"ผิด timeout ไม่ขึ้นกับ memory; ค่าสูงสุดของ Lambda มาตรฐานยังเป็น 15 นาที"},{"t":"function เปลี่ยนเป็นแบบ asynchronous อัตโนมัติเมื่อ memory เกิน 1024 MB","why":"ผิด วิธี invoke ถูกกำหนดโดยผู้เรียก ไม่เกี่ยวกับ memory"}],"ans":0,"ref":"W13 · สไลด์ 17, 68"},{"id":"w13-013","topic":"AWS Lambda","level":"apply","story":"","q":"S3 event trigger เรียก Lambda แบบ asynchronous แต่ function โยน error ทุกครั้งที่รัน และไม่ได้ตั้ง DLQ หรือ on-failure destination\nตามค่าเริ่มต้นของ asynchronous invocation (เพิ่มเติม) event หนึ่งรายการจะถูกรัน function สูงสุดกี่ครั้ง และเกิดอะไรกับ event หลังล้มเหลว?","opts":[{"t":"3 ครั้ง (รัน 1 + retry 2) แล้ว event ถูกทิ้งเพราะไม่มี DLQ หรือ destination","why":"ถูก Lambda retry ค่าเริ่มต้น 2 ครั้ง หากไม่มี DLQ/destination จะสูญเสีย event จึงควรตั้ง DLQ (สไลด์ 23, 65)"},{"t":"1 ครั้ง เพราะ asynchronous invocation ไม่มีการ retry ให้โดยอัตโนมัติ","why":"ผิด async มีการ retry อัตโนมัติ ต่างจาก synchronous ที่ผู้เรียกต้อง retry เอง"},{"t":"2 ครั้ง แล้ว Lambda ส่ง event ไปเก็บใน SQS queue ให้เองโดยอัตโนมัติ","why":"ผิด จำนวน attempt รวม 3 และ event ไม่ถูกส่งไปที่ใดเองหากไม่ตั้งค่า"},{"t":"ไม่จำกัดจำนวนครั้ง Lambda จะ retry ต่อไปจนกว่า function จะสำเร็จ","why":"ผิด retry มีจำนวนและช่วงเวลาจำกัด"}],"ans":0,"ref":"W13 · สไลด์ 23"},{"id":"w13-014","topic":"AWS Lambda","level":"scen","story":"Lambda function อยู่ใน private subnet ผ่านการตั้งค่า VPC และ query RDS ได้ปกติ แต่หลังจากเพิ่มโค้ดเรียก S3 และ DynamoDB ผ่าน public endpoint ของ AWS ทุกครั้งเกิด timeout VPC นี้ไม่มี NAT gateway และไม่มี VPC endpoint","q":"ควรแก้อย่างไร?","opts":[{"t":"เพิ่ม VPC endpoint สำหรับ S3/DynamoDB หรือ NAT gateway เพื่อให้มีเส้นทางออก","why":"ถูก เมื่อ function อยู่ใน VPC ต้องมีเส้นทางออกไปยังบริการ AWS (สไลด์ 19)"},{"t":"ถอด function ออกจากการตั้งค่า VPC ทั้งหมดเพื่อให้ใช้ network ของ Lambda","why":"ผิด จะเข้าถึง RDS ใน private subnet ไม่ได้อีก"},{"t":"เพิ่ม timeout ของ function เป็น 15 นาทีเพื่อรอการเชื่อมต่อให้นานขึ้น","why":"ผิด ปัญหาคือไม่มี network path ไม่ใช่เวลารัน"},{"t":"แยกไลบรารี AWS SDK ออกไปเป็น Lambda layer เพื่อให้เรียกบริการได้","why":"ผิด layer เปลี่ยนวิธีแพ็ก dependency ไม่ได้สร้างเส้นทางเครือข่าย"}],"ans":0,"ref":"W13 · สไลด์ 19"},{"id":"w13-015","topic":"AWS Lambda","level":"scen","story":"API ที่ใช้ Lambda ต่อกับ RDS ผ่าน VPC ช่วง flash sale scale ไปประมาณ 500 execution environment พร้อมกัน แต่ฐานข้อมูลแจ้ง too many connections เป็นระยะ เพราะแต่ละ environment เปิด connection ของตัวเอง","q":"ทางแก้ที่ตรงกับแผนภาพในสไลด์ 19 คืออะไร?","opts":[{"t":"เพิ่ม memory ของ function เพื่อให้แต่ละ environment ใช้ connection ได้น้อยลง","why":"ผิด ไม่ลดจำนวน connection ต่อ environment"},{"t":"เปลี่ยนเป็น asynchronous invocation เพื่อลดจำนวน environment ที่รันพร้อมกัน","why":"ผิด ยังมีหลาย environment รันพร้อมกันและเปิด connection เช่นเดิม"},{"t":"เก็บ connection ไว้ใน Lambda layer เพื่อให้ทุก environment ใช้ร่วมกัน","why":"ผิด layer เป็นไฟล์ read-only ไม่ใช่ connection pool และ environment ใช้ร่วมกันข้ามกันไม่ได้"},{"t":"วาง RDS Proxy ระหว่าง function กับ database เพื่อทำ connection pooling","why":"ถูก Proxy รวม connection จำนวนมากให้เหลือน้อยลงที่ฝั่ง database"}],"ans":3,"ref":"W13 · สไลด์ 19, 26"},{"id":"w13-016","topic":"Containers (ECS/EKS/Fargate)","level":"know","story":"","q":"ข้อใดตรงกับ AWS Fargate ตามสไลด์ 36?","opts":[{"t":"Serverless compute engine สำหรับคอนเทนเนอร์ ไม่ต้องจัดการ server ใช้ได้กับ ECS และ EKS","why":"ถูก"},{"t":"ใช้ได้เฉพาะกับ Amazon ECS เพราะเป็นส่วนของ ECS scheduler โดยตรง","why":"ผิด Fargate ใช้กับ EKS ได้ด้วย"},{"t":"ผู้ใช้ต้องเลือก AMI และ patch OS ของ node ที่รันคอนเทนเนอร์เอง","why":"ผิด นั่นคือ EC2; Fargate ไม่มี node ให้จัดการ"},{"t":"คิดค่าบริการรายเดือนตามขนาด instance ที่จองไว้ล่วงหน้าตลอดช่วงสัญญา","why":"ผิด Fargate คิดแบบต่อวินาที (per second billing)"}],"ans":0,"ref":"W13 · สไลด์ 35, 36"},{"id":"w13-017","topic":"Containers (ECS/EKS/Fargate)","level":"know","story":"","q":"ในแผนภาพ Amazon ECS (สไลด์ 37) องค์ประกอบ Service ทำหน้าที่ใด?","opts":[{"t":"รักษาจำนวน task ที่ต้องการให้รันต่อเนื่อง แทน task ที่ล้ม และเชื่อมกับ load balancer","why":"ถูก service scheduler รักษา desired count"},{"t":"เป็นแม่แบบ JSON ที่ระบุ image, CPU/memory และ port ของคอนเทนเนอร์","why":"ผิด นั่นคือ task definition"},{"t":"เก็บ container image ที่ build จาก Dockerfile เพื่อให้ compute ดึงไปใช้","why":"ผิด นั่นคือ Amazon ECR registry"},{"t":"รันงานครั้งเดียวแล้วจบ ไม่ถูกแทนที่เมื่อเกิดความล้มเหลวระหว่างรัน","why":"ผิด ลักษณะนี้คือ task แบบครั้งเดียว ไม่ใช่ service"}],"ans":0,"ref":"W13 · สไลด์ 37"},{"id":"w13-018","topic":"Containers (ECS/EKS/Fargate)","level":"know","story":"","q":"องค์ประกอบใดของ Amazon EKS ทำหน้าที่คล้าย task definition ของ Amazon ECS (สไลด์ 39)?","opts":[{"t":"ReplicaSet","why":"ผิด ReplicaSet รักษาจำนวน Pod ใกล้เคียงบทบาทของ ECS service"},{"t":"PodSpec","why":"ถูก ระบุ Pod และ image เทียบได้กับ task definition"},{"t":"Amazon ECR registry","why":"ผิด ECR เป็น registry เก็บ image ใช้ร่วมกันได้ทั้ง ECS และ EKS"},{"t":"Application Load Balancer","why":"ผิด ALB เป็นช่องทางรับ request ไม่ใช่แม่แบบการรัน"}],"ans":1,"ref":"W13 · สไลด์ 37, 39"},{"id":"w13-019","topic":"Containers (ECS/EKS/Fargate)","level":"apply","story":"","q":"เรียงขั้นตอนสร้างและ deploy คอนเทนเนอร์ตามสไลด์ 34 ให้ถูกต้อง","opts":[{"t":"Build image, เขียน Dockerfile, pull image, push ไป repository แล้ว deploy","why":"ผิด Dockerfile เป็นอินพุตของการ build ต้องมาก่อน และ push ต้องมาก่อน pull"},{"t":"Dockerfile, push, build image, pull จาก repository แล้ว deploy containers","why":"ผิด ยังไม่มี image ให้ push ก่อน build"},{"t":"Dockerfile, build image, deploy, push ไป repository แล้ว pull มาตรวจสอบ","why":"ผิด compute pull image จาก repository ก่อน deploy ไม่ใช่หลัง"},{"t":"Dockerfile, build image, push ไป repository, compute pull image แล้วรัน","why":"ถูก image ต้อง build และ push ไป registry ก่อนที่ compute จะ pull ไปรัน"}],"ans":3,"ref":"W13 · สไลด์ 34"},{"id":"w13-020","topic":"Containers (ECS/EKS/Fargate)","level":"apply","story":"","q":"ตามเกณฑ์สไลด์ 29 workload ใดเหมาะกับ AWS Lambda มากกว่าคอนเทนเนอร์?","opts":[{"t":"API ที่มีโหลดสูงสม่ำเสมอตลอด 24 ชั่วโมงและใช้ resource ค่อนข้างคงที่","why":"ผิด ภาระคงที่คุ้มกับคอนเทนเนอร์ที่ราคาคงที่ (เกณฑ์ Cost)"},{"t":"งานแปลงภาพขนาดเล็กที่ถูก trigger เป็นช่วง ๆ ปริมาณไม่แน่นอน รันไม่กี่วินาที","why":"ถูก ภาระไม่คงที่ได้ประโยชน์จากการคิดเงินตาม invocation/duration และไม่ชนข้อจำกัดของ Lambda"},{"t":"แอปเดิมจาก on-premises ที่ต้องย้ายขึ้นคลาวด์โดยไม่แก้โค้ดหรือ refactor","why":"ผิด คอนเทนเนอร์ย้ายแอปเดิมได้โดยไม่ re-architect"},{"t":"บริการที่ต้องใช้ memory 12 GB ต่อ instance ตลอดการประมวลผล","why":"ผิด เกิน 10 GB ซึ่งสไลด์ระบุว่าไม่เหมาะกับ Lambda"}],"ans":1,"ref":"W13 · สไลด์ 29"},{"id":"w13-021","topic":"Containers (ECS/EKS/Fargate)","level":"apply","story":"","q":"Lambda Managed Instances (LMI) ตั้ง timeout ผ่านคอนโซลเป็น 1 ชม. 30 นาที 0 วินาที (สไลด์ 31)\nเมื่อ function นี้ถูก invoke แบบ synchronous ผ่าน API Gateway เวลารันสูงสุดที่มีผลจริงคือเท่าใด?","opts":[{"t":"90 นาที","why":"ผิด 90 นาทีมีผลกับ async และ event source mapping เท่านั้น"},{"t":"60 นาที","why":"ผิด ไม่มีค่าดังกล่าวในสไลด์"},{"t":"15 นาที","why":"ถูก คอนโซลระบุว่า synchronous invokes มี maximum timeout 15 นาที แม้ตั้งค่ามากกว่า"},{"t":"ไม่มีเพดาน เพราะเป็น Managed Instances","why":"ผิด ช่วงที่ตั้งได้คือ 1 วินาทีถึง 90 นาที และ sync ถูกจำกัด 15 นาที"}],"ans":2,"ref":"W13 · สไลด์ 30, 31"},{"id":"w13-022","topic":"Containers (ECS/EKS/Fargate)","level":"scen","story":"ทีมมี Java application เดิม 3 ตัวบน EC2 ต้องการย้ายขึ้นสถาปัตยกรรมใหม่โดยไม่ refactor ทีมใหม่กับ container และ Kubernetes โหลดมีช่วงสูงต่ำ และไม่ต้องการ patch OS ของ node","q":"ตัวเลือกใดเหมาะที่สุด?","opts":[{"t":"เขียนใหม่ให้เป็น Lambda function ทั้งหมดเพื่อไม่ต้องดูแล node","why":"ผิด ต้อง refactor/re-architect ซึ่งขัดกับข้อกำหนด"},{"t":"รันบน Amazon EKS ด้วย EC2 node ที่ดูแล patch เองทั้งหมด","why":"ผิด ต้องเรียนรู้ Kubernetes และยัง patch OS ของ node เอง"},{"t":"แพ็กเป็น container image ใน ECR แล้วรันบน ECS ด้วย Fargate","why":"ถูก ย้ายโดยไม่ re-architect, ECS ง่ายสำหรับทีมใหม่ และ Fargate ตัดภาระ node (สไลด์ 29, 36, 40)"},{"t":"คงไว้บน EC2 เดิมแล้วเพิ่ม Auto Scaling group พร้อม load balancer","why":"ผิด ยังต้องจัดการ instance และ OS จึงไม่ตอบข้อกำหนดเรื่อง node"}],"ans":2,"ref":"W13 · สไลด์ 29, 33, 36, 40"},{"id":"w13-023","topic":"Containers (ECS/EKS/Fargate)","level":"scen","story":"API server บน ECS service ต้องมี task อย่างน้อย 8 ตัวตลอด 24 ชั่วโมง และช่วงเปิดลงทะเบียนต้อง scale ถึง 20 ตัว ทีมต้องการต้นทุนฐานที่คงที่ ขณะที่ส่วน burst ไม่อยากจัดการ node เพิ่ม และต้องการ ALB ตัวเดียวรับ traffic","q":"โครงสร้างใดสอดคล้องกับตัวอย่างสไลด์ 37–38?","opts":[{"t":"แยกเป็น 2 cluster และ 2 ALB ตามชนิด compute ที่ใช้ในแต่ละกลุ่ม task","why":"ผิด ไม่จำเป็นและเพิ่มความซับซ้อน ผสม compute ใน cluster เดียวได้"},{"t":"รันเป็น task ครั้งเดียว 20 ตัวทันทีโดยไม่ใช้ service scheduler ดูแลจำนวน","why":"ผิด ไม่มี service scheduler ดูแล desired count และเปลี่ยน task ที่ล้มเหลว"},{"t":"ย้ายทั้งหมดไปรันบน Lambda ที่ตั้ง timeout สูงสุด 15 นาทีต่อ invocation","why":"ผิด เปลี่ยนสถาปัตยกรรม ไม่ตรงโจทย์ที่ต้องการ task ต่อเนื่องราคาฐานคงที่"},{"t":"cluster เดียว: baseline task บน EC2, burst task บน Fargate หลัง ALB เดียว","why":"ถูก ECS ผสม EC2 และ Fargate ใน cluster เดียวได้ service autoscaling ปรับตามภาระ"}],"ans":3,"ref":"W13 · สไลด์ 29, 37, 38"},{"id":"w13-024","topic":"Step Functions","level":"know","story":"","q":"ข้อใดตรงกับ Standard Workflow ตามสไลด์ 45?","opts":[{"t":"รันได้ไม่เกิน 5 นาที และคิดเงินตามจำนวน request กับ duration","why":"ผิด นั่นคือ Express"},{"t":"รันนานได้สูงสุด 1 ปี มีประวัติครบในคอนโซล บันทึกทุกครั้งที่ state เปลี่ยน","why":"ถูก"},{"t":"ผลลัพธ์อยู่ใน CloudWatch Logs เป็นหลักและไม่บันทึกทุก transition","why":"ผิด นั่นคือ Express"},{"t":"รองรับเฉพาะ synchronous invocation โดยผู้เรียกรอจนจบ","why":"ผิด Standard ใช้แบบ asynchronous ส่วน Express รองรับทั้ง sync และ async"}],"ans":1,"ref":"W13 · สไลด์ 45"},{"id":"w13-025","topic":"Step Functions","level":"know","story":"","q":"ใน Amazon States Language ฟิลด์ StartAt ระบุอะไร?","opts":[{"t":"ARN ของ Lambda function ที่เรียกก่อน","why":"ผิด ARN อยู่ใน Resource ของ Task state"},{"t":"ชื่อ state สุดท้ายที่ทำให้ execution สิ้นสุด","why":"ผิด state สุดท้ายใช้ Type Succeed/Fail หรือ End"},{"t":"ชื่อ state แรกที่เริ่มรัน","why":"ถูก (สไลด์ 49)"},{"t":"เวลาที่ workflow เริ่มตามตารางเวลา","why":"ผิด ตารางเวลากำหนดภายนอก เช่น EventBridge ไม่ใช่ใน ASL"}],"ans":2,"ref":"W13 · สไลด์ 49"},{"id":"w13-026","topic":"Step Functions","level":"know","story":"","q":"Map state ทำหน้าที่ใดใน state machine?","opts":[{"t":"รัน branch ที่ต่างกันหลายชุดพร้อมกันแล้วรอจนครบทุก branch","why":"ผิด นั่นคือ Parallel state"},{"t":"เลือก state ถัดไปตามเงื่อนไขของค่าข้อมูลที่ส่งเข้ามา","why":"ผิด นั่นคือ Choice state"},{"t":"หน่วงเวลา workflow ตามระยะเวลาที่กำหนดก่อนไป state ถัดไป","why":"ผิด นั่นคือ Wait state"},{"t":"แยกประมวลผลแต่ละ record ในชุดข้อมูลด้วย workflow เดียวกันแบบขนาน","why":"ถูก (สไลด์ 47, 48)"}],"ans":3,"ref":"W13 · สไลด์ 47, 48"},{"id":"w13-027","topic":"Step Functions","level":"apply","story":"","q":"state machine มี state \"1 Task state\" ชนิด Task เรียก arn:aws:states:::lambda:invoke และ Next ชี้ไป \"2 Success state\" (Type Succeed) โดย state แรกไม่มี Retry หรือ Catch\nถ้า Lambda โยน error ที่ไม่ได้ถูกจัดการ ผลคืออะไร? (เพิ่มเติม)","opts":[{"t":"execution ไปที่ 2 Success state ตามค่าของ Next","why":"ผิด Next ใช้เมื่อ state สำเร็จเท่านั้น"},{"t":"execution ล้มเหลว โดยไม่ไปที่ 2 Success state","why":"ถูก ไม่มี Catch จึงไม่มีเส้นทางจัดการ error; Retry/Catch ต้องกำหนดใน state เอง"},{"t":"Step Functions retry ไม่จำกัดครั้งจนสำเร็จ","why":"ผิด การ retry ต้องกำหนดใน Retry พร้อมจำนวนครั้ง"},{"t":"workflow หยุดรอ callback token","why":"ผิด ต้องเลือก wait for callback ใน state จึงจะใช้ task token"}],"ans":1,"ref":"W13 · สไลด์ 44, 47, 49"},{"id":"w13-028","topic":"Step Functions","level":"apply","story":"","q":"ข้อความใดเกี่ยวกับ Standard และ Express ต่อไปนี้ผิด?","opts":[{"t":"Express บันทึกทุกครั้งที่ state เปลี่ยนและคิดเงินตามจำนวน state transition","why":"ผิดจริง Express ไม่บันทึกทุก transition และคิดตามจำนวน request กับ duration"},{"t":"Standard คิดเงินตามจำนวน state transition ที่เกิดขึ้นในแต่ละ execution","why":"ข้อความนี้ถูก (สไลด์ 45)"},{"t":"Express ส่งผลการรันไปเก็บที่ CloudWatch Logs แทนประวัติเต็มในคอนโซล","why":"ข้อความนี้ถูก (สไลด์ 45)"},{"t":"Express ใช้ได้ทั้งแบบ synchronous และ asynchronous ตามชนิดผู้เรียก","why":"ข้อความนี้ถูก (สไลด์ 45)"}],"ans":0,"ref":"W13 · สไลด์ 45"},{"id":"w13-029","topic":"Step Functions","level":"apply","story":"","q":"ใน state machine ลงทะเบียน (สไลด์ 51) ขั้นตรวจสอบสิทธิ์ใช้ Parallel state โดย Check prerequisites (Lambda) ใช้เวลาประมาณ 3 วินาที และ Get seat count (DynamoDB) ประมาณ 2 วินาที\nเวลาของ Parallel state นี้โดยประมาณเป็นเท่าใด เมื่อเทียบกับการรันตามลำดับ?","opts":[{"t":"ประมาณ 5 วินาที เพราะ Parallel state รัน branch ต่อกันตามลำดับก่อน","why":"ผิด branch ใน Parallel รันพร้อมกัน"},{"t":"ประมาณ 2 วินาที เพราะไปต่อทันทีเมื่อมี branch ใด branch หนึ่งเสร็จก่อน","why":"ผิด ต้องรอทุก branch ไม่ใช่เฉพาะตัวแรก"},{"t":"ประมาณ 1 วินาที เพราะ Step Functions แคชผลลัพธ์ของ Lambda ไว้ให้","why":"ผิด ไม่มีการแคชผลดังกล่าว"},{"t":"ประมาณ 3 วินาที เพราะรอทุก branch เสร็จ ส่วนแบบตามลำดับใช้ประมาณ 5 วินาที","why":"ถูก branch รันพร้อมกันและ state ถัดไปเริ่มเมื่อทุก branch เสร็จ"}],"ans":3,"ref":"W13 · สไลด์ 47, 51"},{"id":"w13-030","topic":"Step Functions","level":"scen","story":"ระบบสั่งซื้อให้ Lambda A เรียก Lambda B แล้ว B เรียก C โดยตรง แต่ละตัวมีโค้ด retry และ timeout เอง เมื่อ C ล้มเหลว ผลที่ A เขียนลงฐานข้อมูลยังค้างอยู่ และทีมไม่เห็นว่า request หนึ่งไปถึงขั้นใด","q":"แนวทางใดตรงกับปัญหา coordination ในสไลด์ 43–44 มากที่สุด?","opts":[{"t":"เพิ่มค่า timeout ของ Lambda ทุกตัวให้รอการเรียกต่อกันได้นานขึ้น","why":"ผิด ไม่แก้การชดเชยและการมองเห็น"},{"t":"ใส่ try/except และตรรกะ retry เพิ่มในโค้ดของทุก function","why":"ผิด เพิ่ม coupling และโค้ดควบคุมซ้ำในแต่ละบริการ"},{"t":"ใช้ Step Functions กำหนด Retry/Catch, state ชดเชย และดูสถานะ execution","why":"ถูก แยกตรรกะประสานงานออกจากบริการ จัดการ error และมองเห็นความคืบหน้าในที่เดียว"},{"t":"วาง SQS queue คั่นทุกคู่ function โดยไม่มีตัวประสานงานกลาง","why":"ผิด ไม่มีที่เก็บความคืบหน้าและ compensation ข้ามบริการ"}],"ans":2,"ref":"W13 · สไลด์ 43, 44, 65"},{"id":"w13-031","topic":"Step Functions","level":"scen","story":"Express workflow ลงทะเบียน มีนักศึกษา 2 คนกดจองที่นั่งสุดท้ายพร้อมกัน ทีมเกรงว่าจะจองเกิน และต้องการแจ้งผู้แพ้ว่าที่นั่งเต็ม","q":"ออกแบบ state อย่างไร?","opts":[{"t":"ตรวจ seat count ใน Parallel state แล้วเขียนค่าใหม่โดยไม่มีเงื่อนไข","why":"ผิด สองคนอ่านค่าเดียวกันแล้วเขียนได้ทั้งคู่ เกิด race condition"},{"t":"ใช้ DynamoDB conditional UpdateItem ตอน Reserve seat และ Catch ConditionalCheckFailed","why":"ถูก DynamoDB ตรวจเงื่อนไขแบบ atomic เหลือผู้ชนะเพียงคนเดียว (สไลด์ 51)"},{"t":"ตั้ง Retry บน ConditionalCheckFailed ให้ลองซ้ำจนกว่าจะเขียนสำเร็จ","why":"ผิด เงื่อนไขล้มเหลวซ้ำเมื่อที่นั่งเต็ม ไม่ควร retry"},{"t":"เปลี่ยนเป็น Standard workflow เพื่อให้ได้ exactly-once ทั้ง execution","why":"ผิด exactly-once ของ workflow ไม่ป้องกันการเขียนซ้อนกันที่ DynamoDB"}],"ans":1,"ref":"W13 · สไลด์ 45, 51"},{"id":"w13-032","topic":"API Gateway","level":"know","story":"","q":"API Gateway ชนิดใดที่ให้ latency และ cost ต่ำกว่า REST API และเหมาะกับ microservices ตามสไลด์ 56?","opts":[{"t":"REST API","why":"ผิด มีฟีเจอร์ครบกว่าแต่ราคาและ latency สูงกว่า"},{"t":"HTTP API","why":"ถูก เป็นทางเลือกเบาและถูกกว่า"},{"t":"WebSocket API","why":"ผิด เหมาะแอป real-time แบบ stateful"},{"t":"Lambda function URL","why":"ผิด ไม่ใช่ชนิด API ของ API Gateway"}],"ans":1,"ref":"W13 · สไลด์ 56"},{"id":"w13-033","topic":"API Gateway","level":"know","story":"","q":"VPC link ใน API Gateway ใช้เพื่ออะไร?","opts":[{"t":"เข้าถึง ALB/NLB ใน Customer VPC แบบ private โดยไม่เปิดสู่อินเทอร์เน็ต","why":"ถูก (สไลด์ 57, 60)"},{"t":"เชื่อม Lambda function เข้ากับ subnet ใน VPC ของผู้ใช้ผ่าน ENI","why":"ผิด ใช้ VPC configuration และ ENI ของ Lambda"},{"t":"เชื่อม API Gateway กับ DynamoDB table โดยตรงเพื่อไม่ต้องมี Lambda","why":"ผิด เป็น AWS service integration ไม่ต้องใช้ VPC link"},{"t":"เรียก HTTP endpoint สาธารณะนอก AWS ผ่าน HTTP proxy integration","why":"ผิด ใช้ HTTP proxy integration ไม่ต้องใช้ VPC link"}],"ans":0,"ref":"W13 · สไลด์ 57"},{"id":"w13-034","topic":"API Gateway","level":"know","story":"","q":"ตามสไลด์ 54 ข้อใดจัดอยู่ในประโยชน์กลุ่ม \"Protect microservices\"?","opts":[{"t":"ติดตามการใช้งานของแต่ละ client เพื่อใช้เรียกเก็บเงิน","why":"ผิด อยู่กลุ่ม Monetize API and track statistics"},{"t":"เชื่อมแอปที่เขียนหลายภาษาผ่าน contract มาตรฐานอย่าง HTTP","why":"ผิด อยู่กลุ่ม Standardize app communication"},{"t":"Throttle จำนวน request และตรวจรูปแบบ request ก่อนถึง backend","why":"ถูก"},{"t":"รายงานสถิติการใช้ต่อ client เพื่อวิเคราะห์การใช้งาน","why":"ผิด อยู่กลุ่ม Monetize API and track statistics"}],"ans":2,"ref":"W13 · สไลด์ 54"},{"id":"w13-035","topic":"API Gateway","level":"apply","story":"","q":"เว็บ public ต้องการให้ Lambda ถูกเรียกผ่าน HTTPS endpoint และต้องใช้ Cognito authorizer, throttling และ response caching\nทำไมควรใช้ API Gateway แทน Lambda function URL?","opts":[{"t":"function URL เรียกแบบ synchronous ไม่ได้ จึงรอผลกลับไปยัง client ไม่ได้","why":"ผิด function URL เรียกแบบ synchronous ได้"},{"t":"API Gateway เป็นช่องทางเดียวที่ใช้ invoke Lambda จากภายนอกได้","why":"ผิด ยังมี function URL และการ trigger จากบริการอื่น"},{"t":"function URL ใช้ได้เฉพาะ client ที่อยู่ใน VPC เดียวกับ function","why":"ผิด function URL เป็น HTTPS endpoint ที่เรียกได้โดยตรง"},{"t":"API Gateway มี authorization, throttling และ cache ส่วน function URL มีฟีเจอร์จัดการ API น้อยกว่า","why":"ถูก (สไลด์ 22, 55)"}],"ans":3,"ref":"W13 · สไลด์ 22, 55"},{"id":"w13-036","topic":"API Gateway","level":"scen","story":"HTTP API ของเว็บช็อปต้องเรียก Payment service บน ECS หลัง ALB ใน Customer VPC ฝ่ายความปลอดภัยไม่อนุญาตให้ ALB เปิดรับ traffic จากอินเทอร์เน็ต","q":"ควรออกแบบอย่างไร?","opts":[{"t":"เปลี่ยน ALB เป็น internet-facing แล้วจำกัดต้นทางด้วย security group","why":"ผิด ยังเปิดรับ traffic จากอินเทอร์เน็ต ขัดข้อกำหนด"},{"t":"ให้ API Gateway เรียก ALB ผ่าน HTTP proxy integration ไปยัง public endpoint","why":"ผิด เส้นทางยังเป็น public"},{"t":"ใช้ ALB แบบ internal ใน private subnet แล้วเรียกผ่าน VPC link จาก HTTP API","why":"ถูก traffic ไปถึง ALB โดยไม่ออกอินเทอร์เน็ต (สไลด์ 57, 60)"},{"t":"เพิ่ม NAT gateway ให้ API Gateway เพื่อเปิดทางเข้าสู่ subnet ภายใน","why":"ผิด NAT ใช้กับทราฟฟิกขาออกจาก subnet ไม่ใช่ทางเข้าของ API Gateway"}],"ans":2,"ref":"W13 · สไลด์ 57, 60"},{"id":"w13-037","topic":"API Gateway","level":"scen","story":"แอปแสดงราคาสดต้อง push ข้อมูลไปยัง client ประมาณ 10,000 ราย ที่เปิดหน้าเว็บค้างไว้ ปัจจุบันใช้ HTTP API และให้ client polling ทุก 1 วินาที ทำให้มี request จำนวนมากและข้อมูลมาช้า","q":"ควรเปลี่ยนเป็นอะไร?","opts":[{"t":"REST API พร้อมเปิด cache ที่ stage เพื่อลดภาระ backend","why":"ผิด ยังเป็น request/response แบบ stateless ต้อง polling"},{"t":"HTTP API พร้อมเพิ่ม throttle limit ให้รองรับ request มากขึ้น","why":"ผิด รองรับ request ได้มากขึ้นแต่ server ยัง push เองไม่ได้"},{"t":"WebSocket API ที่คง session สองทางและให้ server push ข้อมูลได้","why":"ถูก WebSocket เป็น stateful เหมาะแอป real-time (สไลด์ 56)"},{"t":"Lambda function URL ที่เรียกตรงเข้า function โดยไม่ผ่าน API Gateway","why":"ผิด เป็น request/response ไม่มี session ค้าง"}],"ans":2,"ref":"W13 · สไลด์ 56"},{"id":"w13-038","topic":"Well-Architected Serverless Lens","level":"apply","story":"","q":"ข้อใดจับคู่ best practice กับ pillar ได้ถูกต้อง?","opts":[{"t":"ใช้ DLQ เก็บ ตรวจ และ retry transaction ที่ล้มเหลว อยู่ใน Reliability","why":"ถูก อยู่ใต้ Failure management ของ Reliability (สไลด์ 65)"},{"t":"Encrypt data in transit and at rest อยู่ใน Cost Optimization","why":"ผิด อยู่ใน Security ใต้ Data protection"},{"t":"เลือกขนาด memory ของ Lambda เพื่อปรับ performance อยู่ใน Security","why":"ผิด อยู่ใน Performance Efficiency (Selection)"},{"t":"Control access to your serverless API อยู่ใน Reliability","why":"ผิด อยู่ใน Security ใต้ Identity and access management"}],"ans":0,"ref":"W13 · สไลด์ 64–69"},{"id":"w13-039","topic":"Well-Architected Serverless Lens","level":"apply","story":"","q":"การปรับข้อใดเป็นการ optimize Performance Efficiency ตาม Selection (สไลด์ 68)?","opts":[{"t":"ตั้ง DLQ ให้ asynchronous invocation เพื่อเก็บ event ที่ล้มเหลวไว้ตรวจสอบ","why":"ผิด เป็น Failure management ของ Reliability"},{"t":"เข้ารหัสข้อมูลที่เก็บใน S3 และ DynamoDB ด้วย AWS KMS key","why":"ผิด เป็น Data protection ของ Security"},{"t":"กำหนด IAM execution role แยกต่อ function ตามหลัก least privilege","why":"ผิด เป็น Identity and access management ของ Security"},{"t":"ทดสอบเพิ่ม Lambda memory เพราะ CPU scale ตาม memory อาจลดเวลารัน (เพิ่มเติม)","why":"ถูก เป็นการเลือกและปรับค่าให้เหมาะกับ workload"}],"ans":3,"ref":"W13 · สไลด์ 68"},{"id":"w13-040","topic":"Well-Architected Serverless Lens","level":"scen","story":"รีวิวความปลอดภัยพบว่า Lambda ทุกตัวใช้ IAM role เดียวที่มีสิทธิ์ AdministratorAccess แต่ API ผ่าน Cognito authorizer แล้ว และ DynamoDB เข้ารหัสแล้ว","q":"ข้อใดแก้ช่องว่างตาม best practice \"Control access to your serverless application\"?","opts":[{"t":"เพิ่ม Cognito user pool authorizer ที่ API Gateway อีกชั้นหนึ่ง","why":"ผิด ควบคุมผู้เรียก API ซึ่งทำไว้แล้ว ไม่ใช่สิทธิ์ของแอปที่เรียกออก"},{"t":"ให้แต่ละ function มี execution role ของตัวเอง ตามหลัก least privilege","why":"ถูก (สไลด์ 66)"},{"t":"เปิดการเข้ารหัส DynamoDB ด้วย KMS key ที่ลูกค้าจัดการเอง","why":"ผิด เป็น Data protection ซึ่งทำไว้แล้วและไม่จำกัดสิทธิ์"},{"t":"เพิ่ม throttling ที่ API Gateway เพื่อจำกัดอัตรา request ต่อวินาที","why":"ผิด จำกัดอัตรา request ไม่ได้จำกัดสิทธิ์ของ function"}],"ans":1,"ref":"W13 · สไลด์ 66"},{"id":"w13-041","topic":"Well-Architected Serverless Lens","level":"scen","story":"Lambda ดึงข้อความจาก SQS queue ผ่าน event source mapping มี poison message หนึ่งข้อความทำให้ batch ล้มเหลวซ้ำ ทีมต้องการเก็บข้อความไว้ตรวจสอบและ retry ภายหลัง","q":"ควรตั้งค่าอย่างไร? (เพิ่มเติม)","opts":[{"t":"ตั้ง DLQ ใน asynchronous configuration ของ Lambda function","why":"ผิด ใช้กับ async invocation ไม่ใช่ SQS event source mapping"},{"t":"ตั้ง redrive policy พร้อม maxReceiveCount บน source SQS queue ไปยัง DLQ","why":"ถูก สอดคล้อง DLQ ใน Failure management (สไลด์ 65)"},{"t":"ลบข้อความที่ error ทิ้งใน function เพื่อให้ batch ผ่านได้","why":"ผิด ข้อมูลสูญหายและตรวจสอบสาเหตุไม่ได้"},{"t":"เพิ่ม timeout ของ function เป็น 15 นาทีเพื่อให้ประมวลผลได้นานขึ้น","why":"ผิด ไม่ช่วยให้ข้อความที่มีปัญหาถูกเก็บแยก"}],"ans":1,"ref":"W13 · สไลด์ 24, 65"},{"id":"w13-042","topic":"Well-Architected Serverless Lens","level":"scen","story":"เว็บช็อปใช้ REST API ของ API Gateway สำหรับ cart microservice ที่เรียก Lambda เท่านั้น ไม่ใช้ usage plan, payload validation, private endpoint หรือ resource policy และต้องการลดต้นทุนกับ latency","q":"ข้อใดสอดคล้อง Cost Optimization?","opts":[{"t":"เปลี่ยนเป็น HTTP API ที่ถูกกว่าและ latency ต่ำกว่า","why":"ถูก (สไลด์ 56, 69)"},{"t":"เปลี่ยนเป็น WebSocket API เพื่อให้คง session กับ client","why":"ผิด สำหรับแอป real-time ที่ต้อง session ไม่เกี่ยวกับ request/response"},{"t":"คง REST API ไว้และเพิ่ม memory ของ Lambda เป็นสองเท่า","why":"ผิด ไม่ลดค่า API Gateway"},{"t":"ย้ายไปใช้ Lambda function URL ร่วมกับ usage plan ของ API Gateway","why":"ผิด function URL ไม่มี usage plan"}],"ans":0,"ref":"W13 · สไลด์ 56, 69"}],"w14":[{"id":"w14-001","topic":"Pricing และการคิดเงิน","level":"know","story":"","q":"AWS คิดค่าใช้จ่ายจาก cost driver หลักสามปัจจัยใด?","opts":[{"t":"Compute, Storage, จำนวน Region ที่เปิดใช้","why":"จำนวน Region ไม่ใช่ cost driver; ราคาต่างกันตาม Region แต่ไม่คิดเงินตามจำนวน Region"},{"t":"Compute, Storage, Data transfer","why":"ตรงกับสไลด์ 3: compute ต่อชั่วโมง/วินาทีตาม instance type, storage ต่อ GB, data transfer ต่อ GB"},{"t":"Compute, Networking hardware, Software license","why":"AWS ไม่คิดค่า networking hardware แยก; hardware เป็นความรับผิดชอบของ AWS"},{"t":"Storage, จำนวน API request, Support plan","why":"เป็นรายการค่าใช้จ่ายบางส่วนของบางบริการ ไม่ใช่สามปัจจัยหลักที่สไลด์ระบุ และไม่มี compute"}],"ans":1,"ref":"W14 · สไลด์ 3"},{"id":"w14-002","topic":"Pricing และการคิดเงิน","level":"know","story":"","q":"ตามสไลด์ 7 การส่งข้อมูลระหว่าง Availability Zone ใน Region เดียวกันถูกคิดเงินอย่างไร?","opts":[{"t":"ฟรี เพราะอยู่ใน Region เดียวกันและใช้ private IP ร่วมกัน","why":"ฟรีเฉพาะภายใน AZ เดียวกันผ่าน private IP ข้าม AZ ยังคิดเงิน"},{"t":"$0.01/GB ทั้งขาออกและขาเข้า","why":"สไลด์แสดง $0.01/GB out และ $0.01/GB in ที่ลูกศรแดงระหว่าง AZ"},{"t":"$0.01/GB เฉพาะฝั่ง out เท่านั้น ส่วนฝั่ง in ไม่คิดเงินเพิ่ม","why":"คิดทั้งสองทิศทาง ไม่ใช่เฉพาะ out"},{"t":"$0.02/GB เฉพาะฝั่ง out เท่านั้น ส่วนฝั่ง in ไม่คิดเงินเพิ่ม","why":"$0.02/GB out เป็นอัตราข้าม Region ในภาพ ไม่ใช่ข้าม AZ"}],"ans":1,"ref":"W14 · สไลด์ 7–8"},{"id":"w14-003","topic":"Pricing และการคิดเงิน","level":"know","story":"","q":"ข้อใดระบุส่วนลดสูงสุดและเงื่อนไขการเรียกคืนของ Spot Instances ได้ตรงสไลด์ 13–14?","opts":[{"t":"สูงสุด 72% และเรียกคืนไม่ได้ตลอดสัญญา 1 หรือ 3 ปี","why":"72% เป็นของ Savings Plans/RI ที่ AWS เรียกคืนไม่ได้ ไม่ใช่ Spot"},{"t":"สูงสุด 90% และเรียกคืนไม่ได้เมื่อประมูลราคาสูงพอ","why":"สไลด์ไม่ได้ระบุกลไกนี้ Spot เรียกคืนได้เสมอเมื่อ AWS ต้องการ capacity"},{"t":"สูงสุด 75% และเรียกคืนได้โดยแจ้ง 2 ชั่วโมง","why":"เวลาแจ้งเตือนคือ 2 นาที และ 75% เป็นตัวเลขของ RI ในสไลด์ 12 ไม่ใช่ Spot"},{"t":"สูงสุด 90% และ AWS เรียกคืนได้โดยแจ้งล่วงหน้า 2 นาที","why":"ตรงกับตารางสไลด์ 13 และ 14: Spot ใช้ capacity ส่วนเกินที่ถูกเรียกคืนได้"}],"ans":3,"ref":"W14 · สไลด์ 13–14"},{"id":"w14-004","topic":"Pricing และการคิดเงิน","level":"know","story":"","q":"ข้อใดเป็นบริการที่ตัวมันเองไม่มีค่าใช้จ่าย (แต่ทรัพยากรที่ถูกสร้างอาจมีค่าใช้จ่าย)?","opts":[{"t":"AWS CloudFormation","why":"สไลด์ 20 ระบุว่า CloudFormation ไม่คิดเงิน แต่ resource ใน stack คิดเงินตามปกติ"},{"t":"NAT gateway","why":"คิดทั้งรายชั่วโมงและต่อ GB ที่ประมวลผล (สไลด์ 21)"},{"t":"Application Load Balancer","why":"มีค่าพื้นฐานราว $16/เดือนแม้ยังไม่มีทราฟฟิก (สไลด์ 21)"},{"t":"Amazon CloudWatch Logs","why":"คิดต่อ GB ที่ ingest และเก็บ (สไลด์ 21)"}],"ans":0,"ref":"W14 · สไลด์ 20–21"},{"id":"w14-005","topic":"Pricing และการคิดเงิน","level":"apply","story":"","q":"NAT gateway 1 ตัวรันครบ 720 ชั่วโมงในเดือน และประมวลผลข้อมูล 1,000 GB ราคาตามสไลด์ 21 ($0.045/ชั่วโมง + $0.045/GB processed) ค่า NAT gateway (ไม่รวม data transfer) ประมาณเท่าใด?","opts":[{"t":"$45.00","why":"นับเฉพาะค่า per GB processed ลืมค่ารายชั่วโมงที่เกิดตราบที่ NAT ยังมีอยู่"},{"t":"$32.40","why":"นับเฉพาะค่ารายชั่วโมง ลืมค่า per GB ที่ประมวลผล"},{"t":"$122.40","why":"บวก $45.00 ซ้ำอีกรอบ ค่า data transfer เป็นรายการแยกและโจทย์ระบุว่าไม่รวม"},{"t":"$77.40","why":"720 x 0.045 = $32.40 (รายชั่วโมง) + 1,000 x 0.045 = $45.00 (processed) = $77.40"}],"ans":3,"ref":"W14 · สไลด์ 21"},{"id":"w14-006","topic":"Pricing และการคิดเงิน","level":"apply","story":"","q":"ทีมมี baseline compute ที่ใช้เงินคงที่ราว $2/ชั่วโมงตลอด 3 ปี แต่คาดว่าจะเปลี่ยน instance family และขนาดหลายครั้งระหว่างปี ตัวเลือกใดให้ส่วนลดโดยไม่ผูกกับ instance type เดียว?","opts":[{"t":"Reserved Instances แบบ Standard","why":"ผูกกับคุณลักษณะของ instance จึงเหมาะกับระบบที่ไม่เปลี่ยนขนาด"},{"t":"Spot Instances","why":"ไม่ผูกพันก็จริง แต่ AWS เรียกคืนได้ ไม่เหมาะกับ baseline ที่ต้องรันตลอด"},{"t":"Savings Plans","why":"ผูกพันเป็นจำนวนเงิน $ ต่อชั่วโมง ไม่ผูกกับ instance type โดยตรง จึงรองรับการเปลี่ยนขนาด/family (สไลด์ 13)"},{"t":"On-Demand","why":"ยืดหยุ่นเต็มที่แต่ไม่มีส่วนลด จึงจ่ายแพงสุดต่อหน่วยสำหรับโหลดคงที่"}],"ans":2,"ref":"W14 · สไลด์ 12–13"},{"id":"w14-007","topic":"Pricing และการคิดเงิน","level":"apply","story":"","q":"แอปใน AZ-a ส่งข้อมูล 500 GB ไปยังฐานข้อมูลใน AZ-b ใน VPC เดียวกันตลอดเดือน (ทิศทางเดียว) ค่า data transfer ข้าม AZ ตามสไลด์ 7 ประมาณเท่าใด?","opts":[{"t":"$5.00","why":"นับเพียงทิศทางเดียว (out) แต่สไลด์ระบุว่าคิดทั้ง out และ in"},{"t":"$0.00","why":"ข้าม AZ ไม่ฟรี มีเฉพาะภายใน AZ เดียวกันผ่าน private IP ที่ฟรี"},{"t":"$10.00","why":"$0.01/GB out ที่ AZ-a + $0.01/GB in ที่ AZ-b = $0.02/GB; 500 x 0.02 = $10"},{"t":"$20.00","why":"คูณสองซ้ำเหมือนมีทราฟฟิกสองทิศทาง ทั้งที่โจทย์ส่งทิศทางเดียว 500 GB"}],"ans":2,"ref":"W14 · สไลด์ 7–8"},{"id":"w14-008","topic":"Pricing และการคิดเงิน","level":"scen","story":"ระบบ RegisterFast มี web tier ที่รันตลอดปีด้วย c7i.xlarge 4 ตัวในโหลดคงที่ และมี worker ที่ประมวลผลวิดีโอจาก SQS วันละ 6 ชั่วโมง งานทุกชิ้น idempotent และ retry ได้ worker ไม่เก็บ state ทีมต้องการลดต้นทุนสูงสุดโดยไม่เสี่ยงให้ระบบหลักหยุด","q":"การเลือกรูปแบบราคาแบบใดเหมาะสมที่สุด?","opts":[{"t":"ทุก instance รวม worker ใช้ Reserved แบบ 3 ปีเพื่อรับส่วนลดสูงสุด","why":"worker ใช้เพียงวันละ 6 ชั่วโมง การผูกพัน 24/7 จ่ายเกินสำหรับช่วงที่ไม่ได้รัน"},{"t":"ทุก instance รวม web tier ใช้ Spot เพื่อให้ได้ส่วนลดสูงสุด 90%","why":"web tier ถูกเรียกคืนได้พร้อมกันทำให้ระบบหลักหยุด ไม่ตรงเงื่อนไข stateless ที่ถูกแทนที่ได้ทันที"},{"t":"ทุก instance ใช้ On-Demand ทั้งหมดเพื่อคงความยืดหยุ่นเต็มที่","why":"ปลอดภัยแต่แพงสุด ทั้งที่มีโหลดคงที่และงานที่ขัดจังหวะได้ซึ่งมีส่วนลดสูง"},{"t":"Web tier ใช้ Savings Plans ส่วน worker ใช้ Spot หลาย instance type","why":"โหลดคงที่คุ้มกับ commitment ส่วน worker stateless + visibility timeout ของ SQS ทำให้ถูกเรียกคืนได้ปลอดภัย"}],"ans":3,"ref":"W14 · สไลด์ 12–14"},{"id":"w14-009","topic":"Pricing และการคิดเงิน","level":"scen","story":"หลังทีมเทสต์ terminate EC2 และลบ ASG ในบัญชี dev ครบแล้ว บิลของบัญชีนั้นยังเพิ่มขึ้นทุกเดือน Cost Explorer แสดงว่าก้อนที่โตเป็น EBS snapshot และ CloudWatch Logs ส่วน compute เป็นศูนย์","q":"ข้อใดแก้ต้นเหตุของค่าใช้จ่ายที่เพิ่มสะสมนี้?","opts":[{"t":"ตั้ง AWS Budgets แจ้งเตือนที่ 80% ของงบรายเดือนของบัญชี dev","why":"Budgets แค่เตือน ไม่หยุดหรือลบทรัพยากร ค่าเก็บยังสะสมต่อ"},{"t":"ซื้อ Compute Savings Plans แบบ 3 ปีเพื่อลดต้นทุนของบัญชีนี้","why":"Compute Savings Plans ลดค่า compute ไม่ลดค่า storage ของ snapshot และ log"},{"t":"ตั้ง retention ให้ log group และลบ snapshot/volume ที่ไม่ใช้","why":"ทรัพยากรที่มี lifecycle แยกไม่ถูกลบตาม instance และ log group มี retention เริ่มต้นไม่หมดอายุ (สไลด์ 21)"},{"t":"เปิด consolidated billing ใน Organizations เพื่อรวมบิลทุกบัญชี","why":"รวมบิลและแชร์ส่วนลดปริมาณ แต่ไม่ลดหรือลบทรัพยากรที่ยังเก็บอยู่"}],"ans":2,"ref":"W14 · สไลด์ 21"},{"id":"w14-010","topic":"TCO","level":"know","story":"","q":"TCO (Total Cost of Ownership) ตามสไลด์ 27 หมายถึงอะไร?","opts":[{"t":"ราคาซื้อฮาร์ดแวร์และ license ครั้งแรกของระบบเท่านั้น","why":"เป็นเพียงต้นทุนทางตรงส่วนหนึ่ง TCO ต้องรวมแรงงาน พื้นที่ ไฟ ระบายความร้อน"},{"t":"ค่าบริการคลาวด์ที่ปรากฏในใบแจ้งหนี้รายเดือนล่าสุดเท่านั้น","why":"เป็นตัวเลขของฝั่งคลาวด์ช่วงเดียว ไม่ใช่การประเมินตลอดอายุและไม่ครอบคลุมฝั่ง on-premises"},{"t":"ประมาณต้นทุนทางตรงและทางอ้อมของระบบตลอดอายุการใช้งาน","why":"ใช้เปรียบเทียบ on-premises กับ AWS และสร้าง business case"},{"t":"ผลตอบแทนการลงทุน (ROI) ที่เกิดขึ้นหลังย้ายระบบเสร็จแล้ว","why":"ROI เป็นผลตอบแทนเทียบเงินลงทุน คนละตัวชี้วัดกับการรวมต้นทุนเป็น TCO"}],"ans":2,"ref":"W14 · สไลด์ 27"},{"id":"w14-011","topic":"TCO","level":"know","story":"","q":"ใน Case B (คลังวิดีโอ 400 TB ส่งออก 150 TB/เดือน) แถวใดทำให้คลาวด์แพงกว่า on-premises มากที่สุด?","opts":[{"t":"Server ($33k บนคลาวด์เทียบกับ $156k บน on-premises ตามตาราง)","why":"ฝั่งคลาวด์ถูกกว่า on-premises ในแถวนี้ จึงไม่ใช่สาเหตุที่คลาวด์แพงกว่า"},{"t":"Network ($408k เทียบ $76k) จาก data transfer out","why":"Network เป็น 53% ของบิลคลาวด์ ($408k จาก $773k) เพราะ egress คิดต่อ GB ขณะที่ on-prem ใช้ลิงก์ flat-rate"},{"t":"Storage ($224k บนคลาวด์เทียบกับ $187k บน on-premises ตามตาราง)","why":"คลาวด์แพงกว่าจริงแต่ส่วนต่างเพียง $37k น้อยกว่าส่วนต่าง Network มาก"},{"t":"IT labor ($108k บนคลาวด์เทียบกับ $90k บน on-premises ตามตาราง)","why":"ส่วนต่าง $18k เล็กที่สุดในกลุ่มที่คลาวด์แพงกว่า"}],"ans":1,"ref":"W14 · สไลด์ 32"},{"id":"w14-012","topic":"TCO","level":"apply","story":"","q":"ข้อใดเป็น soft benefit (วัดเป็นเงินยากกว่า) ของการย้ายขึ้นคลาวด์ตามสไลด์ 39?","opts":[{"t":"ประสิทธิภาพของนักพัฒนาเพิ่มขึ้น","why":"จัดเป็น soft benefit เพราะประเมินเป็นเงินตรง ๆ ได้ยาก มักใช้ประกอบ business case"},{"t":"จำนวนบุคลากรปฏิบัติการลดลง","why":"hard benefit วัดเป็นเงินเงินเดือนได้โดยตรง"},{"t":"ไม่ต้องซื้อฮาร์ดแวร์และซอฟต์แวร์ล่วงหน้า (capex)","why":"hard benefit ใส่ลงสเปรดชีต TCO ได้"},{"t":"ต้นทุน backup และ disaster recovery ลดลง","why":"hard benefit เป็นรายการต้นทุนปฏิบัติการที่คำนวณได้"}],"ans":0,"ref":"W14 · สไลด์ 39"},{"id":"w14-013","topic":"TCO","level":"apply","story":"","q":"ทีมเปรียบเทียบ TCO 3 ปี โดยฝั่งคลาวด์นับเฉพาะ instance และ storage ส่วนฝั่ง on-premises นับครบ Server, Storage, Network, IT labor ข้อใดอธิบายความผิดพลาดของวิธีนี้ถูกต้อง?","opts":[{"t":"ละเมิดกฎ 2: ห้ามปัดตัวเลขเป็นหลักพันเพราะทำให้ข้อมูลคลาดเคลื่อน","why":"กฎ 2 ให้ปัดเป็น $1,000 เพื่อไม่แสดงความแม่นยำเกินจริง ไม่ใช่ห้ามปัด"},{"t":"ละเมิดกฎ 1: ฝั่งคลาวด์ขาดคู่ตรงข้าม เช่น NAT, public IPv4, egress, support, migration","why":"ฝั่งคลาวด์จึงต่ำกว่าจริง ทำให้ข้อสรุปเอนเอียงไปทางคลาวด์"},{"t":"ใช้สี่แถวเดียวกันทั้งสองฝั่ง ซึ่งทำให้เปรียบเทียบกันโดยตรงไม่ได้","why":"ใช้สี่แถวเดียวกันคือแนวทางที่ถูก ปัญหาอยู่ที่รายการภายในแถวของฝั่งคลาวด์ที่ขาด"},{"t":"ไม่ได้ระบุอายุเครื่องเป็น 3 ปี จึงไม่สามารถสรุปผลเปรียบเทียบได้","why":"โจทย์ระบุ 3 ปีแล้ว และสมมติฐานไม่ใช่จุดที่ผิดในโจทย์นี้"}],"ans":1,"ref":"W14 · สไลด์ 30"},{"id":"w14-014","topic":"TCO","level":"scen","story":"สื่อแห่งหนึ่งมี data centre ของตนเอง ทีม ops ที่จ่ายแล้ว และ campus link แบบ flat-rate ต้องสตรีมวิดีโอ 200 TB/เดือนแบบคงที่ 24/7 โดยคาดว่าโหลดไม่เปลี่ยนตลอด 5 ปี ฝ่ายบริหารเห็นว่า compute บนคลาวด์ถูกกว่า on-premises มาก","q":"ข้อสรุปเชิง TCO ที่สมเหตุสมผลที่สุดคือข้อใด?","opts":[{"t":"ย้ายทั้งหมดขึ้นคลาวด์เพราะแถว Server บนคลาวด์ถูกกว่ามาก","why":"ดูแถวเดียวไม่พอ ใน Case B ส่วนต่างที่ Network ล้าง saving ของ Server"},{"t":"ย้ายขึ้นคลาวด์แล้วซื้อ Savings Plans เพื่อลดค่า egress ต่อ GB","why":"Savings Plans ลดค่า compute เท่านั้น ไม่ลดค่า data transfer out ต่อ GB"},{"t":"ย้ายขึ้นคลาวด์เพราะ soft benefit ย่อมมีน้ำหนักเหนือกว่าเสมอ","why":"soft benefit ไม่ใช่ตัวตัดสินเสมอ และโหลดคงที่ทำให้ค่า option ในการเปลี่ยนใจมีค่าน้อย"},{"t":"ประเมิน egress 200 TB/เดือนด้วย: โหลดคงที่ข้อมูลออกมาก จึงเอนไปทาง on-premises","why":"ตามสไลด์ 33 โหลดคงที่ + ข้อมูลออกมาก + มีโครงสร้างพื้นฐานจ่ายแล้ว ชี้ไป on-premises ตามบทเรียน Case B"}],"ans":3,"ref":"W14 · สไลด์ 32–34"},{"id":"w14-015","topic":"TCO","level":"scen","story":"ระบบลงทะเบียนมีเว็บเซิร์ฟเวอร์ 2 ตัวเกือบทั้งปี แต่ต้องการ 40 ตัวที่ 09:00 เป็นเวลา 6 สัปดาห์ต่อปี ฝ่ายไอทีเสนอซื้อ on-premises host ขนาด peak ผลวิเคราะห์ Case A ชี้ว่าคลาวด์ถูกกว่า 69%","q":"ปัจจัยใดอธิบายผลนี้ได้ตรงที่สุด?","opts":[{"t":"Utilization ต่ำ: on-prem จ่ายทั้งปีเพื่อรอง peak 6 สัปดาห์ ส่วนคลาวด์จ่ายเฉพาะช่วง peak","why":"ความต่างระหว่างค่าเฉลี่ยกับ peak กำหนดผล (สไลด์ 31)"},{"t":"ค่าแรงบนคลาวด์เป็นศูนย์ จึงต้นทุนรวมต่ำกว่า on-premises มาก","why":"Case A ยังนับ 0.2 sysadmin บนคลาวด์ แรงงานลดลงแต่ไม่เป็นศูนย์"},{"t":"ราคา instance-hour ของ AWS ต่ำกว่าต้นทุนฮาร์ดแวร์ต่อชั่วโมงเสมอ","why":"ไม่จริงเสมอ Case B แสดงว่าโหลดคงที่ทำให้ on-premises ชนะ ตัวแปรคือรูปแบบโหลด"},{"t":"Data transfer เข้า AWS ฟรี จึงตัดต้นทุน network ออกจากบิลทั้งหมด","why":"ฝั่งคลาวด์ยังมีค่า network ($14k) จาก ALB, NAT ฯลฯ และไม่ใช่ตัวกำหนดผลของ Case A"}],"ans":0,"ref":"W14 · สไลด์ 31, 33"},{"id":"w14-016","topic":"AWS Organizations / SCP / Landing Zone","level":"know","story":"","q":"ขนาดสูงสุดของเอกสาร SCP หนึ่งฉบับตามสไลด์ 57 คือเท่าใด?","opts":[{"t":"2,048 bytes","why":"ต่ำกว่าค่าจริง ไม่ตรงกับตารางสไลด์"},{"t":"10,240 bytes","why":"สูงกว่าค่าจริงสองเท่า ไม่ตรงกับตารางสไลด์"},{"t":"5,120 bytes","why":"ค่าจำกัดจากตาราง Limits of AWS Organizations จึงต้องเขียน SCP กระชับ"},{"t":"1,000 bytes","why":"1,000 เป็นจำนวน OU และ policies สูงสุด ไม่ใช่ขนาดเอกสาร SCP"}],"ans":2,"ref":"W14 · สไลด์ 57"},{"id":"w14-017","topic":"AWS Organizations / SCP / Landing Zone","level":"know","story":"","q":"ใน AWS Organizations ข้อใดถูกต้องเกี่ยวกับ OU และ root ตามสไลด์ 51 และ 57?","opts":[{"t":"มี 1 root และซ้อน OU ใต้ root ได้สูงสุด 5 ระดับ","why":"ตรงกับตาราง limits; policy ที่ attach ที่โหนดใดมีผลกับโหนดใต้มัน"},{"t":"มีได้หลาย root และซ้อน OU ได้ลึกไม่จำกัดตามต้องการ","why":"จำนวน root คือ 1 และความลึกจำกัด 5 ระดับ"},{"t":"มี 1 root และซ้อน OU ได้เพียง 2 ระดับเท่านั้นต่อ root","why":"ความลึกสูงสุดคือ 5 ระดับ ไม่ใช่ 2"},{"t":"มีได้ 5 root ต่อ organization เพื่อแยกสภาพแวดล้อม Prod/Dev","why":"5 คือความลึกของ OU ไม่ใช่จำนวน root การแยกทำด้วย OU ใต้ root เดียว"}],"ans":0,"ref":"W14 · สไลด์ 51, 57"},{"id":"w14-018","topic":"AWS Organizations / SCP / Landing Zone","level":"know","story":"","q":"ใน Landing Zone ควบคุมแบบ Detective (ตรวจพบหลังเกิดเหตุ) ทำงานด้วยกลไกใด?","opts":[{"t":"Service control policy (SCP)","why":"เป็น Preventive บล็อก action ก่อนเกิด"},{"t":"กฎ AWS Config","why":"สไลด์ 60: Detective = AWS Config rules ตรวจพบการละเมิดหลังเกิด"},{"t":"การตรวจ stack ก่อน deploy ระดับ CloudFormation","why":"เป็น Proactive ตรวจก่อน provision"},{"t":"Account Factory","why":"เป็นกลไกสร้างบัญชีที่ต่อ logging/guardrails ไม่ใช่ชนิดของ control"}],"ans":1,"ref":"W14 · สไลด์ 60"},{"id":"w14-019","topic":"AWS Organizations / SCP / Landing Zone","level":"know","story":"","q":"ประโยชน์ของ consolidated billing ใน AWS Organizations ตามสไลด์ 52 คือข้อใด?","opts":[{"t":"รวม service quota ของทุกบัญชีเป็นก้อนเดียวใช้ร่วมกันทั้ง organization","why":"quota เป็นรายบัญชี (สไลด์ 48–49) ไม่ถูกรวม"},{"t":"รวมบิลทุก member account ที่ management account และแชร์ส่วนลดปริมาณกับ Savings Plans","why":"ปริมาณรวมไปถึง tier ราคาต่ำกว่าได้ ขณะที่ยังดูค่าใช้จ่ายแยกบัญชีได้"},{"t":"IAM user ของ management account ใช้ได้ในทุก member account อัตโนมัติ","why":"consolidated billing เกี่ยวกับบิล ไม่ใช่การแชร์ IAM identity"},{"t":"SCP ของ management account บังคับ workload ที่รันในบัญชีนั้นด้วย","why":"SCP ไม่จำกัด management account"}],"ans":1,"ref":"W14 · สไลด์ 52"},{"id":"w14-020","topic":"AWS Organizations / SCP / Landing Zone","level":"apply","story":"","q":"ผู้ใช้ในบัญชีมี IAM policy AdministratorAccess แต่ SCP ที่มีผลกับบัญชีนั้นอนุญาตเฉพาะ ec2:* และ rds:* ผู้ใช้ทำสิ่งใดได้?","opts":[{"t":"ทำได้ทั้ง ec2:RunInstances และ s3:PutObject เพราะเป็น Administrator","why":"IAM Administrator ไม่ override SCP ที่ไม่อนุญาต action นั้น"},{"t":"ทำไม่ได้ทั้งสองอย่าง เพราะ SCP ไม่ได้ให้สิทธิ์แก่ผู้ใช้","why":"SCP ไม่ได้ให้สิทธิ์แต่กำหนดเพดาน action ที่ IAM อนุญาตและอยู่ในเพดานยังทำได้"},{"t":"เรียก ec2:RunInstances ได้ แต่ s3:PutObject ไม่ได้","why":"effective permission = IAM ∩ SCP; ec2 อยู่ในทั้งสอง ส่วน s3 ไม่อยู่ใน SCP"},{"t":"เรียก s3:PutObject ได้ แต่ ec2:RunInstances ถูกปฏิเสธ","why":"กลับด้าน: ec2 ถูก SCP อนุญาต s3 ไม่ถูกอนุญาต"}],"ans":2,"ref":"W14 · สไลด์ 54–55"},{"id":"w14-021","topic":"AWS Organizations / SCP / Landing Zone","level":"apply","story":"","q":"องค์กรผูก SCP Deny ec2:* ที่ root ของ organization แล้วผู้ดูแลต้องการรัน EC2 ทดสอบ บัญชีใดยังรัน EC2 ได้ (ถ้า IAM อนุญาต)?","opts":[{"t":"บัญชีใน Security OU เพราะเป็น core account","why":"policy ที่ root สืบทอดถึงทุกบัญชีใต้ root รวม Security OU"},{"t":"บัญชีที่มี IAM AdministratorAccess","why":"IAM ให้สิทธิ์ไม่ override Deny ใน SCP"},{"t":"บัญชีใน Sandbox OU ที่ซ้อน OU ลึก 5 ระดับ","why":"การสืบทอดครอบคลุมทุกระดับใต้ root ความลึกไม่ทำให้พ้นการจำกัด"},{"t":"Management account","why":"SCP ไม่จำกัด management account แต่จำกัด member account ทุกบัญชีใต้ root"}],"ans":3,"ref":"W14 · สไลด์ 52, 55"},{"id":"w14-022","topic":"AWS Organizations / SCP / Landing Zone","level":"scen","story":"องค์กรมี 100 บัญชีและทีมใหม่ขอบัญชีทุกสัปดาห์ ข้อกำหนดคือ ทุกบัญชีต้องส่ง log เข้าบัญชีกลาง ห้ามปิด CloudTrail และห้ามใช้ Region นอกรายการ โดยไม่ต้องให้แต่ละทีมตั้งค่าเอง","q":"ควรออกแบบอย่างไร?","opts":[{"t":"ส่ง checklist ให้แต่ละทีมตั้งค่า logging และ policy ของบัญชีตนเอง","why":"พึ่งวินัยรายคน ไม่ใช่ design บัญชีเสี่ยงหลุดมาตรฐานเมื่อมี 100 บัญชี"},{"t":"ใช้บัญชีเดียวและบังคับมาตรฐานด้วย tag กับ IAM policy ทั้งหมด","why":"tag และ IAM เป็นข้อบังคับระดับธรรมเนียม ไม่แยก quota/blast radius และ IAM ผิดตัวเดียวทะลุได้"},{"t":"ตั้ง Landing Zone ด้วย Control Tower พร้อม SCP ที่ OU และ Account Factory","why":"ตัดสินใจครั้งเดียวแล้วสืบทอด บัญชีใหม่ compliant ตั้งแต่เกิด (สไลด์ 60)"},{"t":"ตั้ง Budget ให้ทุกบัญชีเพื่อแจ้งเตือนเมื่อมีการละเมิดข้อกำหนด","why":"Budgets เตือนเรื่องค่าใช้จ่าย ไม่บล็อก action หรือบังคับ logging"}],"ans":2,"ref":"W14 · สไลด์ 49, 59–61"},{"id":"w14-023","topic":"AWS Organizations / SCP / Landing Zone","level":"scen","story":"ผู้ดูแลเขียน SCP deny Region นอก us-east-1 แล้วผูกที่ root ทันทีโดยไม่ทดสอบ ผลคือ pipeline ใน member account ที่ deploy ข้าม Region ล้มทุกบัญชี ขณะที่ทดสอบจาก management account แล้วไม่พบปัญหา","q":"ขั้นตอนใดควรทำเพื่อไม่ให้เกิดเหตุนี้?","opts":[{"t":"ผูก SCP กับ OU ทดลองและทดสอบจาก member account ก่อน","why":"SCP ผิดที่ root ส่งผลทุกบัญชี และการทดสอบต้องทำใน member account (สไลด์ 56)"},{"t":"ทดสอบ SCP จาก management account ให้มากรอบขึ้นก่อนผูกที่ root","why":"SCP ไม่จำกัด management account ผลทดสอบจึงไม่สะท้อนบัญชีสมาชิก"},{"t":"เพิ่ม IAM AdministratorAccess ให้ pipeline role ในทุกบัญชีสมาชิก","why":"IAM ไม่ override Deny ใน SCP จึงไม่แก้"},{"t":"แปลง SCP เป็น IAM policy แล้ววางทีละบัญชีด้วยตนเองทั้งหมด","why":"เสียประโยชน์ group-based management และยังไม่แก้ปัญหาการไม่ทดสอบก่อน"}],"ans":0,"ref":"W14 · สไลด์ 55–56"},{"id":"w14-024","topic":"Billing และ Cost Management","level":"know","story":"","q":"เครื่องมือใดให้ข้อมูลค่าใช้จ่ายละเอียดที่สุดในระดับบรรทัดการใช้งาน (product, usage type, operation, AZ, usage amount)?","opts":[{"t":"AWS Cost Explorer","why":"แสดงกราฟและจัดกลุ่มตามมิติเพื่อดูแนวโน้ม ไม่ใช่ข้อมูลดิบรายบรรทัด"},{"t":"AWS Budgets","why":"ตั้งงบและแจ้งเตือน ไม่ใช่ชุดข้อมูลรายละเอียด"},{"t":"AWS Cost and Usage Report (CUR)","why":"สไลด์ 69: CUR แต่ละบรรทัดคือหนึ่งรายการใช้งานพร้อมค่าธรรมเนียม"},{"t":"Billing dashboard","why":"สรุป spend, forecast, สัดส่วนต่อบริการ ระดับภาพรวม"}],"ans":2,"ref":"W14 · สไลด์ 65, 69"},{"id":"w14-025","topic":"Billing และ Cost Management","level":"know","story":"","q":"ข้อมูลใน Cost Explorer มีความหน่วงได้ถึงประมาณเท่าใด?","opts":[{"t":"ได้ถึงประมาณ 1 วัน","why":"สไลด์ 23: ความผิดพลาดของเมื่อวานอาจยังไม่ปรากฏ"},{"t":"ไม่มีความหน่วง เป็น real-time","why":"ไม่จริง ข้อมูลบิลมีความหน่วง"},{"t":"ประมาณ 1 ชั่วโมง","why":"น้อยกว่าที่สไลด์ระบุ"},{"t":"ประมาณ 7 วัน","why":"มากกว่าที่สไลด์ระบุ"}],"ans":0,"ref":"W14 · สไลด์ 23, 67"},{"id":"w14-026","topic":"Billing และ Cost Management","level":"apply","story":"","q":"หน้า Budgets แสดง S3 Usage Bucket: Current 2,978 Req, Forecasted 3,650.16 Req, Budgeted 3,000 Req ข้อใดตีความถูกต้อง?","opts":[{"t":"เกินงบแล้ว เพราะค่า forecast สูงกว่าค่า budget ที่ตั้งไว้ในหน้านี้","why":"forecast คือค่าคาดการณ์ ค่าจริงปัจจุบัน 2,978 ยังต่ำกว่า 3,000"},{"t":"เป็น cost budget หน่วย USD ที่ใช้ติดตามค่าใช้จ่ายรายเดือน","why":"หน่วยเป็นจำนวน request จึงเป็นงบแบบ usage"},{"t":"Budgets จะบล็อก request ส่วนที่เกิน 3,000 ให้อัตโนมัติทันที","why":"โดยค่าเริ่มต้น Budgets เตือนอย่างเดียวไม่หยุดการใช้งาน"},{"t":"usage budget ที่ยังไม่เกิน แต่ forecast จะเกิน จึงใช้ forecasted alert ได้","why":"Current < Budgeted แต่ Forecasted > Budgeted และงบเป็นหน่วย Req (สไลด์ 68, 22)"}],"ans":3,"ref":"W14 · สไลด์ 22, 68"},{"id":"w14-027","topic":"Billing และ Cost Management","level":"scen","story":"บัญชี dev มีงบรายเดือน $5,000 โดยปกติใช้ประมาณ $20/วัน วันที่ 3 ของเดือนมี NAT gateway ที่ถูกกำหนดค่าผิดทำให้ค่าใช้จ่ายขึ้นเป็น $90/วัน ซึ่งยังห่างจากเกณฑ์ actual 80% มาก","q":"กลไกใดตรวจพบการพุ่งผิดปกตินี้ได้เร็วที่สุดโดยไม่ต้องรอใกล้เกณฑ์งบ?","opts":[{"t":"Actual threshold ที่ 80% ของงบรายเดือนซึ่งต้องรอให้ใช้จริงถึงเกณฑ์","why":"ต้องรอจนใช้จริงถึง $4,000 เงินถูกใช้ไปแล้วมาก"},{"t":"ตรวจ Cost and Usage Report ด้วยตนเองทุกต้นเดือนเพื่อดูแนวโน้ม","why":"ช้ามาก และเป็นการวิเคราะห์ย้อนหลังด้วยคน ไม่ใช่การแจ้งเตือน"},{"t":"ตั้ง budget action ให้ลบ NAT gateway ทุกตัวเมื่อค่าใช้จ่ายพุ่ง","why":"ไม่ใช่การตรวจจับ และการลบอัตโนมัติอาจทำ production ล่ม (สไลด์ 22)"},{"t":"Cost Anomaly Detection ที่แจ้งเมื่อรูปแบบพุ่งผิดปกติ แม้ยังไม่เกินงบ","why":"สไลด์ 22: anomaly detection เตือนแม้ยังไม่เกินงบ"}],"ans":3,"ref":"W14 · สไลด์ 22"},{"id":"w14-028","topic":"Billing และ Cost Management","level":"scen","story":"เช้าวันจันทร์ทีมสงสัยว่ามีคนเปิด GPU instance 20 เครื่องทิ้งไว้ตั้งแต่คืนวันอาทิตย์ แต่ Cost Explorer แสดงค่าใช้จ่ายของวันอาทิตย์และวันจันทร์ปกติ","q":"ควรสรุปและตรวจอย่างไร?","opts":[{"t":"สรุปว่าไม่มีค่าใช้จ่ายเพิ่ม เพราะกราฟของ Cost Explorer ไม่พุ่งขึ้น","why":"ข้อมูลหน่วงได้ ค่าของเมื่อวานอาจยังไม่ปรากฏ"},{"t":"รอครบ 7 วันให้ Cost Explorer แสดงข้อมูลครบแล้วจึงค่อยตรวจสอบ","why":"เสียค่า instance ที่รันอยู่ต่อเนื่องระหว่างรอ ทั้งที่ตรวจ console ได้ทันที"},{"t":"ถือว่ากราฟอาจหน่วง (ได้ถึงราว 1 วัน) จึงตรวจ console ของ EC2/EBS/NAT โดยตรง","why":"สไลด์ 23: อย่าพึ่งหน้าบิลอย่างเดียวในการหาทรัพยากรที่ลืม"},{"t":"ใช้ AWS Pricing Calculator ดูค่าใช้จ่ายจริงของเมื่อวานแทนการตรวจ","why":"Pricing Calculator ประมาณค่าก่อนสร้าง ไม่ใช่เครื่องมือดูค่าใช้จ่ายจริง"}],"ans":2,"ref":"W14 · สไลด์ 23, 36, 67"},{"id":"w14-029","topic":"Support plans","level":"know","story":"","q":"แผน AWS Support ใดที่ให้ response time ระดับ Critical เป้าหมาย 15 นาที?","opts":[{"t":"Business","why":"Business เริ่มที่ Urgent 1 ชั่วโมง ไม่มีระดับ Critical"},{"t":"Enterprise","why":"ตารางสไลด์ 74: Critical 15 นาทีมีเฉพาะ Enterprise (24/7)"},{"t":"Developer","why":"Developer ทำงานเวลาทำการ และรองรับเพียง Normal/Low"},{"t":"Basic","why":"Basic ไม่มี case support ทางเทคนิค"}],"ans":1,"ref":"W14 · สไลด์ 73–74"},{"id":"w14-030","topic":"Support plans","level":"apply","story":"","q":"ข้อใดจับคู่บริการ/เครื่องมือกับหน้าที่ผิด ตามสไลด์ 72?","opts":[{"t":"Technical Account Manager (TAM): proactive guidance","why":"ถูก ตามสไลด์ 72"},{"t":"AWS Support Concierge: ช่วยด้านบัญชีและบิลลิ่ง","why":"ถูก ตามสไลด์ 72"},{"t":"AWS Trusted Advisor: ตรวจสภาพบัญชีเทียบแนวปฏิบัติที่ดี เช่น cost optimization, security","why":"ถูก (เพิ่มเติม) ตามหมวดตรวจที่ระบุในสไลด์ 72"},{"t":"AWS Trusted Advisor: ผู้เชี่ยวชาญเฉพาะบัญชีที่ให้คำแนะนำเชิงรุกรายบุคคล","why":"ผิด: นั่นคือบทบาทของ Technical Account Manager (TAM) ส่วน Trusted Advisor ตรวจบัญชีเทียบ best practices"}],"ans":3,"ref":"W14 · สไลด์ 72"},{"id":"w14-031","topic":"Support plans","level":"apply","story":"","q":"ธุรกิจรัน production workload ต้องการให้ AWS ตอบเคส Urgent ภายใน 1 ชั่วโมงแบบ 24/7 แต่ไม่ต้องการ severity Critical แผนที่ต่ำที่สุดที่ตรงเงื่อนไขคืออะไร?","opts":[{"t":"Business","why":"ตาราง: Business (24/7) Urgent 1 ชั่วโมง; Developer ไม่มี Urgent"},{"t":"Developer","why":"ทำงานเฉพาะเวลาทำการและรองรับเพียง Normal 12 ชม./Low 24 ชม."},{"t":"Basic","why":"ไม่มี case support ทางเทคนิค"},{"t":"Enterprise","why":"ตอบ Urgent 1 ชั่วโมงเท่ากัน แต่เกินความต้องการ เพราะ Critical และบริการเชิงรุกไม่จำเป็น"}],"ans":0,"ref":"W14 · สไลด์ 73–74"},{"id":"w14-032","topic":"Support plans","level":"scen","story":"ระบบชำระเงินของบริษัทเป็น mission-critical หากล่ม 03:00 ต้องได้การตอบกลับครั้งแรกจาก AWS ภายใน 15 นาที และต้องการ TAM ให้คำแนะนำเชิงรุก ผู้บริหารเข้าใจว่า 15 นาทีคือเวลาที่ปัญหาจะถูกแก้เสร็จ","q":"ควรเลือกแผนและแก้ความเข้าใจอย่างไร?","opts":[{"t":"Enterprise โดยชี้แจงว่า 15 นาทีคือเป้าการตอบครั้งแรก ไม่ใช่เวลาแก้ปัญหา","why":"Critical 15 นาทีมีเฉพาะ Enterprise ซึ่งมี TAM (สไลด์ 72, 74)"},{"t":"Business เพราะให้บริการ 24/7 และตอบเคสสำคัญได้เร็วเพียงพอแล้ว","why":"Business ไม่มี Critical (เริ่มที่ Urgent 1 ชั่วโมง) และ TAM เป็นสิทธิ์ระดับ Enterprise"},{"t":"Developer เพราะประหยัดที่สุดและตอบเคส Critical นอกเวลาทำการได้","why":"Developer ไม่ครอบคลุม 24/7 และไม่มีระดับ Critical"},{"t":"Basic พร้อมใช้ discussion forums เป็นช่องทางขอความช่วยเหลือหลัก","why":"Basic ไม่มี case support ทางเทคนิค ไม่เหมาะกับงาน mission-critical"}],"ans":0,"ref":"W14 · สไลด์ 73–74"},{"id":"w14-033","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"apply","story":"","q":"ข้อใดผิดเกี่ยวกับวิธีแก้ปัญหา 6 ขั้นในสไลด์ 77?","opts":[{"t":"ควรถามว่า What changed? เพราะเหตุขัดข้องส่วนใหญ่ตามหลังการเปลี่ยนแปลง","why":"ถูก ตามขั้น 2: deploy, config, certificate, traffic spike"},{"t":"Bisect โดยตรวจกลางเส้นทางแล้วแบ่งครึ่งซ้ำ ทำให้การค้นหาเป็น O(log n) ตามจำนวนชั้น","why":"ถูก ตามขั้น 3"},{"t":"สมมติฐานควรมีสาเหตุเดียวและมีหลักฐานที่พิสูจน์ว่าผิดได้ (falsifiable)","why":"ถูก ตามขั้น 4"},{"t":"เมื่อสงสัยหลายจุด ควรแก้ทุกจุดพร้อมกันเพื่อให้อาการหายเร็วที่สุด","why":"ผิด: ต้อง change one thing เพราะเปลี่ยนหลายอย่างพร้อมกันเกิด confounding variables และไม่รู้สาเหตุ"}],"ans":3,"ref":"W14 · สไลด์ 77"},{"id":"w14-034","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"know","story":"","q":"การเชื่อมต่อไปยังพอร์ตหนึ่งตอบกลับทันทีว่า Connection refused อาการนี้ชี้ไปที่อะไรมากที่สุด?","opts":[{"t":"security group หรือ NACL ทิ้ง packet เงียบ ๆ ระหว่างทางไปโฮสต์","why":"การ drop ทำให้เงียบและ timeout ไม่ใช่ refused ทันที"},{"t":"DNS ไม่สามารถ resolve ชื่อของโฮสต์ปลายทางได้ตั้งแต่ต้น","why":"ถ้า DNS ล้มเหลว จะเป็น Name not resolved ก่อนส่ง packet ใด ๆ"},{"t":"ถึงโฮสต์แล้ว แต่ไม่มี process listen พอร์ตนั้น","why":"refused มาจาก TCP RST ของปลายทาง แปลว่า packet ไปถึงแล้ว (สไลด์ 80)"},{"t":"load balancer ไม่มี target ที่อยู่ในสถานะ healthy เหลืออยู่เลย","why":"อาการนั้นคือ HTTP 503 จาก load balancer ไม่ใช่ TCP refused"}],"ans":2,"ref":"W14 · สไลด์ 80"},{"id":"w14-035","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"know","story":"","q":"เครื่องมือใดตอบคำถามว่า packet ถึงไหม และผ่านหรือถูกปฏิเสธ (ACCEPT/REJECT) ที่ระดับ subnet/interface?","opts":[{"t":"AWS CloudTrail","why":"ตอบว่าใครเปลี่ยนอะไรเมื่อไร ไม่ใช่สถานะ packet"},{"t":"VPC Flow Logs","why":"ตามตารางสไลด์ 79: ตัวอย่างคือ REJECT บนพอร์ต 443 ที่ subnet"},{"t":"CloudWatch Logs","why":"ตอบว่าแอปพูดว่าอะไร (log ของแอป)"},{"t":"ALB access logs","why":"ตอบว่า load balancer เห็นและตอบอะไร เช่น target_status_code ไม่ใช่การปฏิเสธ packet ที่ subnet"}],"ans":1,"ref":"W14 · สไลด์ 79"},{"id":"w14-036","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"know","story":"","q":"Load balancer ตอบ HTTP 503 Service Unavailable โดย access log ระบุว่าไม่มี target ควรตรวจอะไรเป็นอันดับแรก?","opts":[{"t":"ความเร็วของ query ในฐานข้อมูล","why":"เป็นแนวทางของ 504 ที่ target รับแล้วแต่ตอบช้า"},{"t":"health check ของ target group","why":"503 หมายถึง load balancer ไม่มี target ที่ healthy (สไลด์ 80)"},{"t":"record และ TTL ของ hosted zone","why":"เป็นของอาการ Name not resolved ซึ่งเกิดก่อนถึง load balancer"},{"t":"response ที่ผิดรูปแบบจาก app และ log ของ app","why":"เป็นแนวทางของ 502 ที่ load balancer ถึง target แล้วได้ response ผิด"}],"ans":1,"ref":"W14 · สไลด์ 79–80"},{"id":"w14-037","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"apply","story":"","q":"จากเครื่อง app ใน private subnet ทดสอบไปยัง 10.0.2.15 (ฐานข้อมูล): nc พอร์ต 6379 ตอบ Connection refused ทันที ส่วน nc พอร์ต 5432 ค้างจนหมดเวลา โดยเส้นทางเครือข่ายเดียวกัน ข้อสรุปใดเหมาะสมที่สุดสำหรับพอร์ต 5432?","opts":[{"t":"route table ของ subnet ต้นทางไม่มีเส้นทางไปยัง 10.0.2.15 เลย","why":"ถ้าไม่มี route พอร์ต 6379 ก็ต้อง timeout เช่นกัน แต่กลับได้ refused"},{"t":"ชื่อ DNS ของโฮสต์ฐานข้อมูลถูกกำหนดไว้ผิดในระบบ resolver","why":"ทดสอบด้วย IP โดยตรงจึงไม่เกี่ยวกับ DNS"},{"t":"service ฐานข้อมูลไม่ได้รัน จึงควร restart ที่พอร์ต 5432 ก่อน","why":"ถ้าไม่มี listener จะ refused ทันทีเหมือน 6379 ไม่ใช่ค้าง"},{"t":"เส้นทางถึงโฮสต์แล้ว (6379 ถึง) จึงสงสัย SG หรือ NACL ที่ drop เฉพาะ 5432","why":"timeout = มีตัวกรอง drop เงียบ ส่วน refused พิสูจน์ว่า route และโฮสต์ถึงได้"}],"ans":3,"ref":"W14 · สไลด์ 78, 80"},{"id":"w14-038","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"apply","story":"","q":"ผู้ใช้เปิดเว็บแล้วได้ HTTP 503 จากชื่อโดเมน การ resolve DNS สำเร็จ และ curl ไปที่ load balancer ได้ response ตอบกลับมา ระบบมีลำดับ DNS > Route table > NACL > Security group > Load balancer > Instance+app > Cache/DB ตามหลัก bisect ปัญหาอยู่ฝั่งใดของเส้นทาง และควรไปต่ออย่างไร?","opts":[{"t":"ฝั่งหลัง load balancer: ตรวจ health ของ target และ app","why":"เข้าถึง load balancer ได้ ปัญหาจึงอยู่ทางขวา (สไลด์ 78) และ 503 ชี้ไปที่ health check"},{"t":"ฝั่งซ้าย: ตรวจ DNS record ของโดเมนก่อนเพราะเป็นด่านแรกสุด","why":"DNS resolve สำเร็จและ request ถึง LB แล้ว ฝั่งซ้ายผ่านการทดสอบ"},{"t":"ฝั่งซ้าย: เปิดกฎ inbound ของ NACL ที่อยู่หน้า load balancer","why":"request ถึง load balancer แล้ว แปลว่า NACL/SG ก่อน LB ไม่ได้บล็อก"},{"t":"ตรวจทุกชั้นพร้อมกันโดยเปิดทุก console ของบริการที่เกี่ยวข้อง","why":"ขัดกับหลักเลือกเครื่องมือที่ตอบคำถามของกล่องที่กำลังทดสอบ"}],"ans":0,"ref":"W14 · สไลด์ 78, 80"},{"id":"w14-039","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"scen","story":"เวลา 02:11 CloudTrail บันทึกว่า IAM user หนึ่งลบ security group rule ที่อนุญาต health check จาก ALB ไปยัง target เวลา 02:14 CloudWatch แสดง HealthyHostCount เหลือ 0 และ ALB ตอบ 503 ไม่มี deploy ในช่วงนั้น","q":"ขั้นตอนใดสอดคล้องกับวิธีแก้ปัญหาที่ดีที่สุด?","opts":[{"t":"สมมติฐานเดียว: การลบ rule ทำให้ health check ล้มเหลว คืน rule อย่างเดียวแล้วยืนยันผล","why":"ใช้ What changed + one hypothesis + change one thing + verify/record (สไลด์ 77, 79)"},{"t":"restart ทุก instance และคืน rule พร้อมกันเพื่อให้ระบบกลับมาเร็วที่สุด","why":"เปลี่ยนหลายอย่างพร้อมกัน ไม่รู้ว่าอะไรแก้ได้ และ restart ไม่เกี่ยวกับสาเหตุ"},{"t":"สรุปว่าเป็นบั๊กของ ALB เพราะช่วงเวลา 3 นาทีน่าจะไม่เกี่ยวข้องกัน","why":"ลำดับเวลาชี้เหตุและผลชัดเจน การโทษ ALB ไม่มีหลักฐานรองรับ"},{"t":"เพิ่มจำนวน target เพื่อให้มี healthy host เหลือมากขึ้นกว่าเดิม","why":"target ใหม่ก็ถูกบล็อก health check ด้วย rule เดิม ไม่แก้ต้นเหตุ"}],"ans":0,"ref":"W14 · สไลด์ 77, 79"},{"id":"w14-040","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"scen","story":"หลัง deploy เมื่อ 01:50 ผู้ใช้ได้ HTTP 504 หลังรอ 30 วินาทีเฉพาะ /register ส่วนหน้าอื่นปกติ ALB ถึง target ได้และ health check ผ่าน CloudWatch แสดง latency ของ endpoint นั้นสูง","q":"ควรตรวจสิ่งใดต่อ?","opts":[{"t":"ตรวจ NACL ว่าตกกฎ ephemeral port ขาตอบกลับของ subnet หรือไม่","why":"packet ไปถึง target และ health check ผ่าน การ drop ของ NACL ให้อาการอื่น และไม่เลือกเฉพาะ path"},{"t":"แก้ DNS record ของโดเมนและลด TTL ให้สั้นลงเพื่อให้มีผลเร็ว","why":"DNS ทำงานปกติ ไม่เช่นนั้นผู้ใช้จะไม่ถึง ALB"},{"t":"ตรวจแอปและ downstream ของ /register เช่น query ที่เปลี่ยนใน deploy","why":"504 = target รับแล้วแต่ตอบช้าเกิน (สไลด์ 80) และมี change เป็นเบาะแส"},{"t":"เปลี่ยน health check interval ของ target group ให้ถี่ขึ้นกว่าเดิม","why":"health check ผ่านอยู่แล้ว และ 504 ไม่ได้มาจาก target ที่ unhealthy"}],"ans":2,"ref":"W14 · สไลด์ 77, 80"},{"id":"w14-041","topic":"Troubleshooting (วิธีการ/เครื่องมือ/อาการ)","level":"scen","story":"แอปใน private subnet ล็อก Connection refused ที่ 10.0.3.20:6379 ทันที Security group ของ cache อนุญาต 6379 จาก SG ของแอป และ Reachability Analyzer รายงานว่าเข้าถึงได้ ก่อนหน้านี้ทีมเพิ่งเปลี่ยน/สร้าง cache node ใหม่","q":"สาเหตุที่น่าจะเป็นมากที่สุด?","opts":[{"t":"ไม่มี process listen ที่ IP/พอร์ตนั้น เช่น แอปชี้ endpoint ของ node เก่า","why":"refused แปลว่าถึงโฮสต์แล้วแต่ไม่มี listener (สไลด์ 80)"},{"t":"NACL ไม่อนุญาต ephemeral port ในขากลับของ subnet ฝั่ง cache","why":"การถูก drop จะค้าง/timeout ไม่ใช่ refused ทันที"},{"t":"route table ไม่มีเส้นทางไปยัง subnet ที่ cache node ใหม่อยู่","why":"ไม่มี route จะ timeout และ Reachability Analyzer รายงานว่าเข้าถึงได้"},{"t":"security group ของ cache ต้องเพิ่ม rule outbound ให้ครบถ้วน","why":"SG ปล่อยตอบกลับเอง (stateful) และ SG ที่ drop จะทำให้ timeout ไม่ใช่ refused"}],"ans":0,"ref":"W14 · สไลด์ 79–80"},{"id":"w14-042","topic":"NACL vs Security group","level":"know","story":"","q":"ข้อใดจับคู่ขอบเขตการใช้งานและ state ของ Security group และ Network ACL ถูกต้อง?","opts":[{"t":"SG: ผูกกับทั้ง subnet และเป็น stateless; NACL: ผูกกับ instance และเป็น stateful","why":"สลับกันทั้งขอบเขตและ state"},{"t":"SG: ผูกกับ network interface, stateful; NACL: ผูกกับ subnet, stateless","why":"ตามตารางสไลด์ 81"},{"t":"SG: ผูกกับ network interface และเป็น stateless; NACL: ผูกกับ subnet และเป็น stateful","why":"สลับ state: SG เป็น stateful และ NACL เป็น stateless"},{"t":"SG และ NACL ผูกกับ network interface ของ instance และเป็น stateful ทั้งคู่","why":"NACL ผูกที่ทั้ง subnet และเป็น stateless"}],"ans":1,"ref":"W14 · สไลด์ 81"},{"id":"w14-043","topic":"NACL vs Security group","level":"know","story":"","q":"คุณสมบัติใดมีเฉพาะ Network ACL เมื่อเทียบกับ Security group?","opts":[{"t":"สถานะ stateful ที่ตอบกลับได้เองอัตโนมัติโดยไม่ต้องมี rule","why":"เป็นคุณสมบัติของ Security group"},{"t":"ค่าเริ่มต้นที่ deny inbound ทั้งหมดเมื่อสร้างใหม่ทันที","why":"เป็นค่าเริ่มต้นของ Security group (default NACL allow ทั้งหมด)"},{"t":"การมีเฉพาะกฎแบบ allow เท่านั้นโดยไม่มีกฎแบบ deny","why":"เป็นลักษณะของ Security group"},{"t":"กฎ deny ที่มีเลขลำดับ ตรงรายการแรกชนะ","why":"NACL รองรับทั้ง allow และ deny พร้อมลำดับ ส่วน SG มีแต่ allow"}],"ans":3,"ref":"W14 · สไลด์ 81"},{"id":"w14-044","topic":"NACL vs Security group","level":"apply","story":"","q":"ข้อใดเกี่ยวกับค่าเริ่มต้นของ Security group และ NACL ผิด?","opts":[{"t":"Security group ที่สร้างใหม่ deny inbound ทั้งหมดโดยค่าเริ่มต้น","why":"ถูก ตามสไลด์ 81"},{"t":"Default NACL ปฏิเสธ inbound ทั้งหมดจนกว่าจะเพิ่ม allow rule","why":"ผิด: default NACL allow ทั้งหมด (custom NACL ต่างหากที่เริ่ม deny ทั้งหมด)"},{"t":"Custom NACL ที่สร้างเองเริ่มต้น deny ทั้งหมด","why":"ถูก (เพิ่มเติม) ตามหมายเหตุในสไลด์ 81"},{"t":"Security group มีแต่กฎ allow ไม่มีกฎ deny","why":"ถูก ตามสไลด์ 81"}],"ans":1,"ref":"W14 · สไลด์ 81"},{"id":"w14-045","topic":"NACL vs Security group","level":"apply","story":"","q":"ไคลเอนต์ 203.0.113.7:51234 เชื่อมต่อ HTTPS ไปยังเซิร์ฟเวอร์ 10.0.1.10:443 ใน subnet ที่ใช้ NACL แบบ stateless และ inbound 443 ถูกอนุญาตแล้ว กฎใดจำเป็นสำหรับ reply?","opts":[{"t":"Outbound TCP ไปยัง destination port 443 ของไคลเอนต์ที่เชื่อมต่อเข้ามา","why":"reply ไม่ได้ไปที่พอร์ต 443 แต่ไปที่พอร์ตชั่วคราวของไคลเอนต์"},{"t":"Outbound TCP ไป destination port ช่วง ephemeral (1024–65535) สู่ไคลเอนต์","why":"reply มี destination port เป็น 51234 ไม่ใช่ 443 และ NACL ต้องมีกฎแต่ละทิศ"},{"t":"Inbound TCP ไป destination port ช่วง 1024–65535 ของ subnet เซิร์ฟเวอร์","why":"กฎนี้ควบคุม request ที่เข้ามา ไม่ใช่ reply ที่ออกจาก subnet"},{"t":"ไม่ต้องมีกฎเพิ่ม เพราะ Security group ปล่อย reply ให้อยู่แล้วโดยปริยาย","why":"NACL ประเมินแยกจาก SG และเป็น stateless จึงยังบล็อก reply ได้"}],"ans":1,"ref":"W14 · สไลด์ 81–82"},{"id":"w14-046","topic":"NACL vs Security group","level":"apply","story":"","q":"NACL ของ subnet เว็บมี inbound rule 90: DENY ALL จาก 203.0.113.0/24 และ rule 100: ALLOW TCP 443 จาก 0.0.0.0/0 (outbound ephemeral เปิดแล้ว) ไคลเอนต์ 203.0.113.7 เชื่อมต่อ TCP 443 จะเกิดอะไรขึ้น?","opts":[{"t":"ถูกปฏิเสธ เพราะ rule 90 ถูกประเมินก่อนและตรงรายการแรก","why":"NACL ประเมินตามเลขลำดับ ตรงรายการแรกชนะ (สไลด์ 81)"},{"t":"ผ่าน เพราะ rule 100 ระบุพอร์ต 443 ซึ่งเจาะจงกว่า rule 90 ที่ deny","why":"NACL ไม่ใช้ความเจาะจง ใช้ลำดับเลขและตรงรายการแรก"},{"t":"ผ่าน เพราะ allow ที่เลขลำดับท้ายกว่า override deny ที่มาก่อนได้","why":"ไม่มีการ override กฎแรกที่ตรงชนะทันที"},{"t":"ผ่าน เพราะ NACL เป็น stateful จึงไม่ตรวจ request ขาเข้าทุกครั้ง","why":"NACL เป็น stateless และตรวจ request ทุกครั้ง"}],"ans":0,"ref":"W14 · สไลด์ 81"},{"id":"w14-047","topic":"NACL vs Security group","level":"scen","story":"เว็บเซิร์ฟเวอร์อยู่หลัง security group ที่อนุญาต TCP 443 จาก 0.0.0.0/0 ทีมความปลอดภัยพบว่า 198.51.100.9 ยิงคำขอผิดปกติ และต้องการบล็อก IP นี้เพียงรายเดียวโดยไม่กระทบผู้ใช้อื่น","q":"วิธีใดทำได้ตรงจุด?","opts":[{"t":"เพิ่ม deny rule สำหรับ IP นั้นลงใน security group ของเว็บเซิร์ฟเวอร์","why":"Security group มีแต่กฎ allow ไม่รองรับ deny"},{"t":"ลบ rule 443 ออกจาก security group เพื่อตัดการเข้าถึงทั้งหมดไปก่อน","why":"บล็อกผู้ใช้ทุกคน ไม่ใช่เฉพาะ IP ที่ต้องการ"},{"t":"เพิ่ม outbound deny ไปยัง 198.51.100.9 ใน NACL เพียงอย่างเดียว","why":"คำขอ inbound ยังเข้าถึงเซิร์ฟเวอร์ได้ การ deny outbound ไม่ใช่การบล็อก request ขาเข้า"},{"t":"เพิ่ม inbound DENY จาก 198.51.100.9/32 ใน NACL ที่เลขลำดับต่ำกว่า rule allow","why":"SG มี deny ไม่ได้ จึงใช้ NACL และต้องวางก่อน allow เพราะตรงรายการแรกชนะ"}],"ans":3,"ref":"W14 · สไลด์ 81"},{"id":"w14-048","topic":"NACL vs Security group","level":"scen","story":"ทีมสร้าง custom NACL สำหรับ DB subnet (10.0.2.0/24) มี inbound allow TCP 5432 จาก 10.0.1.0/24 และ outbound allow TCP 5432 ไป 10.0.1.0/24 Security group ของ DB อนุญาต 5432 จาก SG ของแอปแล้ว แต่แอปเชื่อมต่อ timeout","q":"แก้อย่างไรให้ถูกต้องที่สุด?","opts":[{"t":"เปลี่ยน security group ของ DB ให้ทำงานแบบ stateless ในการตรวจ reply","why":"SG เป็น stateful เสมอ ตั้งค่าเปลี่ยนไม่ได้ และไม่ใช่ต้นเหตุ"},{"t":"เพิ่ม inbound allow TCP 1024–65535 บน NACL ของ DB subnet เพิ่มเติม","why":"เป็นกฎของ request ขาเข้า ไม่ใช่ reply ขาออก"},{"t":"เพิ่ม outbound allow TCP 1024–65535 ไป 10.0.1.0/24 สำหรับ reply ไปยัง ephemeral port","why":"NACL stateless ต้องอนุญาต reply เองตาม port ปลายทางที่เป็น ephemeral"},{"t":"เปิด outbound TCP 5432 ไป 0.0.0.0/0 เพื่อให้ reply ออกได้ทุกที่","why":"reply ไม่ได้ใช้พอร์ตปลายทาง 5432 จึงไม่ช่วย และเปิดกว้างเกินจำเป็น"}],"ans":2,"ref":"W14 · สไลด์ 81–82"}]};